INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M2-1-u4-C1','math',2,1,'u4',2,'길이를 본떠 비교하기 — 직접 맞댈 수 없는 길이를 끈·종이띠로 본뜨고, 한쪽 끝(시작점)을 맞추어 더 긴 것·더 짧은 것을 가리기',ARRAY['2수03-01']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M2-1-u4-C2','math',2,1,'u4',3,'여러 가지 단위로 재기 — 뼘·클립·지우개 같은 단위를 빈틈없이 이어 옮기며 몇 번인지 세고, 단위가 길수록 잰 횟수가 적음을 알기',ARRAY['2수03-01']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M2-1-u4-C3','math',2,1,'u4',4,'1 cm 알기 — 사람마다 다른 단위의 불편함을 알고, 누가 재어도 같은 1 cm(1 센티미터)를 쓰고 읽으며, 1 cm가 몇 번이면 몇 cm인지 말하기',ARRAY['2수03-02']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M2-1-u4-C4','math',2,1,'u4',5,'자로 길이 재기 — 자의 숫자가 1 cm가 몇 번인지를 나타냄을 알고, 물건 한쪽 끝을 눈금 0에 맞추어 다른 끝의 눈금을 읽거나, 0에 없으면 1 cm 칸을 세기',ARRAY['2수03-02']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M2-1-u4-C5','math',2,1,'u4',6,'약 몇 cm로 나타내기 — 끝이 눈금 사이에 있으면 더 가까운 눈금의 숫자를 읽고 앞에 「약」을 붙이며, 약 몇 cm가 같아도 실제 길이는 다를 수 있음을 알기',ARRAY['2수03-02']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M2-1-u4-C6','math',2,1,'u4',7,'길이 어림하기 — 엄지손톱(약 1 cm)·가운뎃손가락(약 5 cm)·한 뼘(약 10 cm) 같은 기준과 견주어 길이를 약 몇 cm로 어림하고, 자로 재어 어림과 견주기',ARRAY['2수03-02']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-1-u4-X01','math',2,'u4',ARRAY['M2-1-u4-C1']::text[],'본뜬 끈·종이띠의 한쪽 끝을 맞추지 않고 비교한다 — 오른쪽 끝이 더 나온 것을 더 길다고 함','왼쪽 끝(시작점)을 한 줄에 맞춘 뒤 오른쪽에 남는 쪽을 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-1-u4-X02','math',2,'u4',ARRAY['M2-1-u4-C1']::text[],'맞댈 수 없으면 길이를 비교할 수 없다고 여기거나, 굵기·놓인 높이·구부러진 모양으로 길이를 판단한다','끈으로 본떠 곧게 편 뒤 끝을 맞춰 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-1-u4-X03','math',2,'u4',ARRAY['M2-1-u4-C2','M2-1-u4-C3']::text[],'단위를 빈틈없이 이어 옮기지 않는다 — 띄우거나 겹쳐 세어 횟수가 하나 많거나 적음','단위 끝에 손가락을 대고 그 자리에서 다음 단위를 시작하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-1-u4-X04','math',2,'u4',ARRAY['M2-1-u4-C2']::text[],'단위가 길수록 잰 횟수가 많다고 거꾸로 여긴다','긴 걸음과 작은 걸음으로 같은 복도를 걷는 장면을 떠올리기 — 긴 걸음은 적게 걸어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-1-u4-X05','math',2,'u4',ARRAY['M2-1-u4-C2','M2-1-u4-C6']::text[],'단위가 다른데 잰 횟수(또는 숫자)만 보고 길이를 비교하거나 횟수를 그대로 더한다','「무엇으로 쟀지?」 단위를 먼저 확인하고, 단위가 같을 때만 횟수로 비교') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-1-u4-X06','math',2,'u4',ARRAY['M2-1-u4-C2','M2-1-u4-C3']::text[],'뼘 같은 단위는 누가 재도 같고, 1 cm는 사람마다 다르다고 거꾸로 여긴다','내 뼘과 선생님 뼘을 대어 보기 — 1 cm는 모두가 약속한 같은 길이') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-1-u4-X07','math',2,'u4',ARRAY['M2-1-u4-C3']::text[],'cm를 바르게 읽고 쓰지 못하거나 다른 단위와 헷갈린다 — 1 cm를 1 미터·1 칸으로 읽음','cm는 「센티미터」 — 쓸 때는 소문자 c와 m를 붙여서') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-1-u4-X08','math',2,'u4',ARRAY['M2-1-u4-C4','M2-1-u4-C5']::text[],'물건 끝이 0에 있지 않은데 끝 눈금의 숫자를 그대로 길이로 읽는다','시작 눈금부터 1 cm 칸을 손가락으로 하나씩 세기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-1-u4-X09','math',2,'u4',ARRAY['M2-1-u4-C3','M2-1-u4-C4']::text[],'1 cm 칸 대신 눈금(선)의 수를 세어 길이를 1 크게 말한다','선이 아니라 선과 선 사이의 칸을 세기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-1-u4-X10','math',2,'u4',ARRAY['M2-1-u4-C4']::text[],'자의 시작점을 0이 아니라 1로 여겨 1에 맞추거나 1부터 센다','자의 맨 처음 숫자 0에 물건 끝을 맞추기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-1-u4-X11','math',2,'u4',ARRAY['M2-1-u4-C5']::text[],'끝이 눈금 사이에 있을 때 더 먼 눈금이나 늘 큰 쪽(작은 쪽) 숫자를 읽는다','끝에서 양쪽 눈금까지 거리를 견주어 더 가까운 쪽') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-1-u4-X12','math',2,'u4',ARRAY['M2-1-u4-C5','M2-1-u4-C6']::text[],'눈금에 딱 맞지 않거나 어림한 길이를 「약」 없이 정확한 길이처럼 말한다','딱 맞지 않으면 「약」, 어림해도 「약」') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-1-u4-X13','math',2,'u4',ARRAY['M2-1-u4-C5']::text[],'약 몇 cm가 같으면 실제 길이도 똑같다고 여긴다','약 5 cm인 두 종이띠를 맞대어 보기 — 조금 다를 수 있어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-1-u4-X14','math',2,'u4',ARRAY['M2-1-u4-C6']::text[],'1·5·10 cm의 양감이 없어 터무니없이 어림하거나, 어림은 실제와 꼭 같아야 한다고 여긴다','엄지손톱 약 1 cm·가운뎃손가락 약 5 cm·한 뼘 약 10 cm를 기준으로 몇 번쯤인지') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M2-1-u4-X15','math',2,'u4',ARRAY['M2-1-u4-C1','M2-1-u4-C2','M2-1-u4-C4','M2-1-u4-C5','M2-1-u4-C6']::text[],'묻는 말을 거꾸로 읽는다 — 가장 짧은↔가장 긴, 잘못된↔바른, 차이↔합','물음의 「짧은·잘못된·차이」에 동그라미를 치고 답을 넣어 다시 읽기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_L02_basic#1','math',2,1,'u4','L02','g2_1_math_u4_L02_basic','lesson_basic','M2-1-u4-C1',1,'mc','auto','종이띠로 두 나뭇잎의 길이를 본떠 왼쪽 끝을 맞추었어요. 더 긴 잎은 어느 것인가요?',ARRAY['M2-1-u4-X01']::text[],true,'{"seq":1,"concept":"M2-1-u4-C1","difficulty":1,"kind":"mc","stem":"종이띠로 두 나뭇잎의 길이를 본떠 왼쪽 끝을 맞추었어요. 더 긴 잎은 어느 것인가요?","options":[{"t":"나","correct":true},{"t":"가","mis":"M2-1-u4-X01"},{"t":"길이가 같아요","mis":"M2-1-u4-X01"}],"explanation":["왼쪽 끝을 맞추었으니 오른쪽이 더 나온 쪽이 더 길어요.","나 종이띠가 더 많이 나와 있어요.","본뜬 종이띠로 견주면 잎을 따지 않아도 돼요."],"asset":{"type":"len_bars","rows":[{"label":"가","len":5},{"label":"나","len":7}]},"variant_rule":{"alt":[{"stem":"끈으로 두 막대의 길이를 본떠 왼쪽 끝을 맞추었어요. 더 짧은 막대는 어느 것인가요?","options":[{"t":"가","correct":true},{"t":"나","mis":"M2-1-u4-X15"},{"t":"길이가 같아요","mis":"M2-1-u4-X01"}],"explanation":["왼쪽 끝을 맞추었으니 덜 나온 쪽이 더 짧아요.","가 끈이 덜 나와 있어요.","「짧은」을 묻는지 다시 읽어요."],"asset":{"type":"len_bars","rows":[{"label":"가","len":4},{"label":"나","len":8}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_L02_basic#2','math',2,1,'u4','L02','g2_1_math_u4_L02_basic','lesson_basic','M2-1-u4-C1',1,'mc','auto','나뭇가지에 달린 두 나뭇잎처럼 맞댈 수 없는 길이를 비교하는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['M2-1-u4-X02']::text[],true,'{"seq":2,"concept":"M2-1-u4-C1","difficulty":1,"kind":"mc","stem":"나뭇가지에 달린 두 나뭇잎처럼 맞댈 수 없는 길이를 비교하는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"종이띠로 길이를 본떠 한쪽 끝을 맞춰 비교해요","correct":true},{"t":"눈으로 대충 보고 정해요","mis":"M2-1-u4-X02"},{"t":"맞댈 수 없으니 비교할 수 없어요","mis":"M2-1-u4-X02"}],"explanation":["맞댈 수 없으면 종이띠나 끈으로 길이를 본떠요.","본뜬 것끼리 한쪽 끝을 맞춰 비교해요.","이렇게 하면 직접 맞대지 않아도 비교할 수 있어요."],"variant_rule":{"alt":[{"stem":"책상의 긴 쪽과 높이처럼 맞대기 어려운 길이를 비교하는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"끈으로 각각 본떠 한쪽 끝을 맞춰 비교해요","correct":true},{"t":"높이가 더 높아 보이니 높이가 길어요","mis":"M2-1-u4-X02"},{"t":"책상을 눕힐 수 없으니 비교할 수 없어요","mis":"M2-1-u4-X02"}],"explanation":["끈으로 긴 쪽과 높이를 각각 본떠요.","두 끈의 한쪽 끝을 맞춰 남는 쪽이 더 길어요.","보이는 느낌만으로 정하지 않아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_L02_basic#3','math',2,1,'u4','L02','g2_1_math_u4_L02_basic','lesson_basic','M2-1-u4-C1',1,'ox','auto','본뜬 종이띠를 비교할 때는 한쪽 끝을 맞춰야 해요.',ARRAY['M2-1-u4-X01']::text[],true,'{"seq":3,"concept":"M2-1-u4-C1","difficulty":1,"kind":"ox","stem":"본뜬 종이띠를 비교할 때는 한쪽 끝을 맞춰야 해요.","answer":"O","reason_options":[{"t":"끝을 맞춰야 남는 쪽을 보고 더 긴 것을 알 수 있으니까","correct":true},{"t":"오른쪽 끝만 보면 되니까","mis":"M2-1-u4-X01"}],"mis":"M2-1-u4-X01","explanation":["한쪽 끝(시작점)을 똑같이 맞춰요.","그래야 더 나온 쪽이 더 긴 것이에요.","끝을 맞추지 않으면 잘못 비교할 수 있어요."],"variant_rule":{"alt":[{"stem":"본뜬 종이띠는 끝을 맞추지 않고 비교해도 정확해요.","answer":"X","reason_options":[{"t":"시작점이 다르면 더 나온 쪽이 꼭 더 긴 것은 아니니까","correct":true},{"t":"종이띠 길이는 그대로이니까","mis":"M2-1-u4-X01"}],"explanation":["시작점이 다르면 눈이 속아요.","왼쪽 끝을 맞추어야 정확해요.","맞춘 뒤 남는 쪽을 봐요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_L02_basic#4','math',2,1,'u4','L02','g2_1_math_u4_L02_basic','lesson_basic','M2-1-u4-C1',1,'mc','auto','끈으로 본뜬 세 길이를 왼쪽 끝을 맞춰 놓았어요. 가장 긴 것은 어느 것인가요?',ARRAY['M2-1-u4-X15','M2-1-u4-X01']::text[],true,'{"seq":4,"concept":"M2-1-u4-C1","difficulty":1,"kind":"mc","stem":"끈으로 본뜬 세 길이를 왼쪽 끝을 맞춰 놓았어요. 가장 긴 것은 어느 것인가요?","options":[{"t":"파랑","correct":true},{"t":"빨강","mis":"M2-1-u4-X15"},{"t":"노랑","mis":"M2-1-u4-X01"}],"explanation":["왼쪽 끝을 맞추었으니 가장 많이 나온 것이 가장 길어요.","파랑이 가장 많이 나와 있어요.","빨강은 가장 짧아요."],"asset":{"type":"len_bars","rows":[{"label":"빨강","len":3},{"label":"노랑","len":6},{"label":"파랑","len":9}]},"variant_rule":{"alt":[{"stem":"끈으로 본뜬 세 길이를 왼쪽 끝을 맞춰 놓았어요. 가장 짧은 것은 어느 것인가요?","options":[{"t":"노랑","correct":true},{"t":"빨강","mis":"M2-1-u4-X15"},{"t":"파랑","mis":"M2-1-u4-X01"}],"explanation":["왼쪽 끝을 맞추었으니 가장 덜 나온 것이 가장 짧아요.","노랑이 가장 덜 나와 있어요.","「짧은」을 묻는지 다시 읽어요."],"asset":{"type":"len_bars","rows":[{"label":"빨강","len":10},{"label":"노랑","len":4},{"label":"파랑","len":7}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_L02_basic#5','math',2,1,'u4','L02','g2_1_math_u4_L02_basic','lesson_basic','M2-1-u4-C1',2,'mc','auto','두 종이띠를 놓았어요. 더 긴 것은 어느 것인가요? (칸 하나의 길이는 같아요.)',ARRAY['M2-1-u4-X01']::text[],true,'{"seq":5,"concept":"M2-1-u4-C1","difficulty":2,"kind":"mc","stem":"두 종이띠를 놓았어요. 더 긴 것은 어느 것인가요? (칸 하나의 길이는 같아요.)","options":[{"t":"가","correct":true},{"t":"나","mis":"M2-1-u4-X01"},{"t":"길이가 같아요","mis":"M2-1-u4-X01"}],"explanation":["두 종이띠의 시작점이 달라요.","칸을 세면 가는 7칸, 나는 5칸이에요.","오른쪽 끝이 더 나왔다고 더 긴 것이 아니에요."],"asset":{"type":"len_bars","rows":[{"label":"가","len":7},{"label":"나","len":5,"off":3}],"grid":true},"variant_rule":{"alt":[{"stem":"두 끈을 놓았어요. 더 긴 것은 어느 것인가요? (칸 하나의 길이는 같아요.)","options":[{"t":"나","correct":true},{"t":"가","mis":"M2-1-u4-X01"},{"t":"길이가 같아요","mis":"M2-1-u4-X01"}],"explanation":["두 끈의 시작점이 달라요.","칸을 세면 가는 4칸, 나는 6칸이에요.","끝이 나란해 보여도 시작점부터 견줘요."],"asset":{"type":"len_bars","rows":[{"label":"가","len":4,"off":3},{"label":"나","len":6,"off":1}],"grid":true}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_L02_basic#6','math',2,1,'u4','L02','g2_1_math_u4_L02_basic','lesson_basic','M2-1-u4-C1',2,'mc','auto','세 종이띠를 왼쪽 끝을 맞춰 놓았어요. 짧은 것부터 차례대로 쓴 것은 어느 것인가요?',ARRAY['M2-1-u4-X15','M2-1-u4-X01']::text[],true,'{"seq":6,"concept":"M2-1-u4-C1","difficulty":2,"kind":"mc","stem":"세 종이띠를 왼쪽 끝을 맞춰 놓았어요. 짧은 것부터 차례대로 쓴 것은 어느 것인가요?","options":[{"t":"나 → 다 → 가","correct":true},{"t":"가 → 다 → 나","mis":"M2-1-u4-X15"},{"t":"나 → 가 → 다","mis":"M2-1-u4-X01"}],"explanation":["왼쪽 끝을 맞추었으니 덜 나온 것이 짧아요.","나가 가장 짧고, 다, 가 순서로 길어져요.","「짧은 것부터」인지 다시 읽어요."],"asset":{"type":"len_bars","rows":[{"label":"가","len":10},{"label":"나","len":3},{"label":"다","len":6}]},"variant_rule":{"alt":[{"stem":"세 종이띠를 왼쪽 끝을 맞춰 놓았어요. 긴 것부터 차례대로 쓴 것은 어느 것인가요?","options":[{"t":"다 → 가 → 나","correct":true},{"t":"나 → 가 → 다","mis":"M2-1-u4-X15"},{"t":"가 → 다 → 나","mis":"M2-1-u4-X01"}],"explanation":["왼쪽 끝을 맞추었으니 많이 나온 것이 길어요.","다가 가장 길고, 가, 나 순서예요.","「긴 것부터」인지 다시 읽어요."],"asset":{"type":"len_bars","rows":[{"label":"가","len":6},{"label":"나","len":2},{"label":"다","len":9}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_L02_basic#7','math',2,1,'u4','L02','g2_1_math_u4_L02_basic','lesson_basic','M2-1-u4-C1',2,'sa','auto','끈으로 본뜬 네 길이 가운데 가장 짧은 것의 기호를 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M2-1-u4-C1","difficulty":2,"kind":"sa","stem":"끈으로 본뜬 네 길이 가운데 가장 짧은 것의 기호를 쓰세요.","answer":["라"],"explanation":["왼쪽 끝이 맞추어져 있어요.","가장 덜 나온 라가 가장 짧아요.","「짧은」을 묻는지 확인해요."],"asset":{"type":"len_bars","rows":[{"label":"가","len":8},{"label":"나","len":5},{"label":"다","len":10},{"label":"라","len":3}]},"variant_rule":{"alt":[{"stem":"끈으로 본뜬 네 길이 가운데 가장 긴 것의 기호를 쓰세요.","answer":["나"],"explanation":["왼쪽 끝이 맞추어져 있어요.","가장 많이 나온 나가 가장 길어요.","「긴」을 묻는지 확인해요."],"asset":{"type":"len_bars","rows":[{"label":"가","len":6},{"label":"나","len":11},{"label":"다","len":4},{"label":"라","len":8}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_L02_basic#8','math',2,1,'u4','L02','g2_1_math_u4_L02_basic','lesson_basic','M2-1-u4-C1',2,'ox','auto','구부러진 끈을 그대로 놓고 비교해도 길이를 바르게 알 수 있어요.',ARRAY['M2-1-u4-X02']::text[],true,'{"seq":8,"concept":"M2-1-u4-C1","difficulty":2,"kind":"ox","stem":"구부러진 끈을 그대로 놓고 비교해도 길이를 바르게 알 수 있어요.","answer":"X","reason_options":[{"t":"끈을 곧게 펴고 끝을 맞춰야 정확하니까","correct":true},{"t":"구부러져도 길이가 보이니까","mis":"M2-1-u4-X02"}],"mis":"M2-1-u4-X02","explanation":["구부러진 끈은 짧아 보여요.","곧게 편 뒤 한쪽 끝을 맞추어 비교해요.","모양에 속지 않아요."],"variant_rule":{"alt":[{"stem":"굵은 막대는 가는 막대보다 언제나 더 길어요.","answer":"X","reason_options":[{"t":"길이는 굵기가 아니라 한쪽 끝을 맞춰 견줘야 아니까","correct":true},{"t":"굵으면 크니까 길이도 기니까","mis":"M2-1-u4-X02"}],"explanation":["굵기와 길이는 달라요.","한쪽 끝을 맞추어 남는 쪽을 봐요.","굵어도 짧을 수 있어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_L02_basic#9','math',2,1,'u4','L02','g2_1_math_u4_L02_basic','lesson_basic','M2-1-u4-C1',2,'mc','auto','놀이 기구 앞에 키 제한선만큼 끈을 걸어 두었어요. 끈보다 키가 큰 사람만 탈 수 있어요. 하람이는 끈보다 크고, 지우는 끈보다 작아요. 탈 수 있는 사람은 누구인가요?',ARRAY['M2-1-u4-X15','M2-1-u4-X01']::text[],true,'{"seq":9,"concept":"M2-1-u4-C1","difficulty":2,"kind":"mc","stem":"놀이 기구 앞에 키 제한선만큼 끈을 걸어 두었어요. 끈보다 키가 큰 사람만 탈 수 있어요. 하람이는 끈보다 크고, 지우는 끈보다 작아요. 탈 수 있는 사람은 누구인가요?","options":[{"t":"하람","correct":true},{"t":"지우","mis":"M2-1-u4-X15"},{"t":"둘 다","mis":"M2-1-u4-X01"}],"explanation":["끈은 키 제한선을 본뜬 것이에요.","끈보다 큰 하람이만 탈 수 있어요.","지우는 끈보다 작아서 탈 수 없어요."],"variant_rule":{"alt":[{"stem":"끈으로 문의 폭을 본떴어요. 끈보다 짧은 상자만 문을 지나갈 수 있어요. 빨간 상자는 끈보다 길고, 파란 상자는 끈보다 짧아요. 지나갈 수 있는 상자는 어느 것인가요?","options":[{"t":"파란 상자","correct":true},{"t":"빨간 상자","mis":"M2-1-u4-X15"},{"t":"둘 다","mis":"M2-1-u4-X01"}],"explanation":["끈은 문의 폭을 본뜬 것이에요.","끈보다 짧은 파란 상자만 지나갈 수 있어요.","빨간 상자는 끈보다 길어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_L02_basic#10','math',2,1,'u4','L02','g2_1_math_u4_L02_basic','lesson_basic','M2-1-u4-C1',3,'error','auto','친구들이 본뜬 종이띠를 비교했어요. 잘못 비교한 친구는 누구인가요?',ARRAY['M2-1-u4-X01','M2-1-u4-X15']::text[],true,'{"seq":10,"concept":"M2-1-u4-C1","difficulty":3,"kind":"error","stem":"친구들이 본뜬 종이띠를 비교했어요. 잘못 비교한 친구는 누구인가요?","options":[{"t":"민호 — 왼쪽 끝을 맞추지 않고 오른쪽이 더 나온 것을 더 길다고 했어요","correct":true,"mis_target":"M2-1-u4-X01"},{"t":"소율 — 왼쪽 끝을 맞춘 뒤 남는 쪽을 보았어요","mis":"M2-1-u4-X15"},{"t":"태민 — 끈을 곧게 펴서 끝을 맞추었어요","mis":"M2-1-u4-X15"}],"explanation":["민호는 시작점을 맞추지 않았어요.","시작점이 다르면 더 나온 쪽이 더 긴 것이 아닐 수 있어요.","소율이와 태민이는 바르게 비교했어요."],"variant_rule":{"alt":[{"stem":"친구들이 길이를 비교했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하린 — 「나무 높이는 맞댈 수 없으니 비교할 수 없어.」","correct":true,"mis_target":"M2-1-u4-X02"},{"t":"준우 — 「끈으로 본떠서 비교하면 돼.」","mis":"M2-1-u4-X15"},{"t":"서윤 — 「본뜬 끈은 한쪽 끝을 맞춰야 해.」","mis":"M2-1-u4-X15"}],"explanation":["맞댈 수 없어도 본떠서 비교할 수 있어요.","하린이가 잘못 말했어요.","준우와 서윤이는 바르게 말했어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_L02_challenge#1','math',2,1,'u4','L02','g2_1_math_u4_L02_challenge','lesson_challenge','M2-1-u4-C1',2,'mc','auto','끈으로 본뜬 네 길이를 왼쪽 끝을 맞춰 놓았어요. 가장 짧은 것은 어느 것인가요?',ARRAY['M2-1-u4-X15','M2-1-u4-X01']::text[],false,'{"seq":1,"concept":"M2-1-u4-C1","difficulty":2,"kind":"mc","stem":"끈으로 본뜬 네 길이를 왼쪽 끝을 맞춰 놓았어요. 가장 짧은 것은 어느 것인가요?","options":[{"t":"다","correct":true},{"t":"나","mis":"M2-1-u4-X15"},{"t":"가","mis":"M2-1-u4-X01"}],"explanation":["왼쪽 끝이 맞추어져 있어요.","가장 덜 나온 다가 가장 짧아요.","나는 가장 길어요."],"asset":{"type":"len_bars","rows":[{"label":"가","len":6},{"label":"나","len":11},{"label":"다","len":3},{"label":"라","len":8}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_L02_challenge#2','math',2,1,'u4','L02','g2_1_math_u4_L02_challenge','lesson_challenge','M2-1-u4-C1',2,'mc','auto','책상의 긴 쪽과 높이를 끈으로 본떠 왼쪽 끝을 맞추었어요. 어느 쪽이 더 긴가요?',ARRAY['M2-1-u4-X01']::text[],false,'{"seq":2,"concept":"M2-1-u4-C1","difficulty":2,"kind":"mc","stem":"책상의 긴 쪽과 높이를 끈으로 본떠 왼쪽 끝을 맞추었어요. 어느 쪽이 더 긴가요?","options":[{"t":"긴 쪽","correct":true},{"t":"높이","mis":"M2-1-u4-X01"},{"t":"길이가 같아요","mis":"M2-1-u4-X01"}],"explanation":["왼쪽 끝을 맞추었어요.","「긴 쪽」 끈이 더 많이 나와 있어요.","그래서 책상은 긴 쪽이 높이보다 길어요."],"asset":{"type":"len_bars","rows":[{"label":"긴 쪽","len":10},{"label":"높이","len":7}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_L02_challenge#3','math',2,1,'u4','L02','g2_1_math_u4_L02_challenge','lesson_challenge','M2-1-u4-C1',3,'mc','auto','세 종이띠를 놓았어요. 가장 긴 것은 어느 것인가요? (칸 하나의 길이는 같아요.)',ARRAY['M2-1-u4-X01']::text[],false,'{"seq":3,"concept":"M2-1-u4-C1","difficulty":3,"kind":"mc","stem":"세 종이띠를 놓았어요. 가장 긴 것은 어느 것인가요? (칸 하나의 길이는 같아요.)","options":[{"t":"가","correct":true},{"t":"다","mis":"M2-1-u4-X01"},{"t":"나","mis":"M2-1-u4-X01"}],"explanation":["세 종이띠의 시작점이 모두 달라요.","칸을 세면 가 8칸, 나 6칸, 다 7칸이에요.","오른쪽 끝이 가장 많이 나온 다가 가장 긴 것이 아니에요."],"asset":{"type":"len_bars","rows":[{"label":"가","len":8},{"label":"나","len":6,"off":1},{"label":"다","len":7,"off":3}],"grid":true}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_L02_challenge#4','math',2,1,'u4','L02','g2_1_math_u4_L02_challenge','lesson_challenge','M2-1-u4-C1',3,'mc','auto','세 끈을 놓았어요. 긴 것부터 차례대로 쓴 것은 어느 것인가요? (칸 하나의 길이는 같아요.)',ARRAY['M2-1-u4-X01','M2-1-u4-X15']::text[],false,'{"seq":4,"concept":"M2-1-u4-C1","difficulty":3,"kind":"mc","stem":"세 끈을 놓았어요. 긴 것부터 차례대로 쓴 것은 어느 것인가요? (칸 하나의 길이는 같아요.)","options":[{"t":"나 → 가 → 다","correct":true},{"t":"다 → 나 → 가","mis":"M2-1-u4-X01"},{"t":"다 → 가 → 나","mis":"M2-1-u4-X15"}],"explanation":["시작점이 달라 칸을 세어야 해요.","가 6칸, 나 7칸, 다 4칸이에요.","그래서 나 → 가 → 다 순서예요."],"asset":{"type":"len_bars","rows":[{"label":"가","len":6,"off":2},{"label":"나","len":7},{"label":"다","len":4,"off":4}],"grid":true}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_L02_challenge#5','math',2,1,'u4','L02','g2_1_math_u4_L02_challenge','lesson_challenge','M2-1-u4-C1',3,'ox','auto','두 종이띠의 오른쪽 끝이 같은 곳에 있으면 두 종이띠의 길이는 같아요.',ARRAY['M2-1-u4-X01']::text[],false,'{"seq":5,"concept":"M2-1-u4-C1","difficulty":3,"kind":"ox","stem":"두 종이띠의 오른쪽 끝이 같은 곳에 있으면 두 종이띠의 길이는 같아요.","answer":"X","reason_options":[{"t":"왼쪽 끝(시작점)도 같아야 길이가 같다고 할 수 있으니까","correct":true},{"t":"오른쪽 끝만 보면 되니까","mis":"M2-1-u4-X01"}],"mis":"M2-1-u4-X01","explanation":["오른쪽 끝이 같아도 시작점이 다르면 길이가 달라요.","시작점이 앞에 있는 것이 더 길어요.","양쪽 끝을 모두 살펴봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_L02_challenge#6','math',2,1,'u4','L02','g2_1_math_u4_L02_challenge','lesson_challenge','M2-1-u4-C1',3,'error','auto','친구들이 길이를 비교하는 방법을 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M2-1-u4-X02','M2-1-u4-X15']::text[],false,'{"seq":6,"concept":"M2-1-u4-C1","difficulty":3,"kind":"error","stem":"친구들이 길이를 비교하는 방법을 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"지안 — 「나무 높이와 교실 문 높이는 맞댈 수 없으니 비교할 수 없어.」","correct":true,"mis_target":"M2-1-u4-X02"},{"t":"도윤 — 「끈으로 둘 다 본뜨면 비교할 수 있어.」","mis":"M2-1-u4-X15"},{"t":"은솔 — 「본뜬 끈은 한쪽 끝을 맞추고 비교해.」","mis":"M2-1-u4-X15"}],"explanation":["맞댈 수 없어도 끈으로 본뜨면 비교할 수 있어요.","지안이가 잘못 말했어요.","도윤이와 은솔이는 바르게 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_L02_challenge#7','math',2,1,'u4','L02','g2_1_math_u4_L02_challenge','lesson_challenge','M2-1-u4-C1',3,'mc','auto','끈으로 길이를 본떠 비교했더니 가는 나보다 길고, 나는 다보다 길었어요. 가장 짧은 것은 어느 것인가요?',ARRAY['M2-1-u4-X15','M2-1-u4-X01']::text[],false,'{"seq":7,"concept":"M2-1-u4-C1","difficulty":3,"kind":"mc","stem":"끈으로 길이를 본떠 비교했더니 가는 나보다 길고, 나는 다보다 길었어요. 가장 짧은 것은 어느 것인가요?","options":[{"t":"다","correct":true},{"t":"가","mis":"M2-1-u4-X15"},{"t":"나","mis":"M2-1-u4-X01"}],"explanation":["가가 나보다 길고, 나가 다보다 길어요.","그러니 가 → 나 → 다 순서로 짧아져요.","가장 짧은 것은 다예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_L02_challenge#8','math',2,1,'u4','L02','g2_1_math_u4_L02_challenge','lesson_challenge','M2-1-u4-C1',4,'mc','auto','키 제한선을 끈으로 본떴어요. 끈보다 키가 큰 사람만 탈 수 있어요. 끈과 견주어 보니 서아는 끈보다 크고, 민지는 끈과 같고, 현우는 끈보다 작았어요. 탈 수 있는 사람을 모두 고른 것은 어느 것인가요?',ARRAY['M2-1-u4-X01','M2-1-u4-X15']::text[],false,'{"seq":8,"concept":"M2-1-u4-C1","difficulty":4,"kind":"mc","stem":"키 제한선을 끈으로 본떴어요. 끈보다 키가 큰 사람만 탈 수 있어요. 끈과 견주어 보니 서아는 끈보다 크고, 민지는 끈과 같고, 현우는 끈보다 작았어요. 탈 수 있는 사람을 모두 고른 것은 어느 것인가요?","options":[{"t":"서아","correct":true},{"t":"서아, 민지","mis":"M2-1-u4-X01"},{"t":"민지, 현우","mis":"M2-1-u4-X15"}],"explanation":["끈보다 「큰」 사람만 탈 수 있어요.","민지는 끈과 같아서 크지 않아요.","그래서 서아만 탈 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_L02_challenge#9','math',2,1,'u4','L02','g2_1_math_u4_L02_challenge','lesson_challenge','M2-1-u4-C1',4,'essay','teacher','교실 창문의 폭과 칠판의 폭처럼 맞댈 수 없는 두 길이를 비교하는 방법을 차례대로 써 보세요.','{}'::text[],false,'{"seq":9,"concept":"M2-1-u4-C1","difficulty":4,"kind":"essay","stem":"교실 창문의 폭과 칠판의 폭처럼 맞댈 수 없는 두 길이를 비교하는 방법을 차례대로 써 보세요.","answer_guide":{"answer":"예: ① 끈으로 창문 폭만큼 본떠 자른다. ② 다른 끈으로 칠판 폭만큼 본떠 자른다. ③ 두 끈의 한쪽 끝을 맞추어 남는 쪽이 더 긴 것이다.","scoring_points":["끈·종이띠로 두 길이를 본떴는가","한쪽 끝을 맞추어 비교했는가","남는 쪽이 더 길다고 결론을 썼는가"]},"explanation":["본뜨기.","한쪽 끝 맞추기.","남는 쪽이 더 길어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_L02_challenge#10','math',2,1,'u4','L02','g2_1_math_u4_L02_challenge','lesson_challenge','M2-1-u4-C1',4,'essay','teacher','그림처럼 놓인 두 종이띠를 보고 민호가 「나가 더 길어.」라고 했어요. 민호의 생각이 맞는지 까닭과 함께 써 보세요. (칸 하나의 길이는 같아요.)','{}'::text[],false,'{"seq":10,"concept":"M2-1-u4-C1","difficulty":4,"kind":"essay","stem":"그림처럼 놓인 두 종이띠를 보고 민호가 「나가 더 길어.」라고 했어요. 민호의 생각이 맞는지 까닭과 함께 써 보세요. (칸 하나의 길이는 같아요.)","answer_guide":{"answer":"예: 맞지 않다. 두 종이띠의 시작점이 다르다. 칸을 세면 가는 8칸, 나는 6칸이라 가가 더 길다.","scoring_points":["민호의 생각이 틀렸다고 판단했는가","시작점이 다르다는 것을 짚었는가","칸을 세어 가가 더 길다고 밝혔는가"]},"explanation":["시작점이 달라요.","가 8칸, 나 6칸이에요.","가가 더 길어요."],"asset":{"type":"len_bars","rows":[{"label":"가","len":8},{"label":"나","len":6,"off":4}],"grid":true}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_L03_basic#1','math',2,1,'u4','L03','g2_1_math_u4_L03_basic','lesson_basic','M2-1-u4-C2',1,'sa','auto','막대의 길이는 클립으로 몇 번일까요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M2-1-u4-C2","difficulty":1,"kind":"sa","stem":"막대의 길이는 클립으로 몇 번일까요? 숫자로 쓰세요.","explanation":["클립을 빈틈없이 이어 놓은 것을 세어요.","클립으로 4번이에요.","겹치거나 띄우지 않고 이어서 세어요."],"variant_rule":{"cm":{"ask":"unit"}},"answer":["4"],"asset":{"type":"ruler","len":8,"label":"막대","mode":"unit","unit":"📎","size":2}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_L03_basic#2','math',2,1,'u4','L03','g2_1_math_u4_L03_basic','lesson_basic','M2-1-u4-C2',1,'mc','auto','같은 길이를 잴 때 단위의 길이가 길수록 잰 횟수는 어떻게 될까요?',ARRAY['M2-1-u4-X04','M2-1-u4-X05']::text[],true,'{"seq":2,"concept":"M2-1-u4-C2","difficulty":1,"kind":"mc","stem":"같은 길이를 잴 때 단위의 길이가 길수록 잰 횟수는 어떻게 될까요?","options":[{"t":"적어져요","correct":true},{"t":"많아져요","mis":"M2-1-u4-X04"},{"t":"언제나 똑같아요","mis":"M2-1-u4-X05"}],"explanation":["긴 단위는 한 번에 많이 재요.","그래서 잰 횟수가 적어요.","짧은 단위로 재면 횟수가 많아요."],"variant_rule":{"alt":[{"stem":"같은 길이를 잴 때 단위의 길이가 짧을수록 잰 횟수는 어떻게 될까요?","options":[{"t":"많아져요","correct":true},{"t":"적어져요","mis":"M2-1-u4-X04"},{"t":"언제나 똑같아요","mis":"M2-1-u4-X05"}],"explanation":["짧은 단위는 한 번에 조금씩 재요.","그래서 잰 횟수가 많아요.","긴 단위로 재면 횟수가 적어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_L03_basic#3','math',2,1,'u4','L03','g2_1_math_u4_L03_basic','lesson_basic','M2-1-u4-C2',1,'mc','auto','종이띠의 길이는 지우개로 몇 번일까요?',ARRAY['M2-1-u4-X03']::text[],true,'{"seq":3,"concept":"M2-1-u4-C2","difficulty":1,"kind":"mc","stem":"종이띠의 길이는 지우개로 몇 번일까요?","explanation":["지우개를 빈틈없이 이어 놓은 것을 세어요.","지우개로 3번이에요.","겹치거나 띄우지 않고 이어서 세어요."],"variant_rule":{"cm":{"ask":"unit"}},"options":[{"t":"3번","correct":true},{"t":"4번","mis":"M2-1-u4-X03"},{"t":"2번","mis":"M2-1-u4-X03"}],"asset":{"type":"ruler","len":9,"label":"종이띠","mode":"unit","unit":"🟫","size":3}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_L03_basic#4','math',2,1,'u4','L03','g2_1_math_u4_L03_basic','lesson_basic','M2-1-u4-C2',1,'ox','auto','단위로 길이를 잴 때는 빈틈없이 이어서 옮기며 세어요.',ARRAY['M2-1-u4-X03']::text[],true,'{"seq":4,"concept":"M2-1-u4-C2","difficulty":1,"kind":"ox","stem":"단위로 길이를 잴 때는 빈틈없이 이어서 옮기며 세어요.","answer":"O","reason_options":[{"t":"띄우거나 겹치면 횟수가 달라지니까","correct":true},{"t":"조금 띄어 놓아도 횟수는 같으니까","mis":"M2-1-u4-X03"}],"mis":"M2-1-u4-X03","explanation":["단위 끝에서 바로 다음 단위를 시작해요.","띄우면 횟수가 적게, 겹치면 많게 나와요.","빈틈없이 이어서 세어요."],"variant_rule":{"alt":[{"stem":"클립을 조금씩 겹쳐 놓고 세어도 바르게 잰 거예요.","answer":"X","reason_options":[{"t":"겹치면 횟수가 실제보다 많아지니까","correct":true},{"t":"클립 수만 세면 되니까","mis":"M2-1-u4-X03"}],"explanation":["겹치면 같은 곳을 두 번 재요.","그래서 횟수가 많아져요.","빈틈없이, 겹치지 않게 이어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_L03_basic#5','math',2,1,'u4','L03','g2_1_math_u4_L03_basic','lesson_basic','M2-1-u4-C2',2,'match','auto','같은 막대를 세 가지 단위로 재었어요. 단위와 잰 횟수를 알맞게 이어 보세요.','{}'::text[],true,'{"seq":5,"concept":"M2-1-u4-C2","difficulty":2,"kind":"match","stem":"같은 막대를 세 가지 단위로 재었어요. 단위와 잰 횟수를 알맞게 이어 보세요.","pairs":[{"l":"가장 긴 단위","r":"2번"},{"l":"중간 길이 단위","r":"4번"},{"l":"가장 짧은 단위","r":"8번"}],"mis":"M2-1-u4-X04","explanation":["같은 길이를 재면 긴 단위일수록 횟수가 적어요.","가장 긴 단위는 2번이에요.","가장 짧은 단위는 8번이에요."],"variant_rule":{"alt":[{"stem":"같은 책상을 세 가지 단위로 재었어요. 단위와 잰 횟수를 알맞게 이어 보세요.","pairs":[{"l":"걸음","r":"2번"},{"l":"뼘","r":"5번"},{"l":"클립","r":"20번"}],"explanation":["걸음이 가장 긴 단위라 횟수가 가장 적어요.","뼘은 중간이에요.","클립이 가장 짧아 횟수가 가장 많아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_L03_basic#6','math',2,1,'u4','L03','g2_1_math_u4_L03_basic','lesson_basic','M2-1-u4-C2',2,'sa','auto','붓의 길이는 블록으로 몇 번일까요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M2-1-u4-C2","difficulty":2,"kind":"sa","stem":"붓의 길이는 블록으로 몇 번일까요? 숫자로 쓰세요.","explanation":["블록을 빈틈없이 이어 놓은 것을 세어요.","블록으로 12번이에요.","겹치거나 띄우지 않고 이어서 세어요."],"variant_rule":{"cm":{"ask":"unit"}},"answer":["12"],"asset":{"type":"ruler","len":12,"label":"붓","mode":"unit","unit":"🧩","size":1}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_L03_basic#7','math',2,1,'u4','L03','g2_1_math_u4_L03_basic','lesson_basic','M2-1-u4-C2',2,'mc','auto','교실 긴 쪽의 길이를 잴 때 가장 편리한 단위는 어느 것인가요?',ARRAY['M2-1-u4-X04']::text[],true,'{"seq":7,"concept":"M2-1-u4-C2","difficulty":2,"kind":"mc","stem":"교실 긴 쪽의 길이를 잴 때 가장 편리한 단위는 어느 것인가요?","options":[{"t":"걸음","correct":true},{"t":"엄지손톱","mis":"M2-1-u4-X04"},{"t":"클립","mis":"M2-1-u4-X04"}],"explanation":["교실 긴 쪽은 아주 길어요.","긴 단위인 걸음으로 재면 횟수가 적어 세기 편해요.","짧은 단위로 재면 너무 많이 세야 해요."],"variant_rule":{"alt":[{"stem":"지우개의 길이를 잴 때 가장 알맞은 단위는 어느 것인가요?","options":[{"t":"블록","correct":true},{"t":"걸음","mis":"M2-1-u4-X04"},{"t":"양팔","mis":"M2-1-u4-X04"}],"explanation":["지우개는 짧아요.","짧은 단위인 블록으로 재야 알맞아요.","걸음이나 양팔은 지우개보다 길어서 잴 수 없어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_L03_basic#8','math',2,1,'u4','L03','g2_1_math_u4_L03_basic','lesson_basic','M2-1-u4-C2',2,'mc','auto','하람이와 지우가 같은 책상을 뼘으로 재었더니 하람이는 6뼘, 지우는 5뼘이었어요. 그 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['M2-1-u4-X06','M2-1-u4-X05']::text[],true,'{"seq":8,"concept":"M2-1-u4-C2","difficulty":2,"kind":"mc","stem":"하람이와 지우가 같은 책상을 뼘으로 재었더니 하람이는 6뼘, 지우는 5뼘이었어요. 그 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"두 사람의 뼘 길이가 달라서예요","correct":true},{"t":"책상의 길이가 바뀌어서예요","mis":"M2-1-u4-X06"},{"t":"지우가 책상을 더 길게 재서예요","mis":"M2-1-u4-X05"}],"explanation":["책상의 길이는 그대로예요.","지우의 뼘이 하람이의 뼘보다 길어서 횟수가 적어요.","사람마다 뼘의 길이가 달라요."],"variant_rule":{"alt":[{"stem":"같은 칠판을 선생님은 8뼘, 도윤이는 11뼘으로 재었어요. 그 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"선생님의 뼘이 도윤이의 뼘보다 길어서예요","correct":true},{"t":"칠판이 줄어들어서예요","mis":"M2-1-u4-X06"},{"t":"도윤이가 더 긴 칠판을 재서예요","mis":"M2-1-u4-X05"}],"explanation":["칠판의 길이는 그대로예요.","뼘이 길면 횟수가 적게 나와요.","사람마다 뼘의 길이가 달라요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_L03_basic#9','math',2,1,'u4','L03','g2_1_math_u4_L03_basic','lesson_basic','M2-1-u4-C2',2,'ox','auto','단위가 짧을수록 잰 횟수도 적어요.',ARRAY['M2-1-u4-X04']::text[],true,'{"seq":9,"concept":"M2-1-u4-C2","difficulty":2,"kind":"ox","stem":"단위가 짧을수록 잰 횟수도 적어요.","answer":"X","reason_options":[{"t":"짧은 단위는 더 여러 번 옮겨야 하니까","correct":true},{"t":"짧은 단위는 작으니까 횟수도 작으니까","mis":"M2-1-u4-X04"}],"mis":"M2-1-u4-X04","explanation":["짧은 단위로 재면 횟수가 많아요.","긴 단위로 재면 횟수가 적어요.","단위의 길이와 횟수는 반대로 움직여요."],"variant_rule":{"alt":[{"stem":"같은 연필을 클립으로 6번, 지우개로 3번 재었다면 지우개가 클립보다 길어요.","answer":"O","reason_options":[{"t":"같은 길이를 더 적은 횟수로 쟀으니 지우개가 긴 단위니까","correct":true},{"t":"횟수가 적으니 지우개가 짧으니까","mis":"M2-1-u4-X04"}],"explanation":["같은 길이를 잴 때 긴 단위가 횟수가 적어요.","지우개로 3번, 클립으로 6번이에요.","그래서 지우개가 더 긴 단위예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_L03_basic#10','math',2,1,'u4','L03','g2_1_math_u4_L03_basic','lesson_basic','M2-1-u4-C2',3,'error','auto','친구들이 단위로 수학책의 길이를 재었어요. 잘못 잰 친구는 누구인가요?',ARRAY['M2-1-u4-X03','M2-1-u4-X15']::text[],true,'{"seq":10,"concept":"M2-1-u4-C2","difficulty":3,"kind":"error","stem":"친구들이 단위로 수학책의 길이를 재었어요. 잘못 잰 친구는 누구인가요?","options":[{"t":"서윤 — 클립을 띄엄띄엄 놓고 세었어요","correct":true,"mis_target":"M2-1-u4-X03"},{"t":"하준 — 클립 끝에 맞춰 다음 클립을 이어 놓았어요","mis":"M2-1-u4-X15"},{"t":"로아 — 겹치지 않게 지우개를 옮기며 세었어요","mis":"M2-1-u4-X15"}],"explanation":["서윤이는 클립 사이를 띄웠어요.","띄우면 횟수가 실제보다 적어요.","하준이와 로아는 빈틈없이 재었어요."],"variant_rule":{"alt":[{"stem":"친구들이 뼘으로 책상을 재었어요. 잘못 잰 친구는 누구인가요?","options":[{"t":"예린 — 뼘을 반쯤 겹치게 옮기며 세었어요","correct":true,"mis_target":"M2-1-u4-X03"},{"t":"현우 — 엄지 끝 자리에서 다음 뼘을 시작했어요","mis":"M2-1-u4-X15"},{"t":"아린 — 빈틈없이 이어서 세었어요","mis":"M2-1-u4-X15"}],"explanation":["예린이는 뼘을 겹쳤어요.","겹치면 횟수가 실제보다 많아요.","현우와 아린이는 바르게 재었어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_L03_challenge#1','math',2,1,'u4','L03','g2_1_math_u4_L03_challenge','lesson_challenge','M2-1-u4-C2',2,'mc','auto','리본의 길이는 클립으로 몇 번일까요?',ARRAY['M2-1-u4-X03']::text[],true,'{"seq":1,"concept":"M2-1-u4-C2","difficulty":2,"kind":"mc","stem":"리본의 길이는 클립으로 몇 번일까요?","explanation":["클립을 빈틈없이 이어 놓은 것을 세어요.","클립으로 5번이에요.","겹치거나 띄우지 않고 이어서 세어요."],"variant_rule":{"cm":{"ask":"unit"}},"options":[{"t":"5번","correct":true},{"t":"6번","mis":"M2-1-u4-X03"},{"t":"4번","mis":"M2-1-u4-X03"}],"asset":{"type":"ruler","len":10,"label":"리본","mode":"unit","unit":"📎","size":2}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_L03_challenge#2','math',2,1,'u4','L03','g2_1_math_u4_L03_challenge','lesson_challenge','M2-1-u4-C2',2,'mc','auto','같은 막대를 지우개로 재었더니 3번이었어요. 지우개보다 짧은 클립으로 재면 잰 횟수는 어떻게 될까요?',ARRAY['M2-1-u4-X04','M2-1-u4-X05']::text[],false,'{"seq":2,"concept":"M2-1-u4-C2","difficulty":2,"kind":"mc","stem":"같은 막대를 지우개로 재었더니 3번이었어요. 지우개보다 짧은 클립으로 재면 잰 횟수는 어떻게 될까요?","options":[{"t":"3번보다 많아요","correct":true},{"t":"3번보다 적어요","mis":"M2-1-u4-X04"},{"t":"똑같이 3번이에요","mis":"M2-1-u4-X05"}],"explanation":["클립은 지우개보다 짧은 단위예요.","짧은 단위로 재면 횟수가 많아요.","그래서 3번보다 많아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_L03_challenge#3','math',2,1,'u4','L03','g2_1_math_u4_L03_challenge','lesson_challenge','M2-1-u4-C2',3,'mc','auto','민호는 책상을 연필로 재어 6번, 지안이는 다른 책상을 뼘으로 재어 4번이었어요. 바르게 말한 것은 어느 것인가요?',ARRAY['M2-1-u4-X05','M2-1-u4-X04']::text[],false,'{"seq":3,"concept":"M2-1-u4-C2","difficulty":3,"kind":"mc","stem":"민호는 책상을 연필로 재어 6번, 지안이는 다른 책상을 뼘으로 재어 4번이었어요. 바르게 말한 것은 어느 것인가요?","options":[{"t":"단위가 달라서 횟수만으로는 어느 책상이 긴지 알 수 없어요","correct":true},{"t":"6번인 민호의 책상이 더 길어요","mis":"M2-1-u4-X05"},{"t":"뼘이 짧으니 지안이의 책상이 더 길어요","mis":"M2-1-u4-X04"}],"explanation":["연필과 뼘은 길이가 다른 단위예요.","단위가 다르면 횟수만 보고 견줄 수 없어요.","같은 단위로 재어야 비교할 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_L03_challenge#4','math',2,1,'u4','L03','g2_1_math_u4_L03_challenge','lesson_challenge','M2-1-u4-C2',3,'mc','auto','같은 클립으로 가 막대는 5번, 나 막대는 7번 재었어요. 더 긴 막대는 어느 것인가요?',ARRAY['M2-1-u4-X04','M2-1-u4-X05']::text[],false,'{"seq":4,"concept":"M2-1-u4-C2","difficulty":3,"kind":"mc","stem":"같은 클립으로 가 막대는 5번, 나 막대는 7번 재었어요. 더 긴 막대는 어느 것인가요?","options":[{"t":"나","correct":true},{"t":"가","mis":"M2-1-u4-X04"},{"t":"길이가 같아요","mis":"M2-1-u4-X05"}],"explanation":["같은 단위로 재었어요.","같은 단위라면 횟수가 많을수록 더 길어요.","나가 7번으로 더 길어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_L03_challenge#5','math',2,1,'u4','L03','g2_1_math_u4_L03_challenge','lesson_challenge','M2-1-u4-C2',3,'ox','auto','같은 단위로 잰다면 잰 횟수가 많은 것이 더 길어요.',ARRAY['M2-1-u4-X05']::text[],false,'{"seq":5,"concept":"M2-1-u4-C2","difficulty":3,"kind":"ox","stem":"같은 단위로 잰다면 잰 횟수가 많은 것이 더 길어요.","answer":"O","reason_options":[{"t":"같은 길이의 단위를 더 여러 번 이었으니까","correct":true},{"t":"단위가 달라도 횟수만 보면 되니까","mis":"M2-1-u4-X05"}],"mis":"M2-1-u4-X05","explanation":["같은 단위끼리는 횟수로 비교할 수 있어요.","횟수가 많을수록 더 길어요.","단위가 다르면 횟수로 비교할 수 없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_L03_challenge#6','math',2,1,'u4','L03','g2_1_math_u4_L03_challenge','lesson_challenge','M2-1-u4-C2',3,'error','auto','친구들이 단위와 횟수에 대해 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M2-1-u4-X04','M2-1-u4-X15']::text[],false,'{"seq":6,"concept":"M2-1-u4-C2","difficulty":3,"kind":"error","stem":"친구들이 단위와 횟수에 대해 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"도윤 — 「블록은 클립보다 짧으니 블록으로 잰 횟수가 더 적어.」","correct":true,"mis_target":"M2-1-u4-X04"},{"t":"하늘 — 「긴 단위로 재면 횟수가 적어.」","mis":"M2-1-u4-X15"},{"t":"지후 — 「단위가 같아야 횟수로 비교할 수 있어.」","mis":"M2-1-u4-X15"}],"explanation":["짧은 단위로 재면 횟수가 더 많아요.","도윤이가 거꾸로 말했어요.","하늘이와 지후는 바르게 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_L03_challenge#7','math',2,1,'u4','L03','g2_1_math_u4_L03_challenge','lesson_challenge','M2-1-u4-C2',3,'sa','auto','풀의 길이는 지우개로 몇 번일까요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M2-1-u4-C2","difficulty":3,"kind":"sa","stem":"풀의 길이는 지우개로 몇 번일까요? 숫자로 쓰세요.","explanation":["지우개를 빈틈없이 이어 놓은 것을 세어요.","지우개로 3번이에요.","겹치거나 띄우지 않고 이어서 세어요."],"variant_rule":{"cm":{"ask":"unit"}},"answer":["3"],"asset":{"type":"ruler","len":9,"label":"풀","mode":"unit","unit":"🟫","size":3}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_L03_challenge#8','math',2,1,'u4','L03','g2_1_math_u4_L03_challenge','lesson_challenge','M2-1-u4-C2',4,'mc','auto','막대 한 개의 길이는 클립 4개만큼이고, 클립 한 개의 길이는 블록 2개만큼이에요. 막대의 길이는 블록으로 몇 번일까요?',ARRAY['M2-1-u4-X05','M2-1-u4-X04']::text[],false,'{"seq":8,"concept":"M2-1-u4-C2","difficulty":4,"kind":"mc","stem":"막대 한 개의 길이는 클립 4개만큼이고, 클립 한 개의 길이는 블록 2개만큼이에요. 막대의 길이는 블록으로 몇 번일까요?","options":[{"t":"8번","correct":true},{"t":"6번","mis":"M2-1-u4-X05"},{"t":"2번","mis":"M2-1-u4-X04"}],"explanation":["클립 한 개가 블록 2번이에요.","클립 4개는 블록 2번이 4번 — 2, 4, 6, 8이에요.","그래서 막대는 블록으로 8번이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_L03_challenge#9','math',2,1,'u4','L03','g2_1_math_u4_L03_challenge','lesson_challenge','M2-1-u4-C2',4,'essay','teacher','친구마다 뼘으로 잰 책상의 길이가 다르게 나왔어요. 그 까닭과 어떻게 하면 모두 같게 잴 수 있을지 써 보세요.','{}'::text[],false,'{"seq":9,"concept":"M2-1-u4-C2","difficulty":4,"kind":"essay","stem":"친구마다 뼘으로 잰 책상의 길이가 다르게 나왔어요. 그 까닭과 어떻게 하면 모두 같게 잴 수 있을지 써 보세요.","answer_guide":{"answer":"예: 사람마다 뼘의 길이가 다르기 때문이다. 모두 같은 길이의 단위(같은 클립이나 자)로 재면 같은 횟수가 나온다.","scoring_points":["뼘의 길이가 사람마다 다르다는 까닭을 썼는가","모두가 같은 단위로 재야 한다고 썼는가","단위와 횟수의 관계가 드러나는가"]},"explanation":["뼘이 달라요.","같은 단위로 재요.","그러면 횟수가 같아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_L03_challenge#10','math',2,1,'u4','L03','g2_1_math_u4_L03_challenge','lesson_challenge','M2-1-u4-C2',4,'essay','teacher','같은 길이를 긴 단위와 짧은 단위로 재면 잰 횟수가 어떻게 다른지 예를 들어 설명해 보세요.','{}'::text[],false,'{"seq":10,"concept":"M2-1-u4-C2","difficulty":4,"kind":"essay","stem":"같은 길이를 긴 단위와 짧은 단위로 재면 잰 횟수가 어떻게 다른지 예를 들어 설명해 보세요.","answer_guide":{"answer":"예: 같은 책상을 걸음으로 재면 2번, 클립으로 재면 20번이다. 긴 단위는 한 번에 많이 재서 횟수가 적고, 짧은 단위는 횟수가 많다.","scoring_points":["긴 단위와 짧은 단위의 예를 들었는가","긴 단위의 횟수가 적다고 썼는가","그 까닭을 설명했는가"]},"explanation":["예 들기.","긴 단위는 횟수가 적어요.","까닭."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_L04_basic#1','math',2,1,'u4','L04','g2_1_math_u4_L04_basic','lesson_basic','M2-1-u4-C3',1,'sa','auto','1 cm가 몇 번일까요? 막대의 길이는 몇 cm일까요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M2-1-u4-C3","difficulty":1,"kind":"sa","stem":"1 cm가 몇 번일까요? 막대의 길이는 몇 cm일까요? 숫자로 쓰세요.","explanation":["1 cm 칸을 하나씩 세면 5칸이에요.","1 cm가 5번이면 5 cm예요.","칸 사이의 선이 아니라 칸을 세어요."],"variant_rule":{"cm":{"ask":"cells"}},"answer":["5"],"asset":{"type":"ruler","len":5,"label":"막대","mode":"cells"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_L04_basic#2','math',2,1,'u4','L04','g2_1_math_u4_L04_basic','lesson_basic','M2-1-u4-C3',1,'mc','auto','뼘으로 길이를 재면 불편한 까닭은 무엇인가요?',ARRAY['M2-1-u4-X06','M2-1-u4-X03']::text[],true,'{"seq":2,"concept":"M2-1-u4-C3","difficulty":1,"kind":"mc","stem":"뼘으로 길이를 재면 불편한 까닭은 무엇인가요?","options":[{"t":"사람마다 뼘의 길이가 달라서","correct":true},{"t":"뼘이 너무 길어서","mis":"M2-1-u4-X06"},{"t":"뼘은 셀 수 없어서","mis":"M2-1-u4-X03"}],"explanation":["내 뼘과 친구 뼘의 길이는 달라요.","그래서 같은 것을 재도 횟수가 달라져요.","누가 재어도 같은 단위가 필요해요."],"variant_rule":{"alt":[{"stem":"누가 재어도 똑같은 단위가 필요한 까닭은 무엇인가요?","options":[{"t":"사람마다 다른 단위로 재면 잰 결과가 서로 달라서","correct":true},{"t":"단위는 길수록 좋아서","mis":"M2-1-u4-X06"},{"t":"횟수를 셀 수 없어서","mis":"M2-1-u4-X03"}],"explanation":["뼘·걸음은 사람마다 달라요.","그래서 같은 길이도 다르게 말하게 돼요.","그래서 1 cm를 약속해 써요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_L04_basic#3','math',2,1,'u4','L04','g2_1_math_u4_L04_basic','lesson_basic','M2-1-u4-C3',1,'mc','auto','1 cm가 몇 번일까요? 종이띠의 길이는 몇 cm일까요?',ARRAY['M2-1-u4-X09','M2-1-u4-X03']::text[],true,'{"seq":3,"concept":"M2-1-u4-C3","difficulty":1,"kind":"mc","stem":"1 cm가 몇 번일까요? 종이띠의 길이는 몇 cm일까요?","explanation":["1 cm 칸을 하나씩 세면 7칸이에요.","1 cm가 7번이면 7 cm예요.","칸 사이의 선이 아니라 칸을 세어요."],"variant_rule":{"cm":{"ask":"cells"}},"options":[{"t":"7 cm","correct":true},{"t":"8 cm","mis":"M2-1-u4-X09"},{"t":"6 cm","mis":"M2-1-u4-X03"}],"asset":{"type":"ruler","len":7,"label":"종이띠","mode":"cells"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_L04_basic#4','math',2,1,'u4','L04','g2_1_math_u4_L04_basic','lesson_basic','M2-1-u4-C3',1,'mc','auto','1 cm는 무엇이라고 읽나요?',ARRAY['M2-1-u4-X07']::text[],true,'{"seq":4,"concept":"M2-1-u4-C3","difficulty":1,"kind":"mc","stem":"1 cm는 무엇이라고 읽나요?","options":[{"t":"1 센티미터","correct":true},{"t":"1 미터","mis":"M2-1-u4-X07"},{"t":"1 칸","mis":"M2-1-u4-X07"}],"explanation":["cm는 「센티미터」라고 읽어요.","1 cm는 1 센티미터예요.","미터는 다른 단위예요."],"variant_rule":{"alt":[{"stem":"「3 센티미터」를 바르게 쓴 것은 어느 것인가요?","options":[{"t":"3 cm","correct":true},{"t":"3 m","mis":"M2-1-u4-X07"},{"t":"3 c","mis":"M2-1-u4-X07"}],"explanation":["센티미터는 cm라고 써요.","3 센티미터는 3 cm예요.","m는 미터, c만 쓰면 안 돼요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_L04_basic#5','math',2,1,'u4','L04','g2_1_math_u4_L04_basic','lesson_basic','M2-1-u4-C3',2,'match','auto','1 cm가 몇 번인지와 길이를 알맞게 이어 보세요.','{}'::text[],true,'{"seq":5,"concept":"M2-1-u4-C3","difficulty":2,"kind":"match","stem":"1 cm가 몇 번인지와 길이를 알맞게 이어 보세요.","pairs":[{"l":"1 cm가 2번","r":"2 cm"},{"l":"1 cm가 4번","r":"4 cm"},{"l":"1 cm가 6번","r":"6 cm"}],"mis":"M2-1-u4-X09","explanation":["1 cm가 2번이면 2 cm예요.","1 cm가 4번이면 4 cm예요.","1 cm가 6번이면 6 cm예요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 1 cm가 몇 번인지와 길이를 알맞게 이어 보세요.","pairs":[{"l":"1 cm가 3번","r":"3 cm"},{"l":"1 cm가 7번","r":"7 cm"},{"l":"1 cm가 10번","r":"10 cm"}],"explanation":["1 cm가 3번이면 3 cm예요.","1 cm가 7번이면 7 cm예요.","1 cm가 10번이면 10 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_L04_basic#6','math',2,1,'u4','L04','g2_1_math_u4_L04_basic','lesson_basic','M2-1-u4-C3',2,'sa','auto','1 cm가 몇 번일까요? 리본의 길이는 몇 cm일까요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M2-1-u4-C3","difficulty":2,"kind":"sa","stem":"1 cm가 몇 번일까요? 리본의 길이는 몇 cm일까요? 숫자로 쓰세요.","explanation":["1 cm 칸을 하나씩 세면 9칸이에요.","1 cm가 9번이면 9 cm예요.","칸 사이의 선이 아니라 칸을 세어요."],"variant_rule":{"cm":{"ask":"cells"}},"answer":["9"],"asset":{"type":"ruler","len":9,"label":"리본","mode":"cells"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_L04_basic#7','math',2,1,'u4','L04','g2_1_math_u4_L04_basic','lesson_basic','M2-1-u4-C3',2,'sa','auto','1 cm가 8번이면 몇 cm일까요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M2-1-u4-C3","difficulty":2,"kind":"sa","stem":"1 cm가 8번이면 몇 cm일까요? 숫자로 쓰세요.","answer":["8"],"explanation":["1 cm가 몇 번인지 세면 길이예요.","1 cm가 8번이면 8 cm예요.","8 센티미터라고 읽어요."],"variant_rule":{"alt":[{"stem":"1 cm가 11번이면 몇 cm일까요? 숫자로 쓰세요.","answer":["11"],"explanation":["1 cm가 몇 번인지 세면 길이예요.","1 cm가 11번이면 11 cm예요.","11 센티미터라고 읽어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_L04_basic#8','math',2,1,'u4','L04','g2_1_math_u4_L04_basic','lesson_basic','M2-1-u4-C3',2,'ox','auto','1 cm는 누가 재어도 똑같은 길이예요.',ARRAY['M2-1-u4-X06']::text[],true,'{"seq":8,"concept":"M2-1-u4-C3","difficulty":2,"kind":"ox","stem":"1 cm는 누가 재어도 똑같은 길이예요.","answer":"O","reason_options":[{"t":"모두가 같은 길이로 약속한 단위이니까","correct":true},{"t":"손 크기에 따라 달라지니까","mis":"M2-1-u4-X06"}],"mis":"M2-1-u4-X06","explanation":["1 cm는 모두가 약속한 길이예요.","그래서 누가 재어도 같아요.","뼘과 달리 사람마다 다르지 않아요."],"variant_rule":{"alt":[{"stem":"1 cm는 사람마다 길이가 달라요.","answer":"X","reason_options":[{"t":"누가 재어도 같은 길이로 약속했으니까","correct":true},{"t":"뼘처럼 사람마다 다르니까","mis":"M2-1-u4-X06"}],"explanation":["1 cm는 누가 재어도 같아요.","사람마다 다른 것은 뼘이에요.","그래서 1 cm로 재면 편리해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_L04_basic#9','math',2,1,'u4','L04','g2_1_math_u4_L04_basic','lesson_basic','M2-1-u4-C3',2,'mc','auto','개미가 1 cm씩 6번 기어갔어요. 개미는 모두 몇 cm 갔을까요?',ARRAY['M2-1-u4-X09','M2-1-u4-X07']::text[],true,'{"seq":9,"concept":"M2-1-u4-C3","difficulty":2,"kind":"mc","stem":"개미가 1 cm씩 6번 기어갔어요. 개미는 모두 몇 cm 갔을까요?","options":[{"t":"6 cm","correct":true},{"t":"7 cm","mis":"M2-1-u4-X09"},{"t":"1 cm","mis":"M2-1-u4-X07"}],"explanation":["1 cm가 6번이에요.","1 cm가 6번이면 6 cm예요.","한 번 간 길이가 아니라 모두 간 길이를 물었어요."],"variant_rule":{"alt":[{"stem":"달팽이가 1 cm씩 9번 기어갔어요. 달팽이는 모두 몇 cm 갔을까요?","options":[{"t":"9 cm","correct":true},{"t":"10 cm","mis":"M2-1-u4-X09"},{"t":"1 cm","mis":"M2-1-u4-X07"}],"explanation":["1 cm가 9번이에요.","1 cm가 9번이면 9 cm예요.","한 번 간 길이가 아니라 모두 간 길이를 물었어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_L04_basic#10','math',2,1,'u4','L04','g2_1_math_u4_L04_basic','lesson_basic','M2-1-u4-C3',3,'error','auto','친구들이 막대의 길이를 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M2-1-u4-X07','M2-1-u4-X15']::text[],true,'{"seq":10,"concept":"M2-1-u4-C3","difficulty":3,"kind":"error","stem":"친구들이 막대의 길이를 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하린 — 1 cm가 5번인 막대를 「5 m」라고 썼어요","correct":true,"mis_target":"M2-1-u4-X07"},{"t":"시우 — 1 cm가 4번인 막대를 「4 cm」라고 썼어요","mis":"M2-1-u4-X15"},{"t":"다은 — 1 cm가 7번인 막대를 「7 센티미터」라고 읽었어요","mis":"M2-1-u4-X15"}],"explanation":["1 cm가 5번이면 5 cm예요.","m는 미터라는 다른 단위예요.","시우와 다은이는 바르게 말했어요."],"variant_rule":{"alt":[{"stem":"친구들이 1 cm 칸으로 나눈 막대의 길이를 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"태민 — 칸 사이의 선을 세어 6칸인 막대를 7 cm라고 했어요","correct":true,"mis_target":"M2-1-u4-X09"},{"t":"지안 — 칸을 세어 8칸인 막대를 8 cm라고 했어요","mis":"M2-1-u4-X15"},{"t":"하준 — 칸을 세어 3칸인 막대를 3 cm라고 했어요","mis":"M2-1-u4-X15"}],"explanation":["선이 아니라 칸을 세어야 해요.","6칸이면 6 cm예요.","지안이와 하준이는 바르게 말했어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_L04_challenge#1','math',2,1,'u4','L04','g2_1_math_u4_L04_challenge','lesson_challenge','M2-1-u4-C3',2,'mc','auto','1 cm가 몇 번일까요? 붓의 길이는 몇 cm일까요?',ARRAY['M2-1-u4-X09','M2-1-u4-X03']::text[],true,'{"seq":1,"concept":"M2-1-u4-C3","difficulty":2,"kind":"mc","stem":"1 cm가 몇 번일까요? 붓의 길이는 몇 cm일까요?","explanation":["1 cm 칸을 하나씩 세면 11칸이에요.","1 cm가 11번이면 11 cm예요.","칸 사이의 선이 아니라 칸을 세어요."],"variant_rule":{"cm":{"ask":"cells"}},"options":[{"t":"11 cm","correct":true},{"t":"12 cm","mis":"M2-1-u4-X09"},{"t":"10 cm","mis":"M2-1-u4-X03"}],"asset":{"type":"ruler","len":11,"label":"붓","mode":"cells"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_L04_challenge#2','math',2,1,'u4','L04','g2_1_math_u4_L04_challenge','lesson_challenge','M2-1-u4-C3',2,'mc','auto','1 cm가 3번인 막대와 1 cm가 5번인 막대를 길게 이어 붙였어요. 이은 막대는 몇 cm일까요?',ARRAY['M2-1-u4-X15','M2-1-u4-X07']::text[],false,'{"seq":2,"concept":"M2-1-u4-C3","difficulty":2,"kind":"mc","stem":"1 cm가 3번인 막대와 1 cm가 5번인 막대를 길게 이어 붙였어요. 이은 막대는 몇 cm일까요?","options":[{"t":"8 cm","correct":true},{"t":"2 cm","mis":"M2-1-u4-X15"},{"t":"35 cm","mis":"M2-1-u4-X07"}],"explanation":["1 cm가 3번과 5번이니 모두 8번이에요.","1 cm가 8번이면 8 cm예요.","이어 붙이면 길이를 더해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_L04_challenge#3','math',2,1,'u4','L04','g2_1_math_u4_L04_challenge','lesson_challenge','M2-1-u4-C3',3,'mc','auto','가 막대는 1 cm가 7번이고, 나 막대는 9 cm예요. 더 긴 막대는 어느 것인가요?',ARRAY['M2-1-u4-X05','M2-1-u4-X07']::text[],false,'{"seq":3,"concept":"M2-1-u4-C3","difficulty":3,"kind":"mc","stem":"가 막대는 1 cm가 7번이고, 나 막대는 9 cm예요. 더 긴 막대는 어느 것인가요?","options":[{"t":"나","correct":true},{"t":"가","mis":"M2-1-u4-X05"},{"t":"길이가 같아요","mis":"M2-1-u4-X07"}],"explanation":["가 막대는 7 cm예요.","나 막대는 9 cm예요.","9 cm가 7 cm보다 길어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_L04_challenge#4','math',2,1,'u4','L04','g2_1_math_u4_L04_challenge','lesson_challenge','M2-1-u4-C3',3,'mc','auto','친구마다 「3뼘」만큼 끈을 잘랐더니 끈의 길이가 달랐어요. 모두 같은 길이로 자르려면 어떻게 하면 좋을까요?',ARRAY['M2-1-u4-X06','M2-1-u4-X03']::text[],false,'{"seq":4,"concept":"M2-1-u4-C3","difficulty":3,"kind":"mc","stem":"친구마다 「3뼘」만큼 끈을 잘랐더니 끈의 길이가 달랐어요. 모두 같은 길이로 자르려면 어떻게 하면 좋을까요?","options":[{"t":"누가 재어도 같은 1 cm로 길이를 정해 잘라요","correct":true},{"t":"더 큰 뼘으로 재요","mis":"M2-1-u4-X06"},{"t":"뼘을 겹쳐서 여러 번 재요","mis":"M2-1-u4-X03"}],"explanation":["뼘은 사람마다 달라요.","누가 재어도 같은 1 cm로 정하면 같은 길이가 돼요.","예를 들어 모두 20 cm로 잘라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_L04_challenge#5','math',2,1,'u4','L04','g2_1_math_u4_L04_challenge','lesson_challenge','M2-1-u4-C3',3,'ox','auto','1 cm가 4번이면 4 cm이고, 1 cm가 10번이면 10 cm예요.',ARRAY['M2-1-u4-X09']::text[],false,'{"seq":5,"concept":"M2-1-u4-C3","difficulty":3,"kind":"ox","stem":"1 cm가 4번이면 4 cm이고, 1 cm가 10번이면 10 cm예요.","answer":"O","reason_options":[{"t":"1 cm가 몇 번인지가 곧 몇 cm이니까","correct":true},{"t":"칸이 많으면 하나를 더 세야 하니까","mis":"M2-1-u4-X09"}],"mis":"M2-1-u4-X09","explanation":["1 cm가 몇 번인지 세면 길이예요.","4번이면 4 cm, 10번이면 10 cm예요.","칸 수를 그대로 cm로 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_L04_challenge#6','math',2,1,'u4','L04','g2_1_math_u4_L04_challenge','lesson_challenge','M2-1-u4-C3',3,'error','auto','친구들이 길이를 읽었어요. 잘못 읽은 친구는 누구인가요?',ARRAY['M2-1-u4-X07','M2-1-u4-X15']::text[],false,'{"seq":6,"concept":"M2-1-u4-C3","difficulty":3,"kind":"error","stem":"친구들이 길이를 읽었어요. 잘못 읽은 친구는 누구인가요?","options":[{"t":"지후 — 「6 cm는 6 미터라고 읽어요.」","correct":true,"mis_target":"M2-1-u4-X07"},{"t":"서아 — 「6 cm는 6 센티미터라고 읽어요.」","mis":"M2-1-u4-X15"},{"t":"민호 — 「12 cm는 12 센티미터라고 읽어요.」","mis":"M2-1-u4-X15"}],"explanation":["cm는 센티미터라고 읽어요.","미터는 다른 단위예요.","서아와 민호는 바르게 읽었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_L04_challenge#7','math',2,1,'u4','L04','g2_1_math_u4_L04_challenge','lesson_challenge','M2-1-u4-C3',3,'sa','auto','1 cm가 몇 번일까요? 종이띠의 길이는 몇 cm일까요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M2-1-u4-C3","difficulty":3,"kind":"sa","stem":"1 cm가 몇 번일까요? 종이띠의 길이는 몇 cm일까요? 숫자로 쓰세요.","explanation":["1 cm 칸을 하나씩 세면 12칸이에요.","1 cm가 12번이면 12 cm예요.","칸 사이의 선이 아니라 칸을 세어요."],"variant_rule":{"cm":{"ask":"cells"}},"answer":["12"],"asset":{"type":"ruler","len":12,"label":"종이띠","mode":"cells"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_L04_challenge#8','math',2,1,'u4','L04','g2_1_math_u4_L04_challenge','lesson_challenge','M2-1-u4-C3',4,'mc','auto','가 막대는 1 cm가 4번, 나 막대는 1 cm가 6번이에요. 두 막대를 이어 붙인 길이와, 나 막대가 가 막대보다 더 긴 길이를 차례대로 쓴 것은 어느 것인가요?',ARRAY['M2-1-u4-X15','M2-1-u4-X07']::text[],false,'{"seq":8,"concept":"M2-1-u4-C3","difficulty":4,"kind":"mc","stem":"가 막대는 1 cm가 4번, 나 막대는 1 cm가 6번이에요. 두 막대를 이어 붙인 길이와, 나 막대가 가 막대보다 더 긴 길이를 차례대로 쓴 것은 어느 것인가요?","options":[{"t":"10 cm, 2 cm","correct":true},{"t":"10 cm, 10 cm","mis":"M2-1-u4-X15"},{"t":"46 cm, 2 cm","mis":"M2-1-u4-X07"}],"explanation":["이어 붙이면 4 + 6 = 10, 10 cm예요.","더 긴 길이는 6 − 4 = 2, 2 cm예요.","합과 차이를 묻는 말을 나누어 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_L04_challenge#9','math',2,1,'u4','L04','g2_1_math_u4_L04_challenge','lesson_challenge','M2-1-u4-C3',4,'essay','teacher','뼘 대신 1 cm로 길이를 재면 좋은 점을 써 보세요.','{}'::text[],false,'{"seq":9,"concept":"M2-1-u4-C3","difficulty":4,"kind":"essay","stem":"뼘 대신 1 cm로 길이를 재면 좋은 점을 써 보세요.","answer_guide":{"answer":"예: 뼘은 사람마다 길이가 달라 같은 것을 재도 결과가 다르다. 1 cm는 누가 재어도 같은 길이라서 모두 같은 길이를 말할 수 있다.","scoring_points":["뼘은 사람마다 다르다는 점을 썼는가","1 cm는 누가 재어도 같다고 썼는가","그래서 길이를 똑같이 전할 수 있다고 썼는가"]},"explanation":["뼘은 달라요.","1 cm는 같아요.","똑같이 전할 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_L04_challenge#10','math',2,1,'u4','L04','g2_1_math_u4_L04_challenge','lesson_challenge','M2-1-u4-C3',4,'essay','teacher','1 cm 칸으로 나눈 막대의 길이를 구하고, 어떻게 구했는지 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"M2-1-u4-C3","difficulty":4,"kind":"essay","stem":"1 cm 칸으로 나눈 막대의 길이를 구하고, 어떻게 구했는지 써 보세요.","answer_guide":{"answer":"예: 1 cm 칸을 하나씩 세면 7칸이다. 1 cm가 7번이므로 막대의 길이는 7 cm이다.","scoring_points":["칸을 세어 7칸임을 찾았는가","1 cm가 7번이면 7 cm라고 썼는가","선이 아니라 칸을 셌는가"]},"explanation":["7칸이에요.","7 cm예요.","칸을 세요."],"asset":{"type":"ruler","len":7,"label":"막대","mode":"cells"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_L05_basic#1','math',2,1,'u4','L05','g2_1_math_u4_L05_basic','lesson_basic','M2-1-u4-C4',1,'sa','auto','색연필의 길이는 몇 cm일까요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M2-1-u4-C4","difficulty":1,"kind":"sa","stem":"색연필의 길이는 몇 cm일까요? 숫자로 쓰세요.","explanation":["색연필의 한쪽 끝이 눈금 0에 맞춰져 있어요.","다른 쪽 끝의 눈금이 8이니 8 cm예요.","자의 숫자는 1 cm가 몇 번인지를 나타내요."],"variant_rule":{"cm":{"ask":"read"}},"answer":["8"],"asset":{"type":"ruler","len":8,"label":"색연필"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_L05_basic#2','math',2,1,'u4','L05','g2_1_math_u4_L05_basic','lesson_basic','M2-1-u4-C4',1,'mc','auto','자의 숫자 0은 무엇을 뜻할까요?',ARRAY['M2-1-u4-X10']::text[],true,'{"seq":2,"concept":"M2-1-u4-C4","difficulty":1,"kind":"mc","stem":"자의 숫자 0은 무엇을 뜻할까요?","options":[{"t":"길이를 재기 시작하는 곳(시작점)","correct":true},{"t":"길이의 끝점","mis":"M2-1-u4-X10"},{"t":"가장 긴 길이","mis":"M2-1-u4-X10"}],"explanation":["자의 0은 시작점이에요.","물건의 한쪽 끝을 0에 맞춰요.","다른 쪽 끝의 눈금을 읽어요."],"variant_rule":{"alt":[{"stem":"자의 숫자 5는 무엇을 뜻할까요?","options":[{"t":"0부터 1 cm가 5번이라는 뜻","correct":true},{"t":"물건이 다섯 개라는 뜻","mis":"M2-1-u4-X10"},{"t":"눈금 선이 5개라는 뜻","mis":"M2-1-u4-X09"}],"explanation":["자의 숫자는 1 cm가 몇 번인지를 나타내요.","0부터 5까지는 1 cm가 5번이에요.","그래서 5 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_L05_basic#3','math',2,1,'u4','L05','g2_1_math_u4_L05_basic','lesson_basic','M2-1-u4-C4',1,'mc','auto','막대의 길이는 몇 cm일까요?',ARRAY['M2-1-u4-X09','M2-1-u4-X10']::text[],true,'{"seq":3,"concept":"M2-1-u4-C4","difficulty":1,"kind":"mc","stem":"막대의 길이는 몇 cm일까요?","explanation":["막대의 한쪽 끝이 눈금 0에 맞춰져 있어요.","다른 쪽 끝의 눈금이 6이니 6 cm예요.","자의 숫자는 1 cm가 몇 번인지를 나타내요."],"variant_rule":{"cm":{"ask":"read"}},"options":[{"t":"6 cm","correct":true},{"t":"7 cm","mis":"M2-1-u4-X09"},{"t":"5 cm","mis":"M2-1-u4-X10"}],"asset":{"type":"ruler","len":6,"label":"막대"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_L05_basic#4','math',2,1,'u4','L05','g2_1_math_u4_L05_basic','lesson_basic','M2-1-u4-C4',1,'ox','auto','자로 길이를 잴 때 물건의 한쪽 끝을 눈금 0에 맞춰요.',ARRAY['M2-1-u4-X10']::text[],true,'{"seq":4,"concept":"M2-1-u4-C4","difficulty":1,"kind":"ox","stem":"자로 길이를 잴 때 물건의 한쪽 끝을 눈금 0에 맞춰요.","answer":"O","reason_options":[{"t":"0이 길이를 재기 시작하는 곳이니까","correct":true},{"t":"자의 첫 숫자 1에 맞춰야 하니까","mis":"M2-1-u4-X10"}],"mis":"M2-1-u4-X10","explanation":["물건 끝을 0에 맞춰요.","그래야 다른 끝의 숫자가 곧 길이예요.","1에 맞추면 1 cm만큼 틀려요."],"variant_rule":{"alt":[{"stem":"자의 숫자는 1 cm가 몇 번인지를 나타내요.","answer":"O","reason_options":[{"t":"0부터 그 숫자까지 1 cm가 그만큼 있으니까","correct":true},{"t":"눈금 선이 몇 개인지를 나타내니까","mis":"M2-1-u4-X09"}],"explanation":["자는 1 cm를 여러 번 이어 놓은 도구예요.","숫자 8은 0부터 1 cm가 8번이에요.","눈금 선 수와는 달라요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_L05_basic#5','math',2,1,'u4','L05','g2_1_math_u4_L05_basic','lesson_basic','M2-1-u4-C4',2,'match','auto','자 위에 놓인 물건의 위치와 길이를 알맞게 이어 보세요.','{}'::text[],true,'{"seq":5,"concept":"M2-1-u4-C4","difficulty":2,"kind":"match","stem":"자 위에 놓인 물건의 위치와 길이를 알맞게 이어 보세요.","pairs":[{"l":"0부터 4까지","r":"4 cm"},{"l":"2부터 7까지","r":"5 cm"},{"l":"3부터 9까지","r":"6 cm"}],"mis":"M2-1-u4-X08","explanation":["0부터 4까지는 4 cm예요.","2부터 7까지 1 cm 칸은 5번이에요.","3부터 9까지 1 cm 칸은 6번이에요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 자 위에 놓인 물건의 위치와 길이를 알맞게 이어 보세요.","pairs":[{"l":"0부터 6까지","r":"6 cm"},{"l":"1부터 4까지","r":"3 cm"},{"l":"4부터 12까지","r":"8 cm"}],"explanation":["0부터 6까지는 6 cm예요.","1부터 4까지 1 cm 칸은 3번이에요.","4부터 12까지 1 cm 칸은 8번이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_L05_basic#6','math',2,1,'u4','L05','g2_1_math_u4_L05_basic','lesson_basic','M2-1-u4-C4',2,'sa','auto','종이띠가 자의 눈금 0에 놓여 있지 않아요. 종이띠의 길이는 몇 cm일까요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M2-1-u4-C4","difficulty":2,"kind":"sa","stem":"종이띠가 자의 눈금 0에 놓여 있지 않아요. 종이띠의 길이는 몇 cm일까요? 숫자로 쓰세요.","explanation":["2부터 9까지 1 cm 칸을 세어요.","1 cm가 7번이니 7 cm예요.","끝 눈금 숫자 9를 그대로 읽으면 안 돼요."],"variant_rule":{"cm":{"ask":"off"}},"answer":["7"],"asset":{"type":"ruler","len":7,"label":"종이띠","s":2}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_L05_basic#7','math',2,1,'u4','L05','g2_1_math_u4_L05_basic','lesson_basic','M2-1-u4-C4',2,'mc','auto','붓의 길이는 몇 cm일까요?',ARRAY['M2-1-u4-X09','M2-1-u4-X10']::text[],true,'{"seq":7,"concept":"M2-1-u4-C4","difficulty":2,"kind":"mc","stem":"붓의 길이는 몇 cm일까요?","explanation":["붓의 한쪽 끝이 눈금 0에 맞춰져 있어요.","다른 쪽 끝의 눈금이 11이니 11 cm예요.","자의 숫자는 1 cm가 몇 번인지를 나타내요."],"variant_rule":{"cm":{"ask":"read"}},"options":[{"t":"11 cm","correct":true},{"t":"12 cm","mis":"M2-1-u4-X09"},{"t":"10 cm","mis":"M2-1-u4-X10"}],"asset":{"type":"ruler","len":11,"label":"붓"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_L05_basic#8','math',2,1,'u4','L05','g2_1_math_u4_L05_basic','lesson_basic','M2-1-u4-C4',2,'mc','auto','자로 길이를 잰 방법 가운데 잘못된 것은 어느 것인가요?',ARRAY['M2-1-u4-X15']::text[],true,'{"seq":8,"concept":"M2-1-u4-C4","difficulty":2,"kind":"mc","stem":"자로 길이를 잰 방법 가운데 잘못된 것은 어느 것인가요?","options":[{"t":"물건이 0에 없는데 끝 눈금의 숫자만 읽었어요","correct":true},{"t":"물건 끝을 0에 맞췄어요","mis":"M2-1-u4-X15"},{"t":"물건을 자와 나란히 놓았어요","mis":"M2-1-u4-X15"}],"explanation":["0에 없으면 끝 숫자가 길이가 아니에요.","1 cm 칸을 세어야 해요.","나머지 둘은 바른 방법이에요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 자로 길이를 잰 방법 가운데 잘못된 것은 어느 것인가요?","options":[{"t":"물건 끝을 눈금 1에 맞추고 다른 끝 숫자를 읽었어요","correct":true},{"t":"물건이 0에 없어서 1 cm 칸을 세었어요","mis":"M2-1-u4-X15"},{"t":"물건 끝을 0에 맞췄어요","mis":"M2-1-u4-X15"}],"explanation":["시작점은 1이 아니라 0이에요.","1에 맞추고 끝 숫자를 읽으면 1 cm 길게 말해요.","나머지 둘은 바른 방법이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_L05_basic#9','math',2,1,'u4','L05','g2_1_math_u4_L05_basic','lesson_basic','M2-1-u4-C4',2,'mc','auto','크레파스가 자의 눈금 0에 놓여 있지 않아요. 크레파스의 길이는 몇 cm일까요?',ARRAY['M2-1-u4-X08','M2-1-u4-X09']::text[],true,'{"seq":9,"concept":"M2-1-u4-C4","difficulty":2,"kind":"mc","stem":"크레파스가 자의 눈금 0에 놓여 있지 않아요. 크레파스의 길이는 몇 cm일까요?","explanation":["3부터 8까지 1 cm 칸을 세어요.","1 cm가 5번이니 5 cm예요.","끝 눈금 숫자 8을 그대로 읽으면 안 돼요."],"variant_rule":{"cm":{"ask":"off"}},"options":[{"t":"5 cm","correct":true},{"t":"8 cm","mis":"M2-1-u4-X08"},{"t":"6 cm","mis":"M2-1-u4-X09"}],"asset":{"type":"ruler","len":5,"label":"크레파스","s":3}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_L05_basic#10','math',2,1,'u4','L05','g2_1_math_u4_L05_basic','lesson_basic','M2-1-u4-C4',3,'error','auto','친구들이 자로 연필의 길이를 재었어요. 잘못 잰 친구는 누구인가요?',ARRAY['M2-1-u4-X08','M2-1-u4-X15']::text[],true,'{"seq":10,"concept":"M2-1-u4-C4","difficulty":3,"kind":"error","stem":"친구들이 자로 연필의 길이를 재었어요. 잘못 잰 친구는 누구인가요?","options":[{"t":"태민 — 연필 끝을 1에 맞추고 끝 눈금 9를 읽어 9 cm라고 했어요","correct":true,"mis_target":"M2-1-u4-X08"},{"t":"예린 — 연필 끝을 0에 맞추고 끝 눈금 8을 읽어 8 cm라고 했어요","mis":"M2-1-u4-X15"},{"t":"준우 — 1부터 9까지 1 cm 칸을 세어 8 cm라고 했어요","mis":"M2-1-u4-X15"}],"explanation":["1에 맞추었으면 끝 숫자 9가 길이가 아니에요.","1부터 9까지 칸을 세면 8 cm예요.","예린이와 준우는 바르게 재었어요."],"variant_rule":{"alt":[{"stem":"친구들이 자로 리본의 길이를 재었어요. 잘못 잰 친구는 누구인가요?","options":[{"t":"소율 — 3부터 9까지 놓인 리본의 눈금 선 7개를 세어 7 cm라고 했어요","correct":true,"mis_target":"M2-1-u4-X09"},{"t":"하람 — 3부터 9까지 1 cm 칸을 세어 6 cm라고 했어요","mis":"M2-1-u4-X15"},{"t":"도담 — 리본 끝을 0에 다시 맞추고 6을 읽었어요","mis":"M2-1-u4-X15"}],"explanation":["선이 아니라 칸을 세어야 해요.","3부터 9까지 1 cm 칸은 6개, 6 cm예요.","하람이와 도담이는 바르게 재었어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_L05_challenge#1','math',2,1,'u4','L05','g2_1_math_u4_L05_challenge','lesson_challenge','M2-1-u4-C4',2,'mc','auto','연필이 자의 눈금 0에 놓여 있지 않아요. 연필의 길이는 몇 cm일까요?',ARRAY['M2-1-u4-X08']::text[],true,'{"seq":1,"concept":"M2-1-u4-C4","difficulty":2,"kind":"mc","stem":"연필이 자의 눈금 0에 놓여 있지 않아요. 연필의 길이는 몇 cm일까요?","explanation":["1부터 9까지 1 cm 칸을 세어요.","1 cm가 8번이니 8 cm예요.","끝 눈금 숫자 9를 그대로 읽으면 안 돼요."],"variant_rule":{"cm":{"ask":"off"}},"options":[{"t":"8 cm","correct":true},{"t":"9 cm","mis":"M2-1-u4-X08"}],"asset":{"type":"ruler","len":8,"label":"연필","s":1}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_L05_challenge#2','math',2,1,'u4','L05','g2_1_math_u4_L05_challenge','lesson_challenge','M2-1-u4-C4',2,'sa','auto','붓의 길이는 몇 cm일까요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M2-1-u4-C4","difficulty":2,"kind":"sa","stem":"붓의 길이는 몇 cm일까요? 숫자로 쓰세요.","explanation":["붓의 한쪽 끝이 눈금 0에 맞춰져 있어요.","다른 쪽 끝의 눈금이 13이니 13 cm예요.","자의 숫자는 1 cm가 몇 번인지를 나타내요."],"variant_rule":{"cm":{"ask":"read"}},"answer":["13"],"asset":{"type":"ruler","len":13,"label":"붓"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_L05_challenge#3','math',2,1,'u4','L05','g2_1_math_u4_L05_challenge','lesson_challenge','M2-1-u4-C4',3,'mc','auto','리본이 자의 눈금 0에 놓여 있지 않아요. 리본의 길이는 몇 cm일까요?',ARRAY['M2-1-u4-X08','M2-1-u4-X09']::text[],true,'{"seq":3,"concept":"M2-1-u4-C4","difficulty":3,"kind":"mc","stem":"리본이 자의 눈금 0에 놓여 있지 않아요. 리본의 길이는 몇 cm일까요?","explanation":["3부터 12까지 1 cm 칸을 세어요.","1 cm가 9번이니 9 cm예요.","끝 눈금 숫자 12를 그대로 읽으면 안 돼요."],"variant_rule":{"cm":{"ask":"off"}},"options":[{"t":"9 cm","correct":true},{"t":"12 cm","mis":"M2-1-u4-X08"},{"t":"10 cm","mis":"M2-1-u4-X09"}],"asset":{"type":"ruler","len":9,"label":"리본","s":3}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_L05_challenge#4','math',2,1,'u4','L05','g2_1_math_u4_L05_challenge','lesson_challenge','M2-1-u4-C4',3,'mc','auto','막대가 자의 눈금 2부터 8까지에 놓여 있어요. 막대의 길이는 몇 cm일까요?',ARRAY['M2-1-u4-X08','M2-1-u4-X09']::text[],false,'{"seq":4,"concept":"M2-1-u4-C4","difficulty":3,"kind":"mc","stem":"막대가 자의 눈금 2부터 8까지에 놓여 있어요. 막대의 길이는 몇 cm일까요?","options":[{"t":"6 cm","correct":true},{"t":"8 cm","mis":"M2-1-u4-X08"},{"t":"7 cm","mis":"M2-1-u4-X09"}],"explanation":["2부터 8까지 1 cm 칸을 세요.","3, 4, 5, 6, 7, 8 — 6칸이에요.","그래서 6 cm예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_L05_challenge#5','math',2,1,'u4','L05','g2_1_math_u4_L05_challenge','lesson_challenge','M2-1-u4-C4',3,'ox','auto','물건 끝이 0에 없어도 끝 눈금의 숫자를 그대로 읽으면 길이예요.',ARRAY['M2-1-u4-X08']::text[],false,'{"seq":5,"concept":"M2-1-u4-C4","difficulty":3,"kind":"ox","stem":"물건 끝이 0에 없어도 끝 눈금의 숫자를 그대로 읽으면 길이예요.","answer":"X","reason_options":[{"t":"0에서 시작하지 않으면 1 cm 칸을 세어야 하니까","correct":true},{"t":"자의 숫자가 곧 길이니까","mis":"M2-1-u4-X08"}],"mis":"M2-1-u4-X08","explanation":["0에서 시작할 때만 끝 숫자가 길이예요.","0에 없으면 1 cm 칸이 몇 번인지 세요.","시작 눈금을 꼭 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_L05_challenge#6','math',2,1,'u4','L05','g2_1_math_u4_L05_challenge','lesson_challenge','M2-1-u4-C4',3,'error','auto','친구들이 자 위에 놓인 크레파스의 길이를 말했어요. 크레파스는 4부터 10까지에 놓여 있어요. 잘못 말한 친구는 누구인가요?',ARRAY['M2-1-u4-X08','M2-1-u4-X15']::text[],false,'{"seq":6,"concept":"M2-1-u4-C4","difficulty":3,"kind":"error","stem":"친구들이 자 위에 놓인 크레파스의 길이를 말했어요. 크레파스는 4부터 10까지에 놓여 있어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"은솔 — 「10 cm야.」","correct":true,"mis_target":"M2-1-u4-X08"},{"t":"지호 — 「1 cm 칸이 6번이니 6 cm야.」","mis":"M2-1-u4-X15"},{"t":"아린 — 「10 − 4 = 6, 6 cm야.」","mis":"M2-1-u4-X15"}],"explanation":["4부터 10까지는 1 cm가 6번이에요.","끝 숫자 10을 그대로 읽으면 안 돼요.","지호와 아린이는 바르게 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_L05_challenge#7','math',2,1,'u4','L05','g2_1_math_u4_L05_challenge','lesson_challenge','M2-1-u4-C4',3,'sa','auto','지우개가 자의 눈금 0에 놓여 있지 않아요. 지우개의 길이는 몇 cm일까요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M2-1-u4-C4","difficulty":3,"kind":"sa","stem":"지우개가 자의 눈금 0에 놓여 있지 않아요. 지우개의 길이는 몇 cm일까요? 숫자로 쓰세요.","explanation":["5부터 9까지 1 cm 칸을 세어요.","1 cm가 4번이니 4 cm예요.","끝 눈금 숫자 9를 그대로 읽으면 안 돼요."],"variant_rule":{"cm":{"ask":"off"}},"answer":["4"],"asset":{"type":"ruler","len":4,"label":"지우개","s":5}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_L05_challenge#8','math',2,1,'u4','L05','g2_1_math_u4_L05_challenge','lesson_challenge','M2-1-u4-C4',4,'mc','auto','가 막대는 자의 0부터 7까지, 나 막대는 3부터 11까지에 놓여 있어요. 바르게 말한 것은 어느 것인가요?',ARRAY['M2-1-u4-X08','M2-1-u4-X15']::text[],false,'{"seq":8,"concept":"M2-1-u4-C4","difficulty":4,"kind":"mc","stem":"가 막대는 자의 0부터 7까지, 나 막대는 3부터 11까지에 놓여 있어요. 바르게 말한 것은 어느 것인가요?","options":[{"t":"나가 가보다 1 cm 더 길어요","correct":true},{"t":"나가 가보다 4 cm 더 길어요","mis":"M2-1-u4-X08"},{"t":"가가 나보다 더 길어요","mis":"M2-1-u4-X15"}],"explanation":["가 막대는 7 cm예요.","나 막대는 3부터 11까지 칸을 세면 8 cm예요.","8 − 7 = 1, 나가 1 cm 더 길어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_L05_challenge#9','math',2,1,'u4','L05','g2_1_math_u4_L05_challenge','lesson_challenge','M2-1-u4-C4',4,'essay','teacher','물건이 자의 눈금 0에 놓여 있지 않을 때 길이를 재는 방법을 설명해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M2-1-u4-C4","difficulty":4,"kind":"essay","stem":"물건이 자의 눈금 0에 놓여 있지 않을 때 길이를 재는 방법을 설명해 보세요.","answer_guide":{"answer":"예: 물건이 놓인 처음 눈금부터 끝 눈금까지 1 cm 칸이 몇 번인지 센다. 예를 들어 2부터 7까지면 1 cm가 5번이니 5 cm이다.","scoring_points":["처음 눈금부터 세어야 한다고 썼는가","1 cm 칸이 몇 번인지 세어 길이를 구한다고 썼는가","예를 들어 바르게 계산했는가"]},"explanation":["처음 눈금 확인.","1 cm 칸 세기.","예 들기."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_L05_challenge#10','math',2,1,'u4','L05','g2_1_math_u4_L05_challenge','lesson_challenge','M2-1-u4-C4',4,'essay','teacher','민호가 그림의 막대를 재고 「8 cm예요.」라고 했어요. 잘못된 점을 찾고 바른 길이를 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"M2-1-u4-C4","difficulty":4,"kind":"essay","stem":"민호가 그림의 막대를 재고 「8 cm예요.」라고 했어요. 잘못된 점을 찾고 바른 길이를 써 보세요.","answer_guide":{"answer":"예: 막대가 0이 아니라 2부터 놓여 있는데 끝 숫자 8을 그대로 읽었다. 2부터 8까지 1 cm 칸을 세면 6번이므로 6 cm이다.","scoring_points":["끝 숫자를 그대로 읽은 잘못을 찾았는가","2부터 1 cm 칸을 세었는가","바른 길이 6 cm를 썼는가"]},"explanation":["끝 숫자를 그대로 읽었어요.","2부터 칸을 세요.","6 cm예요."],"asset":{"type":"ruler","len":6,"label":"막대","s":2}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_L06_basic#1','math',2,1,'u4','L06','g2_1_math_u4_L06_basic','lesson_basic','M2-1-u4-C5',1,'sa','auto','색연필의 길이는 약 몇 cm일까요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M2-1-u4-C5","difficulty":1,"kind":"sa","stem":"색연필의 길이는 약 몇 cm일까요? 숫자로 쓰세요.","explanation":["끝이 눈금 7과 8 사이에 있어요.","7에 더 가까우니 약 7 cm예요.","눈금 사이에 있으면 가까운 쪽 숫자를 읽고 「약」을 붙여요."],"variant_rule":{"cm":{"ask":"approx"}},"answer":["7"],"asset":{"type":"ruler","len":7.2,"label":"색연필"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_L06_basic#2','math',2,1,'u4','L06','g2_1_math_u4_L06_basic','lesson_basic','M2-1-u4-C5',1,'mc','auto','물건의 끝이 자의 눈금과 눈금 사이에 있을 때는 어떻게 읽나요?',ARRAY['M2-1-u4-X11','M2-1-u4-X12']::text[],true,'{"seq":2,"concept":"M2-1-u4-C5","difficulty":1,"kind":"mc","stem":"물건의 끝이 자의 눈금과 눈금 사이에 있을 때는 어떻게 읽나요?","options":[{"t":"더 가까운 눈금의 숫자를 읽고 「약」을 붙여요","correct":true},{"t":"더 먼 눈금의 숫자를 읽어요","mis":"M2-1-u4-X11"},{"t":"가까운 눈금의 숫자만 읽고 「약」은 붙이지 않아요","mis":"M2-1-u4-X12"}],"explanation":["끝에서 더 가까운 눈금을 찾아요.","그 숫자 앞에 「약」을 붙여 말해요.","딱 맞지 않았다는 뜻이에요."],"variant_rule":{"alt":[{"stem":"끝이 눈금 7과 8 사이에 있고 7에 더 가까워요. 길이를 바르게 말한 것은 어느 것인가요?","options":[{"t":"약 7 cm","correct":true},{"t":"약 8 cm","mis":"M2-1-u4-X11"},{"t":"7 cm","mis":"M2-1-u4-X12"}],"explanation":["7에 더 가까워요.","딱 맞지 않으니 「약」을 붙여요.","약 7 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_L06_basic#3','math',2,1,'u4','L06','g2_1_math_u4_L06_basic','lesson_basic','M2-1-u4-C5',1,'mc','auto','막대의 길이는 약 몇 cm일까요?',ARRAY['M2-1-u4-X11','M2-1-u4-X12']::text[],true,'{"seq":3,"concept":"M2-1-u4-C5","difficulty":1,"kind":"mc","stem":"막대의 길이는 약 몇 cm일까요?","explanation":["끝이 눈금 5와 6 사이에 있어요.","6에 더 가까우니 약 6 cm예요.","눈금 사이에 있으면 가까운 쪽 숫자를 읽고 「약」을 붙여요."],"variant_rule":{"cm":{"ask":"approx"}},"options":[{"t":"약 6 cm","correct":true},{"t":"약 5 cm","mis":"M2-1-u4-X11"},{"t":"6 cm","mis":"M2-1-u4-X12"}],"asset":{"type":"ruler","len":5.8,"label":"막대"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_L06_basic#4','math',2,1,'u4','L06','g2_1_math_u4_L06_basic','lesson_basic','M2-1-u4-C5',1,'ox','auto','길이가 눈금 사이에 있으면 숫자 앞에 「약」을 붙여 말해요.',ARRAY['M2-1-u4-X12']::text[],true,'{"seq":4,"concept":"M2-1-u4-C5","difficulty":1,"kind":"ox","stem":"길이가 눈금 사이에 있으면 숫자 앞에 「약」을 붙여 말해요.","answer":"O","reason_options":[{"t":"눈금에 딱 맞지 않은 길이라는 뜻이니까","correct":true},{"t":"딱 맞지 않아도 숫자만 말하면 되니까","mis":"M2-1-u4-X12"}],"mis":"M2-1-u4-X12","explanation":["「약」은 「거의 그만큼」이라는 뜻이에요.","딱 맞지 않으면 「약」을 붙여요.","예: 약 6 cm"],"variant_rule":{"alt":[{"stem":"눈금 사이에 있는 길이는 늘 더 큰 쪽 숫자를 읽어요.","answer":"X","reason_options":[{"t":"더 큰 쪽이 아니라 더 가까운 쪽 숫자를 읽으니까","correct":true},{"t":"길이는 크게 말해야 하니까","mis":"M2-1-u4-X11"}],"explanation":["가까운 쪽을 읽어요.","작은 쪽이 더 가까우면 작은 쪽 숫자예요.","그리고 「약」을 붙여요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_L06_basic#5','math',2,1,'u4','L06','g2_1_math_u4_L06_basic','lesson_basic','M2-1-u4-C5',2,'match','auto','끝의 위치와 길이를 알맞게 이어 보세요. (모두 0부터 재었어요.)','{}'::text[],true,'{"seq":5,"concept":"M2-1-u4-C5","difficulty":2,"kind":"match","stem":"끝의 위치와 길이를 알맞게 이어 보세요. (모두 0부터 재었어요.)","pairs":[{"l":"6과 7 사이, 6에 더 가까움","r":"약 6 cm"},{"l":"8과 9 사이, 9에 더 가까움","r":"약 9 cm"},{"l":"3과 4 사이, 3에 더 가까움","r":"약 3 cm"}],"mis":"M2-1-u4-X11","explanation":["6에 가까우면 약 6 cm예요.","9에 가까우면 약 9 cm예요.","3에 가까우면 약 3 cm예요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 끝의 위치와 길이를 알맞게 이어 보세요. (모두 0부터 재었어요.)","pairs":[{"l":"4와 5 사이, 5에 더 가까움","r":"약 5 cm"},{"l":"10과 11 사이, 10에 더 가까움","r":"약 10 cm"},{"l":"7과 8 사이, 8에 더 가까움","r":"약 8 cm"}],"explanation":["5에 가까우면 약 5 cm예요.","10에 가까우면 약 10 cm예요.","8에 가까우면 약 8 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_L06_basic#6','math',2,1,'u4','L06','g2_1_math_u4_L06_basic','lesson_basic','M2-1-u4-C5',2,'sa','auto','붓의 길이는 약 몇 cm일까요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M2-1-u4-C5","difficulty":2,"kind":"sa","stem":"붓의 길이는 약 몇 cm일까요? 숫자로 쓰세요.","explanation":["끝이 눈금 9와 10 사이에 있어요.","10에 더 가까우니 약 10 cm예요.","눈금 사이에 있으면 가까운 쪽 숫자를 읽고 「약」을 붙여요."],"variant_rule":{"cm":{"ask":"approx"}},"answer":["10"],"asset":{"type":"ruler","len":9.7,"label":"붓"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_L06_basic#7','math',2,1,'u4','L06','g2_1_math_u4_L06_basic','lesson_basic','M2-1-u4-C5',2,'mc','auto','지우개의 길이는 약 몇 cm일까요?',ARRAY['M2-1-u4-X11','M2-1-u4-X12']::text[],true,'{"seq":7,"concept":"M2-1-u4-C5","difficulty":2,"kind":"mc","stem":"지우개의 길이는 약 몇 cm일까요?","explanation":["끝이 눈금 4와 5 사이에 있어요.","4에 더 가까우니 약 4 cm예요.","눈금 사이에 있으면 가까운 쪽 숫자를 읽고 「약」을 붙여요."],"variant_rule":{"cm":{"ask":"approx"}},"options":[{"t":"약 4 cm","correct":true},{"t":"약 5 cm","mis":"M2-1-u4-X11"},{"t":"4 cm","mis":"M2-1-u4-X12"}],"asset":{"type":"ruler","len":4.3,"label":"지우개"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_L06_basic#8','math',2,1,'u4','L06','g2_1_math_u4_L06_basic','lesson_basic','M2-1-u4-C5',2,'mc','auto','끝이 눈금 6과 7 사이에 있고 6에 더 가까운 연필이 있어요. 길이를 알맞게 말한 친구는 누구인가요?',ARRAY['M2-1-u4-X12','M2-1-u4-X11']::text[],true,'{"seq":8,"concept":"M2-1-u4-C5","difficulty":2,"kind":"mc","stem":"끝이 눈금 6과 7 사이에 있고 6에 더 가까운 연필이 있어요. 길이를 알맞게 말한 친구는 누구인가요?","options":[{"t":"지우 — 「약 6 cm야.」","correct":true},{"t":"민호 — 「6 cm야.」","mis":"M2-1-u4-X12"},{"t":"서아 — 「약 7 cm야.」","mis":"M2-1-u4-X11"}],"explanation":["6에 더 가까우니 6을 읽어요.","딱 맞지 않으니 「약」을 붙여요.","그래서 약 6 cm예요."],"variant_rule":{"alt":[{"stem":"끝이 눈금 9와 10 사이에 있고 10에 더 가까운 붓이 있어요. 길이를 알맞게 말한 친구는 누구인가요?","options":[{"t":"하린 — 「약 10 cm야.」","correct":true},{"t":"도윤 — 「10 cm야.」","mis":"M2-1-u4-X12"},{"t":"지안 — 「약 9 cm야.」","mis":"M2-1-u4-X11"}],"explanation":["10에 더 가까우니 10을 읽어요.","딱 맞지 않으니 「약」을 붙여요.","그래서 약 10 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_L06_basic#9','math',2,1,'u4','L06','g2_1_math_u4_L06_basic','lesson_basic','M2-1-u4-C5',2,'ox','auto','두 물건이 모두 약 5 cm라면 두 물건의 실제 길이도 똑같아요.',ARRAY['M2-1-u4-X13']::text[],true,'{"seq":9,"concept":"M2-1-u4-C5","difficulty":2,"kind":"ox","stem":"두 물건이 모두 약 5 cm라면 두 물건의 실제 길이도 똑같아요.","answer":"X","reason_options":[{"t":"약 5 cm는 5 cm 가까이라는 뜻이라 조금씩 다를 수 있으니까","correct":true},{"t":"「약 5 cm」로 같으니까","mis":"M2-1-u4-X13"}],"mis":"M2-1-u4-X13","explanation":["약 5 cm는 5에 가깝다는 뜻이에요.","하나는 5보다 조금 짧고 하나는 조금 길 수 있어요.","맞대어 보면 다를 수 있어요."],"variant_rule":{"alt":[{"stem":"약 8 cm인 리본과 약 8 cm인 끈을 맞대어 보면 길이가 조금 다를 수도 있어요.","answer":"O","reason_options":[{"t":"둘 다 8 가까이일 뿐 똑같다는 뜻은 아니니까","correct":true},{"t":"약 8 cm면 모두 8 cm이니까","mis":"M2-1-u4-X13"}],"explanation":["약 8 cm는 8에 가깝다는 뜻이에요.","실제 길이는 조금씩 다를 수 있어요.","정확히 견주려면 맞대어 봐요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_L06_basic#10','math',2,1,'u4','L06','g2_1_math_u4_L06_basic','lesson_basic','M2-1-u4-C5',3,'mc','auto','종이띠의 길이는 약 몇 cm일까요?',ARRAY['M2-1-u4-X08','M2-1-u4-X11']::text[],true,'{"seq":10,"concept":"M2-1-u4-C5","difficulty":3,"kind":"mc","stem":"종이띠의 길이는 약 몇 cm일까요?","explanation":["2부터 세면 끝이 7칸과 6칸 사이에 있어요.","7에 더 가까우니 약 7 cm예요.","눈금 사이에 있으면 가까운 쪽 숫자를 읽고 「약」을 붙여요."],"variant_rule":{"cm":{"ask":"approx","off":true}},"options":[{"t":"약 7 cm","correct":true},{"t":"약 9 cm","mis":"M2-1-u4-X08"},{"t":"약 6 cm","mis":"M2-1-u4-X11"}],"asset":{"type":"ruler","len":6.7,"label":"종이띠","s":2}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_L06_challenge#1','math',2,1,'u4','L06','g2_1_math_u4_L06_challenge','lesson_challenge','M2-1-u4-C5',2,'mc','auto','크레파스의 길이는 약 몇 cm일까요?',ARRAY['M2-1-u4-X11','M2-1-u4-X12']::text[],true,'{"seq":1,"concept":"M2-1-u4-C5","difficulty":2,"kind":"mc","stem":"크레파스의 길이는 약 몇 cm일까요?","explanation":["끝이 눈금 8과 9 사이에 있어요.","8에 더 가까우니 약 8 cm예요.","눈금 사이에 있으면 가까운 쪽 숫자를 읽고 「약」을 붙여요."],"variant_rule":{"cm":{"ask":"approx"}},"options":[{"t":"약 8 cm","correct":true},{"t":"약 9 cm","mis":"M2-1-u4-X11"},{"t":"8 cm","mis":"M2-1-u4-X12"}],"asset":{"type":"ruler","len":8.3,"label":"크레파스"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_L06_challenge#2','math',2,1,'u4','L06','g2_1_math_u4_L06_challenge','lesson_challenge','M2-1-u4-C5',2,'mc','auto','0부터 잰 물건의 끝이 어디에 있으면 「약 7 cm」라고 말할까요?',ARRAY['M2-1-u4-X11','M2-1-u4-X12']::text[],false,'{"seq":2,"concept":"M2-1-u4-C5","difficulty":2,"kind":"mc","stem":"0부터 잰 물건의 끝이 어디에 있으면 「약 7 cm」라고 말할까요?","options":[{"t":"6과 7 사이에서 7에 더 가까운 곳","correct":true},{"t":"7과 8 사이에서 8에 더 가까운 곳","mis":"M2-1-u4-X11"},{"t":"눈금 7에 딱 맞는 곳","mis":"M2-1-u4-X12"}],"explanation":["7에 더 가까운 곳이면 약 7 cm예요.","8에 더 가까우면 약 8 cm예요.","눈금 7에 딱 맞으면 「약」 없이 7 cm예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_L06_challenge#3','math',2,1,'u4','L06','g2_1_math_u4_L06_challenge','lesson_challenge','M2-1-u4-C5',3,'sa','auto','리본의 길이는 약 몇 cm일까요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M2-1-u4-C5","difficulty":3,"kind":"sa","stem":"리본의 길이는 약 몇 cm일까요? 숫자로 쓰세요.","explanation":["3부터 세면 끝이 5칸과 6칸 사이에 있어요.","5에 더 가까우니 약 5 cm예요.","눈금 사이에 있으면 가까운 쪽 숫자를 읽고 「약」을 붙여요."],"variant_rule":{"cm":{"ask":"approx","off":true}},"answer":["5"],"asset":{"type":"ruler","len":5.2,"label":"리본","s":3}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_L06_challenge#4','math',2,1,'u4','L06','g2_1_math_u4_L06_challenge','lesson_challenge','M2-1-u4-C5',3,'mc','auto','막대의 길이는 약 몇 cm일까요?',ARRAY['M2-1-u4-X08','M2-1-u4-X11']::text[],true,'{"seq":4,"concept":"M2-1-u4-C5","difficulty":3,"kind":"mc","stem":"막대의 길이는 약 몇 cm일까요?","explanation":["1부터 세면 끝이 8칸과 7칸 사이에 있어요.","8에 더 가까우니 약 8 cm예요.","눈금 사이에 있으면 가까운 쪽 숫자를 읽고 「약」을 붙여요."],"variant_rule":{"cm":{"ask":"approx","off":true}},"options":[{"t":"약 8 cm","correct":true},{"t":"약 9 cm","mis":"M2-1-u4-X08"},{"t":"약 7 cm","mis":"M2-1-u4-X11"}],"asset":{"type":"ruler","len":7.8,"label":"막대","s":1}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_L06_challenge#5','math',2,1,'u4','L06','g2_1_math_u4_L06_challenge','lesson_challenge','M2-1-u4-C5',3,'ox','auto','약 5 cm인 종이띠 두 개를 맞대어 보면 길이가 다를 수도 있어요.',ARRAY['M2-1-u4-X13']::text[],false,'{"seq":5,"concept":"M2-1-u4-C5","difficulty":3,"kind":"ox","stem":"약 5 cm인 종이띠 두 개를 맞대어 보면 길이가 다를 수도 있어요.","answer":"O","reason_options":[{"t":"약 5 cm는 5 cm 가까이라는 뜻일 뿐이니까","correct":true},{"t":"약 5 cm면 모두 5 cm이니까","mis":"M2-1-u4-X13"}],"mis":"M2-1-u4-X13","explanation":["약 5 cm는 5 cm에 가까운 길이예요.","조금 짧을 수도, 조금 길 수도 있어요.","그래서 맞대면 다를 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_L06_challenge#6','math',2,1,'u4','L06','g2_1_math_u4_L06_challenge','lesson_challenge','M2-1-u4-C5',3,'error','auto','친구들이 0부터 잰 물건의 길이를 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M2-1-u4-X11','M2-1-u4-X15']::text[],false,'{"seq":6,"concept":"M2-1-u4-C5","difficulty":3,"kind":"error","stem":"친구들이 0부터 잰 물건의 길이를 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"은솔 — 끝이 8과 9 사이에서 8에 더 가까운데 「약 9 cm」라고 했어요","correct":true,"mis_target":"M2-1-u4-X11"},{"t":"현우 — 끝이 4와 5 사이에서 5에 더 가까워 「약 5 cm」라고 했어요","mis":"M2-1-u4-X15"},{"t":"서윤 — 끝이 2와 3 사이에서 2에 더 가까워 「약 2 cm」라고 했어요","mis":"M2-1-u4-X15"}],"explanation":["8에 더 가까우면 약 8 cm예요.","은솔이는 먼 눈금을 읽었어요.","현우와 서윤이는 바르게 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_L06_challenge#7','math',2,1,'u4','L06','g2_1_math_u4_L06_challenge','lesson_challenge','M2-1-u4-C5',3,'mc','auto','물건이 자의 눈금 3에서 시작해 끝이 9와 10 사이, 9에 더 가까운 곳에 있어요. 길이는 약 몇 cm일까요?',ARRAY['M2-1-u4-X08','M2-1-u4-X11']::text[],false,'{"seq":7,"concept":"M2-1-u4-C5","difficulty":3,"kind":"mc","stem":"물건이 자의 눈금 3에서 시작해 끝이 9와 10 사이, 9에 더 가까운 곳에 있어요. 길이는 약 몇 cm일까요?","options":[{"t":"약 6 cm","correct":true},{"t":"약 9 cm","mis":"M2-1-u4-X08"},{"t":"약 7 cm","mis":"M2-1-u4-X11"}],"explanation":["3부터 1 cm 칸을 세요.","3부터 9까지 6칸이고, 끝은 9에 더 가까워요.","그래서 약 6 cm예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_L06_challenge#8','math',2,1,'u4','L06','g2_1_math_u4_L06_challenge','lesson_challenge','M2-1-u4-C5',4,'mc','auto','두 종이띠 가와 나는 모두 약 5 cm예요. 가의 끝은 5보다 조금 앞에, 나의 끝은 5보다 조금 뒤에 있어요. (둘 다 0부터 재었어요.) 바르게 말한 것은 어느 것인가요?',ARRAY['M2-1-u4-X13','M2-1-u4-X15']::text[],false,'{"seq":8,"concept":"M2-1-u4-C5","difficulty":4,"kind":"mc","stem":"두 종이띠 가와 나는 모두 약 5 cm예요. 가의 끝은 5보다 조금 앞에, 나의 끝은 5보다 조금 뒤에 있어요. (둘 다 0부터 재었어요.) 바르게 말한 것은 어느 것인가요?","options":[{"t":"둘 다 약 5 cm지만 나가 가보다 조금 더 길어요","correct":true},{"t":"둘은 길이가 똑같아요","mis":"M2-1-u4-X13"},{"t":"가가 나보다 더 길어요","mis":"M2-1-u4-X15"}],"explanation":["둘 다 5에 가장 가까워 약 5 cm예요.","하지만 나의 끝이 더 오른쪽에 있어요.","그래서 나가 조금 더 길어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_L06_challenge#9','math',2,1,'u4','L06','g2_1_math_u4_L06_challenge','lesson_challenge','M2-1-u4-C5',4,'essay','teacher','그림의 연필 길이를 「약 몇 cm」로 말하고, 그렇게 읽은 방법을 설명해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M2-1-u4-C5","difficulty":4,"kind":"essay","stem":"그림의 연필 길이를 「약 몇 cm」로 말하고, 그렇게 읽은 방법을 설명해 보세요.","answer_guide":{"answer":"예: 약 7 cm. 연필 끝이 눈금 7과 8 사이에 있는데 7에 더 가깝다. 그래서 7을 읽고 딱 맞지 않으니 「약」을 붙인다.","scoring_points":["약 7 cm라고 답했는가","끝이 7과 8 사이이며 7에 더 가깝다고 썼는가","딱 맞지 않아 「약」을 붙인다고 썼는가"]},"explanation":["약 7 cm예요.","7에 더 가까워요.","「약」을 붙여요."],"asset":{"type":"ruler","len":7.3,"label":"연필"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_L06_challenge#10','math',2,1,'u4','L06','g2_1_math_u4_L06_challenge','lesson_challenge','M2-1-u4-C5',4,'essay','teacher','두 물건이 모두 「약 6 cm」인데 실제 길이는 다를 수 있는 까닭을 예를 들어 설명해 보세요.','{}'::text[],false,'{"seq":10,"concept":"M2-1-u4-C5","difficulty":4,"kind":"essay","stem":"두 물건이 모두 「약 6 cm」인데 실제 길이는 다를 수 있는 까닭을 예를 들어 설명해 보세요.","answer_guide":{"answer":"예: 한 물건은 끝이 6보다 조금 앞(5와 6 사이)이고, 다른 물건은 6보다 조금 뒤(6과 7 사이)일 수 있다. 둘 다 6에 가장 가까워 약 6 cm지만 실제 길이는 다르다.","scoring_points":["약 6 cm가 되는 두 경우를 들었는가","6보다 조금 짧은 것과 조금 긴 것을 구별했는가","실제 길이가 다를 수 있다고 결론지었는가"]},"explanation":["6보다 조금 짧은 것.","6보다 조금 긴 것.","실제는 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_L07_basic#1','math',2,1,'u4','L07','g2_1_math_u4_L07_basic','lesson_basic','M2-1-u4-C6',1,'mc','auto','엄지손톱의 너비는 약 몇 cm일까요?',ARRAY['M2-1-u4-X14']::text[],true,'{"seq":1,"concept":"M2-1-u4-C6","difficulty":1,"kind":"mc","stem":"엄지손톱의 너비는 약 몇 cm일까요?","options":[{"t":"약 1 cm","correct":true},{"t":"약 5 cm","mis":"M2-1-u4-X14"},{"t":"약 10 cm","mis":"M2-1-u4-X14"}],"explanation":["엄지손톱은 약 1 cm예요.","약 5 cm는 가운뎃손가락, 약 10 cm는 한 뼘쯤이에요.","엄지손톱을 1 cm 기준으로 써요."],"variant_rule":{"alt":[{"stem":"가운뎃손가락의 길이는 약 몇 cm일까요?","options":[{"t":"약 5 cm","correct":true},{"t":"약 1 cm","mis":"M2-1-u4-X14"},{"t":"약 50 cm","mis":"M2-1-u4-X14"}],"explanation":["가운뎃손가락은 약 5 cm예요.","약 1 cm는 엄지손톱쯤이에요.","50 cm는 너무 길어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_L07_basic#2','math',2,1,'u4','L07','g2_1_math_u4_L07_basic','lesson_basic','M2-1-u4-C6',1,'mc','auto','2학년 어린이의 한 뼘은 약 몇 cm일까요?',ARRAY['M2-1-u4-X14']::text[],true,'{"seq":2,"concept":"M2-1-u4-C6","difficulty":1,"kind":"mc","stem":"2학년 어린이의 한 뼘은 약 몇 cm일까요?","options":[{"t":"약 10 cm","correct":true},{"t":"약 1 cm","mis":"M2-1-u4-X14"},{"t":"약 50 cm","mis":"M2-1-u4-X14"}],"explanation":["한 뼘은 약 10 cm쯤이에요.","엄지손톱(약 1 cm)보다 훨씬 길어요.","50 cm는 팔 길이에 가까워요."],"variant_rule":{"alt":[{"stem":"약 10 cm를 어림할 때 기준으로 쓰기 좋은 것은 어느 것인가요?","options":[{"t":"한 뼘","correct":true},{"t":"엄지손톱","mis":"M2-1-u4-X14"},{"t":"한 걸음","mis":"M2-1-u4-X14"}],"explanation":["한 뼘이 약 10 cm예요.","엄지손톱은 약 1 cm예요.","한 걸음은 10 cm보다 훨씬 길어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_L07_basic#3','math',2,1,'u4','L07','g2_1_math_u4_L07_basic','lesson_basic','M2-1-u4-C6',1,'mc','auto','자 없이 크레파스 길이를 어림했어요. 알맞게 말한 것은 어느 것인가요?',ARRAY['M2-1-u4-X12','M2-1-u4-X14']::text[],true,'{"seq":3,"concept":"M2-1-u4-C6","difficulty":1,"kind":"mc","stem":"자 없이 크레파스 길이를 어림했어요. 알맞게 말한 것은 어느 것인가요?","options":[{"t":"「약 8 cm예요.」","correct":true},{"t":"「딱 8 cm예요.」","mis":"M2-1-u4-X12"},{"t":"「아주 길어요.」","mis":"M2-1-u4-X14"}],"explanation":["어림한 길이는 정확하지 않아요.","그래서 「약 몇 cm」로 말해요.","「아주 길어요」는 길이를 알려 주지 않아요."],"variant_rule":{"alt":[{"stem":"자 없이 지우개 길이를 어림했어요. 알맞게 말한 것은 어느 것인가요?","options":[{"t":"「약 4 cm예요.」","correct":true},{"t":"「정확히 4 cm예요.」","mis":"M2-1-u4-X12"},{"t":"「작아요.」","mis":"M2-1-u4-X14"}],"explanation":["어림한 길이는 「약」을 붙여 말해요.","정확히 잰 것이 아니니까요.","「작아요」는 길이를 알려 주지 않아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_L07_basic#4','math',2,1,'u4','L07','g2_1_math_u4_L07_basic','lesson_basic','M2-1-u4-C6',1,'ox','auto','어림한 길이도 「약 몇 cm」로 말해요.',ARRAY['M2-1-u4-X12']::text[],true,'{"seq":4,"concept":"M2-1-u4-C6","difficulty":1,"kind":"ox","stem":"어림한 길이도 「약 몇 cm」로 말해요.","answer":"O","reason_options":[{"t":"자로 정확히 잰 것이 아니니까","correct":true},{"t":"어림해도 정확한 길이니까","mis":"M2-1-u4-X12"}],"mis":"M2-1-u4-X12","explanation":["어림은 짐작한 길이예요.","그래서 「약」을 붙여요.","예: 약 10 cm"],"variant_rule":{"alt":[{"stem":"어림한 길이는 「딱 몇 cm」라고 말해야 해요.","answer":"X","reason_options":[{"t":"어림은 짐작이라 「약 몇 cm」로 말하니까","correct":true},{"t":"어림도 자로 잰 것과 같으니까","mis":"M2-1-u4-X12"}],"explanation":["어림은 정확하지 않아요.","「약 몇 cm」로 말해요.","정확한 길이는 자로 재야 알아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_L07_basic#5','math',2,1,'u4','L07','g2_1_math_u4_L07_basic','lesson_basic','M2-1-u4-C6',2,'match','auto','몸의 부분과 어림 기준이 되는 길이를 알맞게 이어 보세요.','{}'::text[],true,'{"seq":5,"concept":"M2-1-u4-C6","difficulty":2,"kind":"match","stem":"몸의 부분과 어림 기준이 되는 길이를 알맞게 이어 보세요.","pairs":[{"l":"엄지손톱의 너비","r":"약 1 cm"},{"l":"가운뎃손가락의 길이","r":"약 5 cm"},{"l":"한 뼘","r":"약 10 cm"}],"mis":"M2-1-u4-X14","explanation":["엄지손톱은 약 1 cm예요.","가운뎃손가락은 약 5 cm예요.","한 뼘은 약 10 cm예요."],"variant_rule":{"alt":[{"stem":"기준과 어림한 길이를 알맞게 이어 보세요.","pairs":[{"l":"엄지손톱 3개만큼","r":"약 3 cm"},{"l":"가운뎃손가락 2개만큼","r":"약 10 cm"},{"l":"한 뼘 2개만큼","r":"약 20 cm"}],"explanation":["엄지손톱 1개가 약 1 cm라서 3개는 약 3 cm예요.","가운뎃손가락 1개가 약 5 cm라서 2개는 약 10 cm예요.","한 뼘이 약 10 cm라서 2개는 약 20 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_L07_basic#6','math',2,1,'u4','L07','g2_1_math_u4_L07_basic','lesson_basic','M2-1-u4-C6',2,'mc','auto','막대가 가운뎃손가락(약 5 cm)의 두 배쯤 되어 보여요. 막대의 길이를 어떻게 어림할까요?',ARRAY['M2-1-u4-X14','M2-1-u4-X05']::text[],true,'{"seq":6,"concept":"M2-1-u4-C6","difficulty":2,"kind":"mc","stem":"막대가 가운뎃손가락(약 5 cm)의 두 배쯤 되어 보여요. 막대의 길이를 어떻게 어림할까요?","options":[{"t":"약 10 cm","correct":true},{"t":"약 7 cm","mis":"M2-1-u4-X14"},{"t":"약 2 cm","mis":"M2-1-u4-X05"}],"explanation":["가운뎃손가락은 약 5 cm예요.","두 배쯤이면 5 cm가 2번, 약 10 cm예요.","기준이 몇 번쯤인지 견주어 어림해요."],"variant_rule":{"alt":[{"stem":"리본이 한 뼘(약 10 cm)의 두 배쯤 되어 보여요. 리본의 길이를 어떻게 어림할까요?","options":[{"t":"약 20 cm","correct":true},{"t":"약 12 cm","mis":"M2-1-u4-X14"},{"t":"약 2 cm","mis":"M2-1-u4-X05"}],"explanation":["한 뼘은 약 10 cm예요.","두 배쯤이면 10 cm가 2번, 약 20 cm예요.","기준이 몇 번쯤인지 견주어 어림해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_L07_basic#7','math',2,1,'u4','L07','g2_1_math_u4_L07_basic','lesson_basic','M2-1-u4-C6',2,'sa','auto','지우개가 엄지손톱(약 1 cm) 6개를 늘어놓은 만큼쯤 되어 보여요. 지우개의 길이를 약 몇 cm로 어림할까요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M2-1-u4-C6","difficulty":2,"kind":"sa","stem":"지우개가 엄지손톱(약 1 cm) 6개를 늘어놓은 만큼쯤 되어 보여요. 지우개의 길이를 약 몇 cm로 어림할까요? 숫자로 쓰세요.","answer":["6"],"explanation":["엄지손톱 1개가 약 1 cm예요.","6개만큼이면 약 6 cm예요.","기준을 몇 번 이었는지 세요."],"variant_rule":{"alt":[{"stem":"클립이 엄지손톱(약 1 cm) 3개를 늘어놓은 만큼쯤 되어 보여요. 클립의 길이를 약 몇 cm로 어림할까요? 숫자로 쓰세요.","answer":["3"],"explanation":["엄지손톱 1개가 약 1 cm예요.","3개만큼이면 약 3 cm예요.","기준을 몇 번 이었는지 세요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_L07_basic#8','math',2,1,'u4','L07','g2_1_math_u4_L07_basic','lesson_basic','M2-1-u4-C6',2,'mc','auto','내가 어림한 길이가 맞았는지 알아보려면 어떻게 하면 좋을까요?',ARRAY['M2-1-u4-X14']::text[],true,'{"seq":8,"concept":"M2-1-u4-C6","difficulty":2,"kind":"mc","stem":"내가 어림한 길이가 맞았는지 알아보려면 어떻게 하면 좋을까요?","options":[{"t":"자로 재어 어림한 길이와 견주어 봐요","correct":true},{"t":"친구에게 맞았는지 물어봐요","mis":"M2-1-u4-X14"},{"t":"한 번 더 어림만 해요","mis":"M2-1-u4-X14"}],"explanation":["자로 재면 실제 길이를 알 수 있어요.","어림과 실제를 견주어 봐요.","견주어 볼수록 어림이 정확해져요."],"variant_rule":{"alt":[{"stem":"어림을 더 잘하게 되려면 어떻게 하면 좋을까요?","options":[{"t":"어림한 뒤 자로 재어 얼마나 차이 나는지 살펴봐요","correct":true},{"t":"자로 재지 말고 어림만 계속해요","mis":"M2-1-u4-X14"},{"t":"아무 숫자나 크게 말해요","mis":"M2-1-u4-X14"}],"explanation":["어림하고 자로 재어 확인해요.","차이를 보고 다음 어림에 써요.","그러면 어림이 점점 정확해져요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_L07_basic#9','math',2,1,'u4','L07','g2_1_math_u4_L07_basic','lesson_basic','M2-1-u4-C6',2,'ox','auto','어림한 길이는 자로 잰 길이와 언제나 똑같아요.',ARRAY['M2-1-u4-X14']::text[],true,'{"seq":9,"concept":"M2-1-u4-C6","difficulty":2,"kind":"ox","stem":"어림한 길이는 자로 잰 길이와 언제나 똑같아요.","answer":"X","reason_options":[{"t":"어림은 짐작이라 실제와 조금 다를 수 있으니까","correct":true},{"t":"잘 어림하면 언제나 똑같으니까","mis":"M2-1-u4-X14"}],"mis":"M2-1-u4-X14","explanation":["어림은 실제 길이와 조금 다를 수 있어요.","그래서 「약」을 붙여요.","자로 재어 확인해요."],"variant_rule":{"alt":[{"stem":"어림한 뒤 자로 재면 어림이 얼마나 맞았는지 알 수 있어요.","answer":"O","reason_options":[{"t":"자로 잰 실제 길이와 견줄 수 있으니까","correct":true},{"t":"자로 재면 어림이 필요 없으니까","mis":"M2-1-u4-X14"}],"explanation":["어림 → 자로 재기 → 견주기.","차이를 보면 어림이 얼마나 맞았는지 알아요.","다음 어림이 더 정확해져요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_L07_basic#10','math',2,1,'u4','L07','g2_1_math_u4_L07_basic','lesson_basic','M2-1-u4-C6',3,'error','auto','친구들이 물건의 길이를 어림했어요. 알맞지 않게 어림한 친구는 누구인가요?',ARRAY['M2-1-u4-X14','M2-1-u4-X15']::text[],true,'{"seq":10,"concept":"M2-1-u4-C6","difficulty":3,"kind":"error","stem":"친구들이 물건의 길이를 어림했어요. 알맞지 않게 어림한 친구는 누구인가요?","options":[{"t":"현우 — 「숟가락은 약 1 cm야.」","correct":true,"mis_target":"M2-1-u4-X14"},{"t":"다은 — 「지우개는 약 4 cm야.」","mis":"M2-1-u4-X15"},{"t":"로아 — 「연필은 약 15 cm야.」","mis":"M2-1-u4-X15"}],"explanation":["약 1 cm는 엄지손톱만큼이에요.","숟가락은 그보다 훨씬 길어요.","다은이와 로아의 어림은 알맞아요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 친구들이 물건의 길이를 어림했어요. 알맞지 않게 어림한 친구는 누구인가요?","options":[{"t":"하준 — 「클립은 약 30 cm야.」","correct":true,"mis_target":"M2-1-u4-X14"},{"t":"지우 — 「클립은 약 3 cm야.」","mis":"M2-1-u4-X15"},{"t":"서아 — 「크레파스는 약 7 cm야.」","mis":"M2-1-u4-X15"}],"explanation":["약 30 cm는 뼘 세 번만큼이에요.","클립은 엄지손톱 몇 개쯤이에요.","지우와 서아의 어림은 알맞아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_L07_challenge#1','math',2,1,'u4','L07','g2_1_math_u4_L07_challenge','lesson_challenge','M2-1-u4-C6',2,'mc','auto','길이가 약 5 cm에 가장 가까운 것은 어느 것인가요?',ARRAY['M2-1-u4-X14']::text[],false,'{"seq":1,"concept":"M2-1-u4-C6","difficulty":2,"kind":"mc","stem":"길이가 약 5 cm에 가장 가까운 것은 어느 것인가요?","options":[{"t":"가운뎃손가락의 길이","correct":true},{"t":"교실 문의 높이","mis":"M2-1-u4-X14"},{"t":"쌀 한 톨의 길이","mis":"M2-1-u4-X14"}],"explanation":["가운뎃손가락이 약 5 cm예요.","교실 문은 아주 높고, 쌀 한 톨은 아주 짧아요.","기준 길이를 몸으로 기억해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_L07_challenge#2','math',2,1,'u4','L07','g2_1_math_u4_L07_challenge','lesson_challenge','M2-1-u4-C6',2,'mc','auto','연필이 한 뼘(약 10 cm)보다 조금 더 길어요. 연필의 길이는 약 몇 cm로 어림하면 알맞을까요?',ARRAY['M2-1-u4-X14']::text[],false,'{"seq":2,"concept":"M2-1-u4-C6","difficulty":2,"kind":"mc","stem":"연필이 한 뼘(약 10 cm)보다 조금 더 길어요. 연필의 길이는 약 몇 cm로 어림하면 알맞을까요?","options":[{"t":"약 12 cm","correct":true},{"t":"약 2 cm","mis":"M2-1-u4-X14"},{"t":"약 50 cm","mis":"M2-1-u4-X14"}],"explanation":["한 뼘은 약 10 cm예요.","조금 더 길면 10 cm보다 조금 커요.","그래서 약 12 cm가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_L07_challenge#3','math',2,1,'u4','L07','g2_1_math_u4_L07_challenge','lesson_challenge','M2-1-u4-C6',3,'mc','auto','하람이는 풀의 길이를 약 7 cm로 어림했는데 자로 재어 보니 8 cm였어요. 바르게 말한 것은 어느 것인가요?',ARRAY['M2-1-u4-X14']::text[],false,'{"seq":3,"concept":"M2-1-u4-C6","difficulty":3,"kind":"mc","stem":"하람이는 풀의 길이를 약 7 cm로 어림했는데 자로 재어 보니 8 cm였어요. 바르게 말한 것은 어느 것인가요?","options":[{"t":"어림이 실제보다 1 cm 짧았어요","correct":true},{"t":"어림이 틀렸으니 어림은 쓸모없어요","mis":"M2-1-u4-X14"},{"t":"자로 잰 길이가 잘못됐어요","mis":"M2-1-u4-X14"}],"explanation":["어림 약 7 cm, 실제 8 cm예요.","8 − 7 = 1, 1 cm 차이예요.","차이를 알면 다음 어림이 더 정확해져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_L07_challenge#4','math',2,1,'u4','L07','g2_1_math_u4_L07_challenge','lesson_challenge','M2-1-u4-C6',3,'mc','auto','실제 길이가 9 cm인 리본을 지안이는 약 8 cm, 도윤이는 약 12 cm로 어림했어요. 실제 길이에 더 가깝게 어림한 친구는 누구인가요?',ARRAY['M2-1-u4-X15','M2-1-u4-X14']::text[],false,'{"seq":4,"concept":"M2-1-u4-C6","difficulty":3,"kind":"mc","stem":"실제 길이가 9 cm인 리본을 지안이는 약 8 cm, 도윤이는 약 12 cm로 어림했어요. 실제 길이에 더 가깝게 어림한 친구는 누구인가요?","options":[{"t":"지안","correct":true},{"t":"도윤","mis":"M2-1-u4-X15"},{"t":"두 친구 모두 똑같이 가까워요","mis":"M2-1-u4-X14"}],"explanation":["지안이는 9 − 8 = 1, 1 cm 차이예요.","도윤이는 12 − 9 = 3, 3 cm 차이예요.","차이가 작은 지안이가 더 가깝게 어림했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_L07_challenge#5','math',2,1,'u4','L07','g2_1_math_u4_L07_challenge','lesson_challenge','M2-1-u4-C6',3,'ox','auto','기준이 되는 길이를 알고 있으면 자가 없어도 길이를 어림할 수 있어요.',ARRAY['M2-1-u4-X14']::text[],false,'{"seq":5,"concept":"M2-1-u4-C6","difficulty":3,"kind":"ox","stem":"기준이 되는 길이를 알고 있으면 자가 없어도 길이를 어림할 수 있어요.","answer":"O","reason_options":[{"t":"기준이 몇 번쯤인지 견주면 되니까","correct":true},{"t":"자가 없으면 길이를 알 수 없으니까","mis":"M2-1-u4-X14"}],"mis":"M2-1-u4-X14","explanation":["엄지손톱·가운뎃손가락·한 뼘이 기준이 돼요.","기준이 몇 번쯤인지 견주어 어림해요.","자가 없어도 「약 몇 cm」로 말할 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_L07_challenge#6','math',2,1,'u4','L07','g2_1_math_u4_L07_challenge','lesson_challenge','M2-1-u4-C6',3,'error','auto','친구들이 어림한 길이를 말했어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['M2-1-u4-X12','M2-1-u4-X15']::text[],false,'{"seq":6,"concept":"M2-1-u4-C6","difficulty":3,"kind":"error","stem":"친구들이 어림한 길이를 말했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"소율 — 「이 책갈피는 딱 6 cm야.」 (어림만 했어요)","correct":true,"mis_target":"M2-1-u4-X12"},{"t":"준우 — 「이 책갈피는 약 6 cm쯤이야.」","mis":"M2-1-u4-X15"},{"t":"민지 — 「가운뎃손가락보다 조금 기니까 약 6 cm야.」","mis":"M2-1-u4-X15"}],"explanation":["어림한 길이는 「약」을 붙여 말해요.","소율이는 어림했는데 「딱」이라고 말했어요.","준우와 민지는 알맞게 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_L07_challenge#7','math',2,1,'u4','L07','g2_1_math_u4_L07_challenge','lesson_challenge','M2-1-u4-C6',3,'sa','auto','리본이 가운뎃손가락(약 5 cm) 3개를 이은 만큼쯤 되어 보여요. 리본의 길이를 약 몇 cm로 어림할까요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":7,"concept":"M2-1-u4-C6","difficulty":3,"kind":"sa","stem":"리본이 가운뎃손가락(약 5 cm) 3개를 이은 만큼쯤 되어 보여요. 리본의 길이를 약 몇 cm로 어림할까요? 숫자로 쓰세요.","answer":["15"],"explanation":["가운뎃손가락 1개가 약 5 cm예요.","3개면 5, 10, 15 — 약 15 cm예요.","기준을 몇 번 이었는지 세요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_L07_challenge#8','math',2,1,'u4','L07','g2_1_math_u4_L07_challenge','lesson_challenge','M2-1-u4-C6',4,'mc','auto','막대를 엄지손톱(약 1 cm)으로 3번, 이어서 가운뎃손가락(약 5 cm)으로 1번 재었어요. 막대의 길이는 약 몇 cm일까요?',ARRAY['M2-1-u4-X05','M2-1-u4-X14']::text[],false,'{"seq":8,"concept":"M2-1-u4-C6","difficulty":4,"kind":"mc","stem":"막대를 엄지손톱(약 1 cm)으로 3번, 이어서 가운뎃손가락(약 5 cm)으로 1번 재었어요. 막대의 길이는 약 몇 cm일까요?","options":[{"t":"약 8 cm","correct":true},{"t":"약 4 cm","mis":"M2-1-u4-X05"},{"t":"약 15 cm","mis":"M2-1-u4-X14"}],"explanation":["엄지손톱 3번은 약 3 cm예요.","가운뎃손가락 1번은 약 5 cm예요.","3 + 5 = 8, 약 8 cm예요. 횟수만 더하면 안 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_L07_challenge#9','math',2,1,'u4','L07','g2_1_math_u4_L07_challenge','lesson_challenge','M2-1-u4-C6',4,'essay','teacher','교실에 있는 물건 하나를 골라 몸의 기준(엄지손톱·가운뎃손가락·한 뼘)으로 어떻게 어림하는지 설명해 보세요.','{}'::text[],false,'{"seq":9,"concept":"M2-1-u4-C6","difficulty":4,"kind":"essay","stem":"교실에 있는 물건 하나를 골라 몸의 기준(엄지손톱·가운뎃손가락·한 뼘)으로 어떻게 어림하는지 설명해 보세요.","answer_guide":{"answer":"예: 필통을 어림한다. 한 뼘(약 10 cm)과 엄지손톱(약 1 cm) 두 개만큼쯤이라 약 12 cm로 어림한다.","scoring_points":["물건을 하나 정했는가","몸의 기준을 몇 번쯤인지 견주었는가","「약 몇 cm」로 어림한 길이를 썼는가"]},"explanation":["물건 정하기.","기준과 견주기.","약 몇 cm."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_L07_challenge#10','math',2,1,'u4','L07','g2_1_math_u4_L07_challenge','lesson_challenge','M2-1-u4-C6',4,'essay','teacher','길이를 어림한 뒤 자로 재어 확인하면 좋은 점을 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"M2-1-u4-C6","difficulty":4,"kind":"essay","stem":"길이를 어림한 뒤 자로 재어 확인하면 좋은 점을 써 보세요.","answer_guide":{"answer":"예: 어림과 실제 길이의 차이를 알 수 있다. 차이를 보고 다음에 어림할 때 기준을 고쳐 쓰면 어림이 점점 정확해진다.","scoring_points":["어림과 실제를 견줄 수 있다고 썼는가","차이를 알 수 있다고 썼는가","다음 어림이 더 정확해진다고 썼는가"]},"explanation":["견주기.","차이 알기.","더 정확해져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_review_a#1','math',2,1,'u4','','g2_1_math_u4_review_a','unit_review','M2-1-u4-C1',1,'mc','auto','끈으로 본뜬 세 길이를 왼쪽 끝을 맞춰 놓았어요. 가장 긴 것은 어느 것인가요?',ARRAY['M2-1-u4-X15','M2-1-u4-X01']::text[],false,'{"seq":1,"concept":"M2-1-u4-C1","difficulty":1,"kind":"mc","stem":"끈으로 본뜬 세 길이를 왼쪽 끝을 맞춰 놓았어요. 가장 긴 것은 어느 것인가요?","options":[{"t":"다","correct":true},{"t":"가","mis":"M2-1-u4-X15"},{"t":"나","mis":"M2-1-u4-X01"}],"explanation":["왼쪽 끝이 맞추어져 있어요.","가장 많이 나온 다가 가장 길어요.","가는 가장 짧아요."],"asset":{"type":"len_bars","rows":[{"label":"가","len":3},{"label":"나","len":6},{"label":"다","len":9}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_review_a#2','math',2,1,'u4','','g2_1_math_u4_review_a','unit_review','M2-1-u4-C2',1,'mc','auto','같은 길이를 잴 때 단위의 길이가 길수록 잰 횟수는 어떻게 될까요?',ARRAY['M2-1-u4-X04','M2-1-u4-X05']::text[],false,'{"seq":2,"concept":"M2-1-u4-C2","difficulty":1,"kind":"mc","stem":"같은 길이를 잴 때 단위의 길이가 길수록 잰 횟수는 어떻게 될까요?","options":[{"t":"적어져요","correct":true},{"t":"많아져요","mis":"M2-1-u4-X04"},{"t":"언제나 똑같아요","mis":"M2-1-u4-X05"}],"explanation":["긴 단위는 한 번에 많이 재요.","긴 단위는 횟수가 적고, 짧은 단위는 횟수가 많아요.","같은 길이를 잴 때의 약속이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_review_a#3','math',2,1,'u4','','g2_1_math_u4_review_a','unit_review','M2-1-u4-C3',1,'mc','auto','1 cm는 무엇이라고 읽나요?',ARRAY['M2-1-u4-X07']::text[],false,'{"seq":3,"concept":"M2-1-u4-C3","difficulty":1,"kind":"mc","stem":"1 cm는 무엇이라고 읽나요?","options":[{"t":"1 센티미터","correct":true},{"t":"1 미터","mis":"M2-1-u4-X07"},{"t":"1 칸","mis":"M2-1-u4-X07"}],"explanation":["cm는 센티미터라고 읽어요.","1 cm는 1 센티미터예요.","미터(m)는 다른 단위예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_review_a#4','math',2,1,'u4','','g2_1_math_u4_review_a','unit_review','M2-1-u4-C4',1,'mc','auto','크레파스의 길이는 몇 cm일까요?',ARRAY['M2-1-u4-X09','M2-1-u4-X10']::text[],true,'{"seq":4,"concept":"M2-1-u4-C4","difficulty":1,"kind":"mc","stem":"크레파스의 길이는 몇 cm일까요?","explanation":["크레파스의 한쪽 끝이 눈금 0에 맞춰져 있어요.","다른 쪽 끝의 눈금이 7이니 7 cm예요.","자의 숫자는 1 cm가 몇 번인지를 나타내요."],"variant_rule":{"cm":{"ask":"read"}},"options":[{"t":"7 cm","correct":true},{"t":"8 cm","mis":"M2-1-u4-X09"},{"t":"6 cm","mis":"M2-1-u4-X10"}],"asset":{"type":"ruler","len":7,"label":"크레파스"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_review_a#5','math',2,1,'u4','','g2_1_math_u4_review_a','unit_review','M2-1-u4-C3',1,'mc','auto','1 cm가 몇 번일까요? 막대의 길이는 몇 cm일까요?',ARRAY['M2-1-u4-X09','M2-1-u4-X03']::text[],true,'{"seq":5,"concept":"M2-1-u4-C3","difficulty":1,"kind":"mc","stem":"1 cm가 몇 번일까요? 막대의 길이는 몇 cm일까요?","explanation":["1 cm 칸을 하나씩 세면 6칸이에요.","1 cm가 6번이면 6 cm예요.","칸 사이의 선이 아니라 칸을 세어요."],"variant_rule":{"cm":{"ask":"cells"}},"options":[{"t":"6 cm","correct":true},{"t":"7 cm","mis":"M2-1-u4-X09"},{"t":"5 cm","mis":"M2-1-u4-X03"}],"asset":{"type":"ruler","len":6,"label":"막대","mode":"cells"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_review_a#6','math',2,1,'u4','','g2_1_math_u4_review_a','unit_review','M2-1-u4-C4',1,'mc','auto','자의 숫자 0은 무엇을 뜻할까요?',ARRAY['M2-1-u4-X10']::text[],false,'{"seq":6,"concept":"M2-1-u4-C4","difficulty":1,"kind":"mc","stem":"자의 숫자 0은 무엇을 뜻할까요?","options":[{"t":"길이를 재기 시작하는 곳","correct":true},{"t":"길이의 끝","mis":"M2-1-u4-X10"},{"t":"가장 긴 길이","mis":"M2-1-u4-X10"}],"explanation":["0은 시작점이에요.","물건 한쪽 끝을 0에 맞추고 다른 끝 눈금을 읽어요.","0에 없으면 1 cm 칸을 세요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_review_a#7','math',2,1,'u4','','g2_1_math_u4_review_a','unit_review','M2-1-u4-C5',1,'mc','auto','끝이 눈금 4와 5 사이에 있고 4에 더 가까워요. 길이를 바르게 말한 것은 어느 것인가요?',ARRAY['M2-1-u4-X11','M2-1-u4-X12']::text[],false,'{"seq":7,"concept":"M2-1-u4-C5","difficulty":1,"kind":"mc","stem":"끝이 눈금 4와 5 사이에 있고 4에 더 가까워요. 길이를 바르게 말한 것은 어느 것인가요?","options":[{"t":"약 4 cm","correct":true},{"t":"약 5 cm","mis":"M2-1-u4-X11"},{"t":"4 cm","mis":"M2-1-u4-X12"}],"explanation":["끝에서 더 가까운 눈금을 찾아요.","4에 더 가까워 약 4 cm예요.","딱 맞지 않으면 「약」을 붙여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_review_a#8','math',2,1,'u4','','g2_1_math_u4_review_a','unit_review','M2-1-u4-C6',1,'mc','auto','엄지손톱의 너비는 약 몇 cm일까요?',ARRAY['M2-1-u4-X14']::text[],false,'{"seq":8,"concept":"M2-1-u4-C6","difficulty":1,"kind":"mc","stem":"엄지손톱의 너비는 약 몇 cm일까요?","options":[{"t":"약 1 cm","correct":true},{"t":"약 5 cm","mis":"M2-1-u4-X14"},{"t":"약 10 cm","mis":"M2-1-u4-X14"}],"explanation":["엄지손톱은 약 1 cm예요.","엄지손톱 약 1 cm, 가운뎃손가락 약 5 cm, 한 뼘 약 10 cm예요.","기준을 알면 어림할 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_review_a#9','math',2,1,'u4','','g2_1_math_u4_review_a','unit_review','M2-1-u4-C1',2,'ox','auto','본뜬 종이띠를 비교할 때는 한쪽 끝을 맞춰야 해요.',ARRAY['M2-1-u4-X01']::text[],false,'{"seq":9,"concept":"M2-1-u4-C1","difficulty":2,"kind":"ox","stem":"본뜬 종이띠를 비교할 때는 한쪽 끝을 맞춰야 해요.","answer":"O","reason_options":[{"t":"끝을 맞춰야 남는 쪽으로 더 긴 것을 알 수 있으니까","correct":true},{"t":"오른쪽 끝만 보면 되니까","mis":"M2-1-u4-X01"}],"mis":"M2-1-u4-X01","explanation":["시작점을 똑같이 맞춰요.","그다음 남는 쪽이 더 길어요.","본뜬 것은 한쪽 끝을 맞추어 비교해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_review_a#10','math',2,1,'u4','','g2_1_math_u4_review_a','unit_review','M2-1-u4-C2',2,'mc','auto','막대의 길이는 클립으로 몇 번일까요?',ARRAY['M2-1-u4-X03']::text[],true,'{"seq":10,"concept":"M2-1-u4-C2","difficulty":2,"kind":"mc","stem":"막대의 길이는 클립으로 몇 번일까요?","explanation":["클립을 빈틈없이 이어 놓은 것을 세어요.","클립으로 4번이에요.","겹치거나 띄우지 않고 이어서 세어요."],"variant_rule":{"cm":{"ask":"unit"}},"options":[{"t":"4번","correct":true},{"t":"5번","mis":"M2-1-u4-X03"},{"t":"3번","mis":"M2-1-u4-X03"}],"asset":{"type":"ruler","len":8,"label":"막대","mode":"unit","unit":"📎","size":2}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_review_a#11','math',2,1,'u4','','g2_1_math_u4_review_a','unit_review','M2-1-u4-C4',2,'sa','auto','종이띠가 자의 눈금 0에 놓여 있지 않아요. 종이띠의 길이는 몇 cm일까요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":11,"concept":"M2-1-u4-C4","difficulty":2,"kind":"sa","stem":"종이띠가 자의 눈금 0에 놓여 있지 않아요. 종이띠의 길이는 몇 cm일까요? 숫자로 쓰세요.","explanation":["2부터 8까지 1 cm 칸을 세어요.","1 cm가 6번이니 6 cm예요.","끝 눈금 숫자 8을 그대로 읽으면 안 돼요."],"variant_rule":{"cm":{"ask":"off"}},"answer":["6"],"asset":{"type":"ruler","len":6,"label":"종이띠","s":2}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_review_a#12','math',2,1,'u4','','g2_1_math_u4_review_a','unit_review','M2-1-u4-C5',2,'mc','auto','색연필의 길이는 약 몇 cm일까요?',ARRAY['M2-1-u4-X11','M2-1-u4-X12']::text[],true,'{"seq":12,"concept":"M2-1-u4-C5","difficulty":2,"kind":"mc","stem":"색연필의 길이는 약 몇 cm일까요?","explanation":["끝이 눈금 6과 7 사이에 있어요.","6에 더 가까우니 약 6 cm예요.","눈금 사이에 있으면 가까운 쪽 숫자를 읽고 「약」을 붙여요."],"variant_rule":{"cm":{"ask":"approx"}},"options":[{"t":"약 6 cm","correct":true},{"t":"약 7 cm","mis":"M2-1-u4-X11"},{"t":"6 cm","mis":"M2-1-u4-X12"}],"asset":{"type":"ruler","len":6.2,"label":"색연필"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_review_a#13','math',2,1,'u4','','g2_1_math_u4_review_a','unit_review','M2-1-u4-C2',2,'mc','auto','민호는 책상을 연필로 6번, 지안이는 다른 책상을 뼘으로 4번 재었어요. 어느 책상이 더 긴지 바르게 말한 것은 어느 것인가요?',ARRAY['M2-1-u4-X05','M2-1-u4-X04']::text[],false,'{"seq":13,"concept":"M2-1-u4-C2","difficulty":2,"kind":"mc","stem":"민호는 책상을 연필로 6번, 지안이는 다른 책상을 뼘으로 4번 재었어요. 어느 책상이 더 긴지 바르게 말한 것은 어느 것인가요?","options":[{"t":"단위가 달라서 횟수만으로는 알 수 없어요","correct":true},{"t":"6번인 민호의 책상이 더 길어요","mis":"M2-1-u4-X05"},{"t":"뼘이 더 짧으니 지안이의 책상이 더 길어요","mis":"M2-1-u4-X04"}],"explanation":["두 친구가 쓴 단위가 달라요.","단위가 다르면 횟수만 보고 길이를 견줄 수 없어요.","같은 단위로 재어야 비교할 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_review_a#14','math',2,1,'u4','','g2_1_math_u4_review_a','unit_review','M2-1-u4-C3',2,'sa','auto','1 cm가 7번이면 몇 cm일까요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":14,"concept":"M2-1-u4-C3","difficulty":2,"kind":"sa","stem":"1 cm가 7번이면 몇 cm일까요? 숫자로 쓰세요.","answer":["7"],"explanation":["1 cm가 몇 번인지 세면 길이예요.","1 cm가 7번이면 7 cm예요.","7 센티미터라고 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_review_a#15','math',2,1,'u4','','g2_1_math_u4_review_a','unit_review','M2-1-u4-C6',2,'mc','auto','막대가 가운뎃손가락(약 5 cm)의 두 배쯤 되어 보여요. 길이를 어떻게 어림할까요?',ARRAY['M2-1-u4-X14','M2-1-u4-X05']::text[],false,'{"seq":15,"concept":"M2-1-u4-C6","difficulty":2,"kind":"mc","stem":"막대가 가운뎃손가락(약 5 cm)의 두 배쯤 되어 보여요. 길이를 어떻게 어림할까요?","options":[{"t":"약 10 cm","correct":true},{"t":"약 7 cm","mis":"M2-1-u4-X14"},{"t":"약 2 cm","mis":"M2-1-u4-X05"}],"explanation":["가운뎃손가락은 약 5 cm예요.","5 cm가 2번이면 약 10 cm예요.","기준이 몇 번쯤인지 견주어 어림해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_review_a#16','math',2,1,'u4','','g2_1_math_u4_review_a','unit_review','M2-1-u4-C5',2,'ox','auto','두 물건이 모두 약 5 cm라면 실제 길이도 똑같아요.',ARRAY['M2-1-u4-X13']::text[],false,'{"seq":16,"concept":"M2-1-u4-C5","difficulty":2,"kind":"ox","stem":"두 물건이 모두 약 5 cm라면 실제 길이도 똑같아요.","answer":"X","reason_options":[{"t":"약 5 cm는 5 cm 가까이라는 뜻이라 다를 수 있으니까","correct":true},{"t":"「약 5 cm」로 같으니까","mis":"M2-1-u4-X13"}],"mis":"M2-1-u4-X13","explanation":["약 5 cm는 5에 가깝다는 뜻이에요.","실제 길이는 조금씩 다를 수 있어요.","「약」은 딱 맞지 않을 때 붙여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_review_a#17','math',2,1,'u4','','g2_1_math_u4_review_a','unit_review','M2-1-u4-C1',3,'mc','auto','세 종이띠를 놓았어요. 가장 긴 것은 어느 것인가요? (칸 하나의 길이는 같아요.)',ARRAY['M2-1-u4-X01','M2-1-u4-X15']::text[],false,'{"seq":17,"concept":"M2-1-u4-C1","difficulty":3,"kind":"mc","stem":"세 종이띠를 놓았어요. 가장 긴 것은 어느 것인가요? (칸 하나의 길이는 같아요.)","options":[{"t":"가","correct":true},{"t":"다","mis":"M2-1-u4-X01"},{"t":"나","mis":"M2-1-u4-X15"}],"explanation":["세 종이띠의 시작점이 달라요.","칸을 세면 가 8칸, 나 6칸, 다 7칸이에요.","오른쪽 끝이 가장 많이 나온 것이 가장 긴 것이 아니에요."],"asset":{"type":"len_bars","rows":[{"label":"가","len":8},{"label":"나","len":6,"off":1},{"label":"다","len":7,"off":3}],"grid":true}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_review_a#18','math',2,1,'u4','','g2_1_math_u4_review_a','unit_review','M2-1-u4-C4',3,'error','auto','친구들이 자 위에 놓인 크레파스의 길이를 말했어요. 크레파스는 4부터 10까지에 놓여 있어요. 잘못 말한 친구는 누구인가요?',ARRAY['M2-1-u4-X08','M2-1-u4-X15']::text[],false,'{"seq":18,"concept":"M2-1-u4-C4","difficulty":3,"kind":"error","stem":"친구들이 자 위에 놓인 크레파스의 길이를 말했어요. 크레파스는 4부터 10까지에 놓여 있어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"은솔 — 「10 cm야.」","correct":true,"mis_target":"M2-1-u4-X08"},{"t":"지호 — 「1 cm 칸이 6번이니 6 cm야.」","mis":"M2-1-u4-X15"},{"t":"아린 — 「10 − 4 = 6, 6 cm야.」","mis":"M2-1-u4-X15"}],"explanation":["4부터 10까지는 1 cm가 6번이에요.","끝 숫자 10을 그대로 읽으면 안 돼요.","나머지 두 친구는 바르게 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_review_a#19','math',2,1,'u4','','g2_1_math_u4_review_a','unit_review','M2-1-u4-C5',3,'mc','auto','종이띠의 길이는 약 몇 cm일까요?',ARRAY['M2-1-u4-X08','M2-1-u4-X11']::text[],true,'{"seq":19,"concept":"M2-1-u4-C5","difficulty":3,"kind":"mc","stem":"종이띠의 길이는 약 몇 cm일까요?","explanation":["3부터 세면 끝이 6칸과 7칸 사이에 있어요.","6에 더 가까우니 약 6 cm예요.","눈금 사이에 있으면 가까운 쪽 숫자를 읽고 「약」을 붙여요."],"variant_rule":{"cm":{"ask":"approx","off":true}},"options":[{"t":"약 6 cm","correct":true},{"t":"약 9 cm","mis":"M2-1-u4-X08"},{"t":"약 7 cm","mis":"M2-1-u4-X11"}],"asset":{"type":"ruler","len":6.2,"label":"종이띠","s":3}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_review_a#20','math',2,1,'u4','','g2_1_math_u4_review_a','unit_review','M2-1-u4-C2',3,'mc','auto','같은 클립으로 가는 5번, 나는 7번 재었어요. 더 긴 것은 어느 것인가요?',ARRAY['M2-1-u4-X04','M2-1-u4-X05']::text[],false,'{"seq":20,"concept":"M2-1-u4-C2","difficulty":3,"kind":"mc","stem":"같은 클립으로 가는 5번, 나는 7번 재었어요. 더 긴 것은 어느 것인가요?","options":[{"t":"나","correct":true},{"t":"가","mis":"M2-1-u4-X04"},{"t":"길이가 같아요","mis":"M2-1-u4-X05"}],"explanation":["같은 단위로 재었어요.","같은 단위라면 횟수가 많을수록 더 길어요.","나가 7번으로 더 길어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_review_a#21','math',2,1,'u4','','g2_1_math_u4_review_a','unit_review','M2-1-u4-C6',3,'mc','auto','실제 길이가 9 cm인 리본을 지안이는 약 8 cm, 도윤이는 약 12 cm로 어림했어요. 실제 길이에 더 가깝게 어림한 친구는 누구인가요?',ARRAY['M2-1-u4-X15','M2-1-u4-X14']::text[],false,'{"seq":21,"concept":"M2-1-u4-C6","difficulty":3,"kind":"mc","stem":"실제 길이가 9 cm인 리본을 지안이는 약 8 cm, 도윤이는 약 12 cm로 어림했어요. 실제 길이에 더 가깝게 어림한 친구는 누구인가요?","options":[{"t":"지안","correct":true},{"t":"도윤","mis":"M2-1-u4-X15"},{"t":"두 친구 모두 똑같이 가까워요","mis":"M2-1-u4-X14"}],"explanation":["지안이는 1 cm 차이예요.","도윤이는 3 cm 차이예요.","차이가 작은 쪽이 더 가깝게 어림한 거예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_review_a#22','math',2,1,'u4','','g2_1_math_u4_review_a','unit_review','M2-1-u4-C4',3,'mc','auto','막대가 자의 눈금 2부터 8까지에 놓여 있어요. 길이는 몇 cm일까요?',ARRAY['M2-1-u4-X08','M2-1-u4-X09']::text[],false,'{"seq":22,"concept":"M2-1-u4-C4","difficulty":3,"kind":"mc","stem":"막대가 자의 눈금 2부터 8까지에 놓여 있어요. 길이는 몇 cm일까요?","options":[{"t":"6 cm","correct":true},{"t":"8 cm","mis":"M2-1-u4-X08"},{"t":"7 cm","mis":"M2-1-u4-X09"}],"explanation":["2부터 8까지 1 cm 칸을 세요.","1 cm가 6번이에요.","그래서 6 cm예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_review_a#23','math',2,1,'u4','','g2_1_math_u4_review_a','unit_review','M2-1-u4-C4',4,'mc','auto','가 막대는 자의 0부터 7까지, 나 막대는 3부터 11까지에 놓여 있어요. 바르게 말한 것은 어느 것인가요?',ARRAY['M2-1-u4-X08','M2-1-u4-X15']::text[],false,'{"seq":23,"concept":"M2-1-u4-C4","difficulty":4,"kind":"mc","stem":"가 막대는 자의 0부터 7까지, 나 막대는 3부터 11까지에 놓여 있어요. 바르게 말한 것은 어느 것인가요?","options":[{"t":"나가 가보다 1 cm 더 길어요","correct":true},{"t":"나가 가보다 4 cm 더 길어요","mis":"M2-1-u4-X08"},{"t":"가가 나보다 더 길어요","mis":"M2-1-u4-X15"}],"explanation":["가는 7 cm예요.","나는 3부터 11까지 칸을 세면 8 cm예요.","8 cm와 7 cm의 차이는 1 cm예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_review_a#24','math',2,1,'u4','','g2_1_math_u4_review_a','unit_review','M2-1-u4-C5',4,'essay','teacher','그림의 연필 길이를 「약 몇 cm」로 말하고, 그렇게 읽은 방법을 설명해 보세요.','{}'::text[],false,'{"seq":24,"concept":"M2-1-u4-C5","difficulty":4,"kind":"essay","stem":"그림의 연필 길이를 「약 몇 cm」로 말하고, 그렇게 읽은 방법을 설명해 보세요.","answer_guide":{"answer":"예: 약 7 cm. 연필 끝이 눈금 7과 8 사이에 있는데 7에 더 가깝다. 그래서 7을 읽고 딱 맞지 않으니 「약」을 붙인다.","scoring_points":["약 7 cm라고 답했는가","끝이 어느 두 눈금 사이이며 어디에 더 가까운지 썼는가","딱 맞지 않아 「약」을 붙인다고 썼는가"]},"explanation":["약 7 cm예요.","7에 더 가까워요.","「약」을 붙여요."],"asset":{"type":"ruler","len":7.3,"label":"연필"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_review_a#25','math',2,1,'u4','','g2_1_math_u4_review_a','unit_review','M2-1-u4-C6',4,'essay','teacher','필통의 길이를 몸의 기준으로 어림하는 방법을 쓰고, 어림이 맞았는지 확인하는 방법도 써 보세요.','{}'::text[],false,'{"seq":25,"concept":"M2-1-u4-C6","difficulty":4,"kind":"essay","stem":"필통의 길이를 몸의 기준으로 어림하는 방법을 쓰고, 어림이 맞았는지 확인하는 방법도 써 보세요.","answer_guide":{"answer":"예: 한 뼘(약 10 cm)보다 조금 더 길어서 약 12 cm로 어림한다. 그다음 자로 재어 어림한 길이와 견준다.","scoring_points":["물건을 정하고 몸의 기준을 골랐는가","기준이 몇 번쯤인지 견주어 「약 몇 cm」로 어림했는가","자로 재어 확인하는 방법까지 썼는가"]},"explanation":["기준 고르기.","약 몇 cm.","자로 확인."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_review_b#1','math',2,1,'u4','','g2_1_math_u4_review_b','unit_review','M2-1-u4-C1',1,'mc','auto','끈으로 본뜬 세 길이를 왼쪽 끝을 맞춰 놓았어요. 가장 긴 것은 어느 것인가요?',ARRAY['M2-1-u4-X15','M2-1-u4-X01']::text[],false,'{"seq":1,"concept":"M2-1-u4-C1","difficulty":1,"kind":"mc","stem":"끈으로 본뜬 세 길이를 왼쪽 끝을 맞춰 놓았어요. 가장 긴 것은 어느 것인가요?","options":[{"t":"가","correct":true},{"t":"다","mis":"M2-1-u4-X15"},{"t":"나","mis":"M2-1-u4-X01"}],"explanation":["왼쪽 끝이 맞추어져 있어요.","가장 많이 나온 가가 가장 길어요.","다는 가장 짧아요."],"asset":{"type":"len_bars","rows":[{"label":"가","len":10},{"label":"나","len":7},{"label":"다","len":4}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_review_b#2','math',2,1,'u4','','g2_1_math_u4_review_b','unit_review','M2-1-u4-C2',1,'mc','auto','같은 길이를 잴 때 단위의 길이가 짧을수록 잰 횟수는 어떻게 될까요?',ARRAY['M2-1-u4-X04','M2-1-u4-X05']::text[],false,'{"seq":2,"concept":"M2-1-u4-C2","difficulty":1,"kind":"mc","stem":"같은 길이를 잴 때 단위의 길이가 짧을수록 잰 횟수는 어떻게 될까요?","options":[{"t":"많아져요","correct":true},{"t":"적어져요","mis":"M2-1-u4-X04"},{"t":"언제나 똑같아요","mis":"M2-1-u4-X05"}],"explanation":["짧은 단위는 한 번에 조금씩 재요.","긴 단위는 횟수가 적고, 짧은 단위는 횟수가 많아요.","같은 길이를 잴 때의 약속이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_review_b#3','math',2,1,'u4','','g2_1_math_u4_review_b','unit_review','M2-1-u4-C3',1,'mc','auto','「4 센티미터」를 바르게 쓴 것은 어느 것인가요?',ARRAY['M2-1-u4-X07']::text[],false,'{"seq":3,"concept":"M2-1-u4-C3","difficulty":1,"kind":"mc","stem":"「4 센티미터」를 바르게 쓴 것은 어느 것인가요?","options":[{"t":"4 cm","correct":true},{"t":"4 m","mis":"M2-1-u4-X07"},{"t":"4 c","mis":"M2-1-u4-X07"}],"explanation":["cm는 센티미터라고 읽어요.","4 센티미터는 4 cm라고 써요.","미터(m)는 다른 단위예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_review_b#4','math',2,1,'u4','','g2_1_math_u4_review_b','unit_review','M2-1-u4-C4',1,'mc','auto','연필의 길이는 몇 cm일까요?',ARRAY['M2-1-u4-X09','M2-1-u4-X10']::text[],true,'{"seq":4,"concept":"M2-1-u4-C4","difficulty":1,"kind":"mc","stem":"연필의 길이는 몇 cm일까요?","explanation":["연필의 한쪽 끝이 눈금 0에 맞춰져 있어요.","다른 쪽 끝의 눈금이 9이니 9 cm예요.","자의 숫자는 1 cm가 몇 번인지를 나타내요."],"variant_rule":{"cm":{"ask":"read"}},"options":[{"t":"9 cm","correct":true},{"t":"10 cm","mis":"M2-1-u4-X09"},{"t":"8 cm","mis":"M2-1-u4-X10"}],"asset":{"type":"ruler","len":9,"label":"연필"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_review_b#5','math',2,1,'u4','','g2_1_math_u4_review_b','unit_review','M2-1-u4-C3',1,'mc','auto','1 cm가 몇 번일까요? 종이띠의 길이는 몇 cm일까요?',ARRAY['M2-1-u4-X09','M2-1-u4-X03']::text[],true,'{"seq":5,"concept":"M2-1-u4-C3","difficulty":1,"kind":"mc","stem":"1 cm가 몇 번일까요? 종이띠의 길이는 몇 cm일까요?","explanation":["1 cm 칸을 하나씩 세면 8칸이에요.","1 cm가 8번이면 8 cm예요.","칸 사이의 선이 아니라 칸을 세어요."],"variant_rule":{"cm":{"ask":"cells"}},"options":[{"t":"8 cm","correct":true},{"t":"9 cm","mis":"M2-1-u4-X09"},{"t":"7 cm","mis":"M2-1-u4-X03"}],"asset":{"type":"ruler","len":8,"label":"종이띠","mode":"cells"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_review_b#6','math',2,1,'u4','','g2_1_math_u4_review_b','unit_review','M2-1-u4-C4',1,'mc','auto','자로 길이를 잴 때 물건의 한쪽 끝을 어느 눈금에 맞추나요?',ARRAY['M2-1-u4-X10','M2-1-u4-X08']::text[],false,'{"seq":6,"concept":"M2-1-u4-C4","difficulty":1,"kind":"mc","stem":"자로 길이를 잴 때 물건의 한쪽 끝을 어느 눈금에 맞추나요?","options":[{"t":"0","correct":true},{"t":"1","mis":"M2-1-u4-X10"},{"t":"아무 곳이나","mis":"M2-1-u4-X08"}],"explanation":["물건의 끝을 0에 맞춰요.","물건 한쪽 끝을 0에 맞추고 다른 끝 눈금을 읽어요.","0에 없으면 1 cm 칸을 세요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_review_b#7','math',2,1,'u4','','g2_1_math_u4_review_b','unit_review','M2-1-u4-C5',1,'mc','auto','끝이 눈금 8과 9 사이에 있고 9에 더 가까워요. 길이를 바르게 말한 것은 어느 것인가요?',ARRAY['M2-1-u4-X11','M2-1-u4-X12']::text[],false,'{"seq":7,"concept":"M2-1-u4-C5","difficulty":1,"kind":"mc","stem":"끝이 눈금 8과 9 사이에 있고 9에 더 가까워요. 길이를 바르게 말한 것은 어느 것인가요?","options":[{"t":"약 9 cm","correct":true},{"t":"약 8 cm","mis":"M2-1-u4-X11"},{"t":"9 cm","mis":"M2-1-u4-X12"}],"explanation":["끝에서 더 가까운 눈금을 찾아요.","9에 더 가까워 약 9 cm예요.","딱 맞지 않으면 「약」을 붙여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_review_b#8','math',2,1,'u4','','g2_1_math_u4_review_b','unit_review','M2-1-u4-C6',1,'mc','auto','가운뎃손가락의 길이는 약 몇 cm일까요?',ARRAY['M2-1-u4-X14']::text[],false,'{"seq":8,"concept":"M2-1-u4-C6","difficulty":1,"kind":"mc","stem":"가운뎃손가락의 길이는 약 몇 cm일까요?","options":[{"t":"약 5 cm","correct":true},{"t":"약 1 cm","mis":"M2-1-u4-X14"},{"t":"약 50 cm","mis":"M2-1-u4-X14"}],"explanation":["가운뎃손가락은 약 5 cm예요.","엄지손톱 약 1 cm, 가운뎃손가락 약 5 cm, 한 뼘 약 10 cm예요.","기준을 알면 어림할 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_review_b#9','math',2,1,'u4','','g2_1_math_u4_review_b','unit_review','M2-1-u4-C1',2,'ox','auto','오른쪽 끝이 더 나온 끈이 언제나 더 길어요.',ARRAY['M2-1-u4-X01']::text[],false,'{"seq":9,"concept":"M2-1-u4-C1","difficulty":2,"kind":"ox","stem":"오른쪽 끝이 더 나온 끈이 언제나 더 길어요.","answer":"X","reason_options":[{"t":"왼쪽 끝이 맞지 않으면 더 나와도 짧을 수 있으니까","correct":true},{"t":"더 나온 쪽이 기니까","mis":"M2-1-u4-X01"}],"mis":"M2-1-u4-X01","explanation":["시작점이 다르면 눈이 속아요.","왼쪽 끝을 맞추어 다시 봐요.","본뜬 것은 한쪽 끝을 맞추어 비교해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_review_b#10','math',2,1,'u4','','g2_1_math_u4_review_b','unit_review','M2-1-u4-C2',2,'mc','auto','종이띠의 길이는 지우개로 몇 번일까요?',ARRAY['M2-1-u4-X03']::text[],true,'{"seq":10,"concept":"M2-1-u4-C2","difficulty":2,"kind":"mc","stem":"종이띠의 길이는 지우개로 몇 번일까요?","explanation":["지우개를 빈틈없이 이어 놓은 것을 세어요.","지우개로 4번이에요.","겹치거나 띄우지 않고 이어서 세어요."],"variant_rule":{"cm":{"ask":"unit"}},"options":[{"t":"4번","correct":true},{"t":"5번","mis":"M2-1-u4-X03"},{"t":"3번","mis":"M2-1-u4-X03"}],"asset":{"type":"ruler","len":12,"label":"종이띠","mode":"unit","unit":"🟫","size":3}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_review_b#11','math',2,1,'u4','','g2_1_math_u4_review_b','unit_review','M2-1-u4-C4',2,'sa','auto','크레파스가 자의 눈금 0에 놓여 있지 않아요. 크레파스의 길이는 몇 cm일까요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":11,"concept":"M2-1-u4-C4","difficulty":2,"kind":"sa","stem":"크레파스가 자의 눈금 0에 놓여 있지 않아요. 크레파스의 길이는 몇 cm일까요? 숫자로 쓰세요.","explanation":["3부터 8까지 1 cm 칸을 세어요.","1 cm가 5번이니 5 cm예요.","끝 눈금 숫자 8을 그대로 읽으면 안 돼요."],"variant_rule":{"cm":{"ask":"off"}},"answer":["5"],"asset":{"type":"ruler","len":5,"label":"크레파스","s":3}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_review_b#12','math',2,1,'u4','','g2_1_math_u4_review_b','unit_review','M2-1-u4-C5',2,'mc','auto','연필의 길이는 약 몇 cm일까요?',ARRAY['M2-1-u4-X11','M2-1-u4-X12']::text[],true,'{"seq":12,"concept":"M2-1-u4-C5","difficulty":2,"kind":"mc","stem":"연필의 길이는 약 몇 cm일까요?","explanation":["끝이 눈금 8과 9 사이에 있어요.","9에 더 가까우니 약 9 cm예요.","눈금 사이에 있으면 가까운 쪽 숫자를 읽고 「약」을 붙여요."],"variant_rule":{"cm":{"ask":"approx"}},"options":[{"t":"약 9 cm","correct":true},{"t":"약 8 cm","mis":"M2-1-u4-X11"},{"t":"9 cm","mis":"M2-1-u4-X12"}],"asset":{"type":"ruler","len":8.8,"label":"연필"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_review_b#13','math',2,1,'u4','','g2_1_math_u4_review_b','unit_review','M2-1-u4-C2',2,'mc','auto','서윤이는 창문을 클립으로 9번, 하준이는 다른 창문을 지우개로 5번 재었어요. 어느 창문이 더 긴지 바르게 말한 것은 어느 것인가요?',ARRAY['M2-1-u4-X05','M2-1-u4-X04']::text[],false,'{"seq":13,"concept":"M2-1-u4-C2","difficulty":2,"kind":"mc","stem":"서윤이는 창문을 클립으로 9번, 하준이는 다른 창문을 지우개로 5번 재었어요. 어느 창문이 더 긴지 바르게 말한 것은 어느 것인가요?","options":[{"t":"단위가 달라서 횟수만으로는 알 수 없어요","correct":true},{"t":"9번인 서윤이의 창문이 더 길어요","mis":"M2-1-u4-X05"},{"t":"지우개가 더 짧으니 하준이의 창문이 더 길어요","mis":"M2-1-u4-X04"}],"explanation":["두 친구가 쓴 단위가 달라요.","단위가 다르면 횟수만 보고 길이를 견줄 수 없어요.","같은 단위로 재어야 비교할 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_review_b#14','math',2,1,'u4','','g2_1_math_u4_review_b','unit_review','M2-1-u4-C3',2,'sa','auto','1 cm가 12번이면 몇 cm일까요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":14,"concept":"M2-1-u4-C3","difficulty":2,"kind":"sa","stem":"1 cm가 12번이면 몇 cm일까요? 숫자로 쓰세요.","answer":["12"],"explanation":["1 cm가 몇 번인지 세면 길이예요.","1 cm가 12번이면 12 cm예요.","12 센티미터라고 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_review_b#15','math',2,1,'u4','','g2_1_math_u4_review_b','unit_review','M2-1-u4-C6',2,'mc','auto','리본이 한 뼘(약 10 cm)의 두 배쯤 되어 보여요. 길이를 어떻게 어림할까요?',ARRAY['M2-1-u4-X14','M2-1-u4-X05']::text[],false,'{"seq":15,"concept":"M2-1-u4-C6","difficulty":2,"kind":"mc","stem":"리본이 한 뼘(약 10 cm)의 두 배쯤 되어 보여요. 길이를 어떻게 어림할까요?","options":[{"t":"약 20 cm","correct":true},{"t":"약 12 cm","mis":"M2-1-u4-X14"},{"t":"약 2 cm","mis":"M2-1-u4-X05"}],"explanation":["한 뼘은 약 10 cm예요.","10 cm가 2번이면 약 20 cm예요.","기준이 몇 번쯤인지 견주어 어림해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_review_b#16','math',2,1,'u4','','g2_1_math_u4_review_b','unit_review','M2-1-u4-C5',2,'ox','auto','길이가 눈금 사이에 있으면 숫자 앞에 「약」을 붙여 말해요.',ARRAY['M2-1-u4-X12']::text[],false,'{"seq":16,"concept":"M2-1-u4-C5","difficulty":2,"kind":"ox","stem":"길이가 눈금 사이에 있으면 숫자 앞에 「약」을 붙여 말해요.","answer":"O","reason_options":[{"t":"눈금에 딱 맞지 않은 길이라는 뜻이니까","correct":true},{"t":"숫자만 말하면 되니까","mis":"M2-1-u4-X12"}],"mis":"M2-1-u4-X12","explanation":["딱 맞지 않으면 「약」을 붙여요.","예: 약 6 cm","「약」은 딱 맞지 않을 때 붙여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_review_b#17','math',2,1,'u4','','g2_1_math_u4_review_b','unit_review','M2-1-u4-C1',3,'mc','auto','세 종이띠를 놓았어요. 가장 긴 것은 어느 것인가요? (칸 하나의 길이는 같아요.)',ARRAY['M2-1-u4-X01','M2-1-u4-X15']::text[],false,'{"seq":17,"concept":"M2-1-u4-C1","difficulty":3,"kind":"mc","stem":"세 종이띠를 놓았어요. 가장 긴 것은 어느 것인가요? (칸 하나의 길이는 같아요.)","options":[{"t":"나","correct":true},{"t":"가","mis":"M2-1-u4-X01"},{"t":"다","mis":"M2-1-u4-X15"}],"explanation":["세 종이띠의 시작점이 달라요.","칸을 세면 가 5칸, 나 7칸, 다 4칸이에요.","오른쪽 끝이 가장 많이 나온 것이 가장 긴 것이 아니에요."],"asset":{"type":"len_bars","rows":[{"label":"가","len":5,"off":4},{"label":"나","len":7},{"label":"다","len":4,"off":3}],"grid":true}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_review_b#18','math',2,1,'u4','','g2_1_math_u4_review_b','unit_review','M2-1-u4-C4',3,'error','auto','친구들이 자 위에 놓인 리본의 길이를 말했어요. 리본은 3부터 9까지에 놓여 있어요. 잘못 말한 친구는 누구인가요?',ARRAY['M2-1-u4-X08','M2-1-u4-X15']::text[],false,'{"seq":18,"concept":"M2-1-u4-C4","difficulty":3,"kind":"error","stem":"친구들이 자 위에 놓인 리본의 길이를 말했어요. 리본은 3부터 9까지에 놓여 있어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"태민 — 「9 cm야.」","correct":true,"mis_target":"M2-1-u4-X08"},{"t":"하람 — 「1 cm 칸이 6번이니 6 cm야.」","mis":"M2-1-u4-X15"},{"t":"서아 — 「9 − 3 = 6, 6 cm야.」","mis":"M2-1-u4-X15"}],"explanation":["3부터 9까지는 1 cm가 6번이에요.","끝 숫자 9를 그대로 읽으면 안 돼요.","나머지 두 친구는 바르게 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_review_b#19','math',2,1,'u4','','g2_1_math_u4_review_b','unit_review','M2-1-u4-C5',3,'mc','auto','막대의 길이는 약 몇 cm일까요?',ARRAY['M2-1-u4-X08','M2-1-u4-X11']::text[],true,'{"seq":19,"concept":"M2-1-u4-C5","difficulty":3,"kind":"mc","stem":"막대의 길이는 약 몇 cm일까요?","explanation":["2부터 세면 끝이 6칸과 5칸 사이에 있어요.","6에 더 가까우니 약 6 cm예요.","눈금 사이에 있으면 가까운 쪽 숫자를 읽고 「약」을 붙여요."],"variant_rule":{"cm":{"ask":"approx","off":true}},"options":[{"t":"약 6 cm","correct":true},{"t":"약 8 cm","mis":"M2-1-u4-X08"},{"t":"약 5 cm","mis":"M2-1-u4-X11"}],"asset":{"type":"ruler","len":5.8,"label":"막대","s":2}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_review_b#20','math',2,1,'u4','','g2_1_math_u4_review_b','unit_review','M2-1-u4-C2',3,'mc','auto','같은 지우개로 가는 9번, 나는 6번 재었어요. 더 긴 것은 어느 것인가요?',ARRAY['M2-1-u4-X04','M2-1-u4-X05']::text[],false,'{"seq":20,"concept":"M2-1-u4-C2","difficulty":3,"kind":"mc","stem":"같은 지우개로 가는 9번, 나는 6번 재었어요. 더 긴 것은 어느 것인가요?","options":[{"t":"가","correct":true},{"t":"나","mis":"M2-1-u4-X04"},{"t":"길이가 같아요","mis":"M2-1-u4-X05"}],"explanation":["같은 단위로 재었어요.","같은 단위라면 횟수가 많을수록 더 길어요.","가가 9번으로 더 길어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_review_b#21','math',2,1,'u4','','g2_1_math_u4_review_b','unit_review','M2-1-u4-C6',3,'mc','auto','실제 길이가 12 cm인 연필을 하린이는 약 13 cm, 준우는 약 9 cm로 어림했어요. 실제 길이에 더 가깝게 어림한 친구는 누구인가요?',ARRAY['M2-1-u4-X15','M2-1-u4-X14']::text[],false,'{"seq":21,"concept":"M2-1-u4-C6","difficulty":3,"kind":"mc","stem":"실제 길이가 12 cm인 연필을 하린이는 약 13 cm, 준우는 약 9 cm로 어림했어요. 실제 길이에 더 가깝게 어림한 친구는 누구인가요?","options":[{"t":"하린","correct":true},{"t":"준우","mis":"M2-1-u4-X15"},{"t":"두 친구 모두 똑같이 가까워요","mis":"M2-1-u4-X14"}],"explanation":["하린이는 1 cm 차이예요.","준우는 3 cm 차이예요.","차이가 작은 쪽이 더 가깝게 어림한 거예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_review_b#22','math',2,1,'u4','','g2_1_math_u4_review_b','unit_review','M2-1-u4-C4',3,'mc','auto','리본이 자의 눈금 3부터 10까지에 놓여 있어요. 길이는 몇 cm일까요?',ARRAY['M2-1-u4-X08','M2-1-u4-X09']::text[],false,'{"seq":22,"concept":"M2-1-u4-C4","difficulty":3,"kind":"mc","stem":"리본이 자의 눈금 3부터 10까지에 놓여 있어요. 길이는 몇 cm일까요?","options":[{"t":"7 cm","correct":true},{"t":"10 cm","mis":"M2-1-u4-X08"},{"t":"8 cm","mis":"M2-1-u4-X09"}],"explanation":["3부터 10까지 1 cm 칸을 세요.","1 cm가 7번이에요.","그래서 7 cm예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_review_b#23','math',2,1,'u4','','g2_1_math_u4_review_b','unit_review','M2-1-u4-C4',4,'mc','auto','가 리본은 자의 0부터 9까지, 나 리본은 2부터 8까지에 놓여 있어요. 바르게 말한 것은 어느 것인가요?',ARRAY['M2-1-u4-X08','M2-1-u4-X15']::text[],false,'{"seq":23,"concept":"M2-1-u4-C4","difficulty":4,"kind":"mc","stem":"가 리본은 자의 0부터 9까지, 나 리본은 2부터 8까지에 놓여 있어요. 바르게 말한 것은 어느 것인가요?","options":[{"t":"가가 나보다 3 cm 더 길어요","correct":true},{"t":"가가 나보다 1 cm 더 길어요","mis":"M2-1-u4-X08"},{"t":"나가 가보다 더 길어요","mis":"M2-1-u4-X15"}],"explanation":["가는 9 cm예요.","나는 2부터 8까지 칸을 세면 6 cm예요.","9 cm와 6 cm의 차이는 3 cm예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_review_b#24','math',2,1,'u4','','g2_1_math_u4_review_b','unit_review','M2-1-u4-C5',4,'essay','teacher','그림의 막대 길이를 「약 몇 cm」로 말하고, 그렇게 읽은 방법을 설명해 보세요.','{}'::text[],false,'{"seq":24,"concept":"M2-1-u4-C5","difficulty":4,"kind":"essay","stem":"그림의 막대 길이를 「약 몇 cm」로 말하고, 그렇게 읽은 방법을 설명해 보세요.","answer_guide":{"answer":"예: 약 6 cm. 막대 끝이 눈금 5와 6 사이에 있는데 6에 더 가깝다. 그래서 6을 읽고 딱 맞지 않으니 「약」을 붙인다.","scoring_points":["약 6 cm라고 답했는가","끝이 어느 두 눈금 사이이며 어디에 더 가까운지 썼는가","딱 맞지 않아 「약」을 붙인다고 썼는가"]},"explanation":["약 6 cm예요.","6에 더 가까워요.","「약」을 붙여요."],"asset":{"type":"ruler","len":5.8,"label":"막대"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_review_b#25','math',2,1,'u4','','g2_1_math_u4_review_b','unit_review','M2-1-u4-C6',4,'essay','teacher','수학책 짧은 쪽의 길이를 몸의 기준으로 어림하는 방법을 쓰고, 어림이 맞았는지 확인하는 방법도 써 보세요.','{}'::text[],false,'{"seq":25,"concept":"M2-1-u4-C6","difficulty":4,"kind":"essay","stem":"수학책 짧은 쪽의 길이를 몸의 기준으로 어림하는 방법을 쓰고, 어림이 맞았는지 확인하는 방법도 써 보세요.","answer_guide":{"answer":"예: 한 뼘(약 10 cm)과 가운뎃손가락(약 5 cm)을 이은 만큼쯤이라 약 15 cm로 어림한다. 자로 재어 견준다.","scoring_points":["물건을 정하고 몸의 기준을 골랐는가","기준이 몇 번쯤인지 견주어 「약 몇 cm」로 어림했는가","자로 재어 확인하는 방법까지 썼는가"]},"explanation":["기준 고르기.","약 몇 cm.","자로 확인."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_review_c#1','math',2,1,'u4','','g2_1_math_u4_review_c','unit_review','M2-1-u4-C1',1,'mc','auto','끈으로 본뜬 세 길이를 왼쪽 끝을 맞춰 놓았어요. 가장 긴 것은 어느 것인가요?',ARRAY['M2-1-u4-X15','M2-1-u4-X01']::text[],false,'{"seq":1,"concept":"M2-1-u4-C1","difficulty":1,"kind":"mc","stem":"끈으로 본뜬 세 길이를 왼쪽 끝을 맞춰 놓았어요. 가장 긴 것은 어느 것인가요?","options":[{"t":"나","correct":true},{"t":"가","mis":"M2-1-u4-X15"},{"t":"다","mis":"M2-1-u4-X01"}],"explanation":["왼쪽 끝이 맞추어져 있어요.","가장 많이 나온 나가 가장 길어요.","가는 가장 짧아요."],"asset":{"type":"len_bars","rows":[{"label":"가","len":2},{"label":"나","len":8},{"label":"다","len":5}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_review_c#2','math',2,1,'u4','','g2_1_math_u4_review_c','unit_review','M2-1-u4-C2',1,'mc','auto','같은 책상을 클립과 뼘으로 재었어요. 잰 횟수가 더 적은 것은 어느 것인가요?',ARRAY['M2-1-u4-X04','M2-1-u4-X05']::text[],false,'{"seq":2,"concept":"M2-1-u4-C2","difficulty":1,"kind":"mc","stem":"같은 책상을 클립과 뼘으로 재었어요. 잰 횟수가 더 적은 것은 어느 것인가요?","options":[{"t":"뼘","correct":true},{"t":"클립","mis":"M2-1-u4-X04"},{"t":"똑같아요","mis":"M2-1-u4-X05"}],"explanation":["뼘이 클립보다 긴 단위예요.","긴 단위는 횟수가 적고, 짧은 단위는 횟수가 많아요.","같은 길이를 잴 때의 약속이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_review_c#3','math',2,1,'u4','','g2_1_math_u4_review_c','unit_review','M2-1-u4-C3',1,'mc','auto','9 cm는 무엇이라고 읽나요?',ARRAY['M2-1-u4-X07']::text[],false,'{"seq":3,"concept":"M2-1-u4-C3","difficulty":1,"kind":"mc","stem":"9 cm는 무엇이라고 읽나요?","options":[{"t":"9 센티미터","correct":true},{"t":"9 미터","mis":"M2-1-u4-X07"},{"t":"9 칸","mis":"M2-1-u4-X07"}],"explanation":["cm는 센티미터라고 읽어요.","9 cm는 9 센티미터예요.","미터(m)는 다른 단위예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_review_c#4','math',2,1,'u4','','g2_1_math_u4_review_c','unit_review','M2-1-u4-C4',1,'mc','auto','지우개의 길이는 몇 cm일까요?',ARRAY['M2-1-u4-X09','M2-1-u4-X10']::text[],true,'{"seq":4,"concept":"M2-1-u4-C4","difficulty":1,"kind":"mc","stem":"지우개의 길이는 몇 cm일까요?","explanation":["지우개의 한쪽 끝이 눈금 0에 맞춰져 있어요.","다른 쪽 끝의 눈금이 5이니 5 cm예요.","자의 숫자는 1 cm가 몇 번인지를 나타내요."],"variant_rule":{"cm":{"ask":"read"}},"options":[{"t":"5 cm","correct":true},{"t":"6 cm","mis":"M2-1-u4-X09"},{"t":"4 cm","mis":"M2-1-u4-X10"}],"asset":{"type":"ruler","len":5,"label":"지우개"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_review_c#5','math',2,1,'u4','','g2_1_math_u4_review_c','unit_review','M2-1-u4-C3',1,'mc','auto','1 cm가 몇 번일까요? 리본의 길이는 몇 cm일까요?',ARRAY['M2-1-u4-X09','M2-1-u4-X03']::text[],true,'{"seq":5,"concept":"M2-1-u4-C3","difficulty":1,"kind":"mc","stem":"1 cm가 몇 번일까요? 리본의 길이는 몇 cm일까요?","explanation":["1 cm 칸을 하나씩 세면 4칸이에요.","1 cm가 4번이면 4 cm예요.","칸 사이의 선이 아니라 칸을 세어요."],"variant_rule":{"cm":{"ask":"cells"}},"options":[{"t":"4 cm","correct":true},{"t":"5 cm","mis":"M2-1-u4-X09"},{"t":"3 cm","mis":"M2-1-u4-X03"}],"asset":{"type":"ruler","len":4,"label":"리본","mode":"cells"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_review_c#6','math',2,1,'u4','','g2_1_math_u4_review_c','unit_review','M2-1-u4-C4',1,'mc','auto','자의 숫자 6은 무엇을 뜻할까요?',ARRAY['M2-1-u4-X10','M2-1-u4-X09']::text[],false,'{"seq":6,"concept":"M2-1-u4-C4","difficulty":1,"kind":"mc","stem":"자의 숫자 6은 무엇을 뜻할까요?","options":[{"t":"0부터 1 cm가 6번이라는 뜻","correct":true},{"t":"물건이 6개라는 뜻","mis":"M2-1-u4-X10"},{"t":"눈금 선이 6개라는 뜻","mis":"M2-1-u4-X09"}],"explanation":["자의 숫자는 1 cm가 몇 번인지예요.","물건 한쪽 끝을 0에 맞추고 다른 끝 눈금을 읽어요.","0에 없으면 1 cm 칸을 세요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_review_c#7','math',2,1,'u4','','g2_1_math_u4_review_c','unit_review','M2-1-u4-C5',1,'mc','auto','끝이 눈금 2와 3 사이에 있고 3에 더 가까워요. 길이를 바르게 말한 것은 어느 것인가요?',ARRAY['M2-1-u4-X11','M2-1-u4-X12']::text[],false,'{"seq":7,"concept":"M2-1-u4-C5","difficulty":1,"kind":"mc","stem":"끝이 눈금 2와 3 사이에 있고 3에 더 가까워요. 길이를 바르게 말한 것은 어느 것인가요?","options":[{"t":"약 3 cm","correct":true},{"t":"약 2 cm","mis":"M2-1-u4-X11"},{"t":"3 cm","mis":"M2-1-u4-X12"}],"explanation":["끝에서 더 가까운 눈금을 찾아요.","3에 더 가까워 약 3 cm예요.","딱 맞지 않으면 「약」을 붙여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_review_c#8','math',2,1,'u4','','g2_1_math_u4_review_c','unit_review','M2-1-u4-C6',1,'mc','auto','2학년 어린이의 한 뼘은 약 몇 cm일까요?',ARRAY['M2-1-u4-X14']::text[],false,'{"seq":8,"concept":"M2-1-u4-C6","difficulty":1,"kind":"mc","stem":"2학년 어린이의 한 뼘은 약 몇 cm일까요?","options":[{"t":"약 10 cm","correct":true},{"t":"약 1 cm","mis":"M2-1-u4-X14"},{"t":"약 50 cm","mis":"M2-1-u4-X14"}],"explanation":["한 뼘은 약 10 cm쯤이에요.","엄지손톱 약 1 cm, 가운뎃손가락 약 5 cm, 한 뼘 약 10 cm예요.","기준을 알면 어림할 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_review_c#9','math',2,1,'u4','','g2_1_math_u4_review_c','unit_review','M2-1-u4-C1',2,'ox','auto','본뜬 끈은 끝을 맞추지 않고 비교해도 정확해요.',ARRAY['M2-1-u4-X01']::text[],false,'{"seq":9,"concept":"M2-1-u4-C1","difficulty":2,"kind":"ox","stem":"본뜬 끈은 끝을 맞추지 않고 비교해도 정확해요.","answer":"X","reason_options":[{"t":"시작점이 다르면 길이를 잘못 볼 수 있으니까","correct":true},{"t":"끈의 길이는 그대로이니까","mis":"M2-1-u4-X01"}],"mis":"M2-1-u4-X01","explanation":["끝을 맞추지 않으면 정확하지 않아요.","한쪽 끝을 맞춰요.","본뜬 것은 한쪽 끝을 맞추어 비교해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_review_c#10','math',2,1,'u4','','g2_1_math_u4_review_c','unit_review','M2-1-u4-C2',2,'mc','auto','리본의 길이는 블록으로 몇 번일까요?',ARRAY['M2-1-u4-X03']::text[],true,'{"seq":10,"concept":"M2-1-u4-C2","difficulty":2,"kind":"mc","stem":"리본의 길이는 블록으로 몇 번일까요?","explanation":["블록을 빈틈없이 이어 놓은 것을 세어요.","블록으로 7번이에요.","겹치거나 띄우지 않고 이어서 세어요."],"variant_rule":{"cm":{"ask":"unit"}},"options":[{"t":"7번","correct":true},{"t":"8번","mis":"M2-1-u4-X03"},{"t":"6번","mis":"M2-1-u4-X03"}],"asset":{"type":"ruler","len":7,"label":"리본","mode":"unit","unit":"🧩","size":1}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_review_c#11','math',2,1,'u4','','g2_1_math_u4_review_c','unit_review','M2-1-u4-C4',2,'sa','auto','막대가 자의 눈금 0에 놓여 있지 않아요. 막대의 길이는 몇 cm일까요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":11,"concept":"M2-1-u4-C4","difficulty":2,"kind":"sa","stem":"막대가 자의 눈금 0에 놓여 있지 않아요. 막대의 길이는 몇 cm일까요? 숫자로 쓰세요.","explanation":["1부터 8까지 1 cm 칸을 세어요.","1 cm가 7번이니 7 cm예요.","끝 눈금 숫자 8을 그대로 읽으면 안 돼요."],"variant_rule":{"cm":{"ask":"off"}},"answer":["7"],"asset":{"type":"ruler","len":7,"label":"막대","s":1}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_review_c#12','math',2,1,'u4','','g2_1_math_u4_review_c','unit_review','M2-1-u4-C5',2,'mc','auto','열쇠의 길이는 약 몇 cm일까요?',ARRAY['M2-1-u4-X11','M2-1-u4-X12']::text[],true,'{"seq":12,"concept":"M2-1-u4-C5","difficulty":2,"kind":"mc","stem":"열쇠의 길이는 약 몇 cm일까요?","explanation":["끝이 눈금 4와 5 사이에 있어요.","4에 더 가까우니 약 4 cm예요.","눈금 사이에 있으면 가까운 쪽 숫자를 읽고 「약」을 붙여요."],"variant_rule":{"cm":{"ask":"approx"}},"options":[{"t":"약 4 cm","correct":true},{"t":"약 5 cm","mis":"M2-1-u4-X11"},{"t":"4 cm","mis":"M2-1-u4-X12"}],"asset":{"type":"ruler","len":4.3,"label":"열쇠"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_review_c#13','math',2,1,'u4','','g2_1_math_u4_review_c','unit_review','M2-1-u4-C2',2,'mc','auto','지후는 칠판을 걸음으로 3번, 예린이는 다른 칠판을 뼘으로 20번 재었어요. 어느 칠판이 더 긴지 바르게 말한 것은 어느 것인가요?',ARRAY['M2-1-u4-X05','M2-1-u4-X04']::text[],false,'{"seq":13,"concept":"M2-1-u4-C2","difficulty":2,"kind":"mc","stem":"지후는 칠판을 걸음으로 3번, 예린이는 다른 칠판을 뼘으로 20번 재었어요. 어느 칠판이 더 긴지 바르게 말한 것은 어느 것인가요?","options":[{"t":"단위가 달라서 횟수만으로는 알 수 없어요","correct":true},{"t":"20번인 예린이의 칠판이 더 길어요","mis":"M2-1-u4-X05"},{"t":"걸음이 더 짧으니 지후의 칠판이 더 길어요","mis":"M2-1-u4-X04"}],"explanation":["두 친구가 쓴 단위가 달라요.","단위가 다르면 횟수만 보고 길이를 견줄 수 없어요.","같은 단위로 재어야 비교할 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_review_c#14','math',2,1,'u4','','g2_1_math_u4_review_c','unit_review','M2-1-u4-C3',2,'sa','auto','1 cm가 9번이면 몇 cm일까요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":14,"concept":"M2-1-u4-C3","difficulty":2,"kind":"sa","stem":"1 cm가 9번이면 몇 cm일까요? 숫자로 쓰세요.","answer":["9"],"explanation":["1 cm가 몇 번인지 세면 길이예요.","1 cm가 9번이면 9 cm예요.","9 센티미터라고 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_review_c#15','math',2,1,'u4','','g2_1_math_u4_review_c','unit_review','M2-1-u4-C6',2,'mc','auto','끈이 가운뎃손가락(약 5 cm)의 세 배쯤 되어 보여요. 길이를 어떻게 어림할까요?',ARRAY['M2-1-u4-X14','M2-1-u4-X05']::text[],false,'{"seq":15,"concept":"M2-1-u4-C6","difficulty":2,"kind":"mc","stem":"끈이 가운뎃손가락(약 5 cm)의 세 배쯤 되어 보여요. 길이를 어떻게 어림할까요?","options":[{"t":"약 15 cm","correct":true},{"t":"약 8 cm","mis":"M2-1-u4-X14"},{"t":"약 3 cm","mis":"M2-1-u4-X05"}],"explanation":["가운뎃손가락은 약 5 cm예요.","5 cm가 3번이면 약 15 cm예요.","기준이 몇 번쯤인지 견주어 어림해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_review_c#16','math',2,1,'u4','','g2_1_math_u4_review_c','unit_review','M2-1-u4-C5',2,'ox','auto','약 8 cm인 리본 두 개를 맞대어 보면 길이가 조금 다를 수도 있어요.',ARRAY['M2-1-u4-X13']::text[],false,'{"seq":16,"concept":"M2-1-u4-C5","difficulty":2,"kind":"ox","stem":"약 8 cm인 리본 두 개를 맞대어 보면 길이가 조금 다를 수도 있어요.","answer":"O","reason_options":[{"t":"둘 다 8 가까이일 뿐 똑같다는 뜻은 아니니까","correct":true},{"t":"약 8 cm면 모두 8 cm이니까","mis":"M2-1-u4-X13"}],"mis":"M2-1-u4-X13","explanation":["약 8 cm는 8에 가깝다는 뜻이에요.","조금 짧거나 길 수 있어요.","「약」은 딱 맞지 않을 때 붙여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_review_c#17','math',2,1,'u4','','g2_1_math_u4_review_c','unit_review','M2-1-u4-C1',3,'mc','auto','세 종이띠를 놓았어요. 가장 긴 것은 어느 것인가요? (칸 하나의 길이는 같아요.)',ARRAY['M2-1-u4-X01','M2-1-u4-X15']::text[],false,'{"seq":17,"concept":"M2-1-u4-C1","difficulty":3,"kind":"mc","stem":"세 종이띠를 놓았어요. 가장 긴 것은 어느 것인가요? (칸 하나의 길이는 같아요.)","options":[{"t":"다","correct":true},{"t":"나","mis":"M2-1-u4-X01"},{"t":"가","mis":"M2-1-u4-X15"}],"explanation":["세 종이띠의 시작점이 달라요.","칸을 세면 가 6칸, 나 5칸, 다 8칸이에요.","오른쪽 끝이 가장 많이 나온 것이 가장 긴 것이 아니에요."],"asset":{"type":"len_bars","rows":[{"label":"가","len":6,"off":1},{"label":"나","len":5,"off":4},{"label":"다","len":8}],"grid":true}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_review_c#18','math',2,1,'u4','','g2_1_math_u4_review_c','unit_review','M2-1-u4-C4',3,'error','auto','친구들이 자 위에 놓인 막대의 길이를 말했어요. 막대는 2부터 8까지에 놓여 있어요. 잘못 말한 친구는 누구인가요?',ARRAY['M2-1-u4-X08','M2-1-u4-X15']::text[],false,'{"seq":18,"concept":"M2-1-u4-C4","difficulty":3,"kind":"error","stem":"친구들이 자 위에 놓인 막대의 길이를 말했어요. 막대는 2부터 8까지에 놓여 있어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"민호 — 「8 cm야.」","correct":true,"mis_target":"M2-1-u4-X08"},{"t":"소율 — 「1 cm 칸이 6번이니 6 cm야.」","mis":"M2-1-u4-X15"},{"t":"준우 — 「8 − 2 = 6, 6 cm야.」","mis":"M2-1-u4-X15"}],"explanation":["2부터 8까지는 1 cm가 6번이에요.","끝 숫자 8을 그대로 읽으면 안 돼요.","나머지 두 친구는 바르게 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_review_c#19','math',2,1,'u4','','g2_1_math_u4_review_c','unit_review','M2-1-u4-C5',3,'mc','auto','리본의 길이는 약 몇 cm일까요?',ARRAY['M2-1-u4-X08','M2-1-u4-X12']::text[],true,'{"seq":19,"concept":"M2-1-u4-C5","difficulty":3,"kind":"mc","stem":"리본의 길이는 약 몇 cm일까요?","explanation":["1부터 세면 끝이 7칸과 8칸 사이에 있어요.","7에 더 가까우니 약 7 cm예요.","눈금 사이에 있으면 가까운 쪽 숫자를 읽고 「약」을 붙여요."],"variant_rule":{"cm":{"ask":"approx","off":true}},"options":[{"t":"약 7 cm","correct":true},{"t":"약 8 cm","mis":"M2-1-u4-X08"},{"t":"7 cm","mis":"M2-1-u4-X12"}],"asset":{"type":"ruler","len":7.3,"label":"리본","s":1}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_review_c#20','math',2,1,'u4','','g2_1_math_u4_review_c','unit_review','M2-1-u4-C2',3,'mc','auto','같은 블록으로 가는 4번, 나는 11번 재었어요. 더 긴 것은 어느 것인가요?',ARRAY['M2-1-u4-X04','M2-1-u4-X05']::text[],false,'{"seq":20,"concept":"M2-1-u4-C2","difficulty":3,"kind":"mc","stem":"같은 블록으로 가는 4번, 나는 11번 재었어요. 더 긴 것은 어느 것인가요?","options":[{"t":"나","correct":true},{"t":"가","mis":"M2-1-u4-X04"},{"t":"길이가 같아요","mis":"M2-1-u4-X05"}],"explanation":["같은 단위로 재었어요.","같은 단위라면 횟수가 많을수록 더 길어요.","나가 11번으로 더 길어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_review_c#21','math',2,1,'u4','','g2_1_math_u4_review_c','unit_review','M2-1-u4-C6',3,'mc','auto','실제 길이가 6 cm인 지우개를 서아는 약 7 cm, 태민이는 약 9 cm로 어림했어요. 실제 길이에 더 가깝게 어림한 친구는 누구인가요?',ARRAY['M2-1-u4-X15','M2-1-u4-X14']::text[],false,'{"seq":21,"concept":"M2-1-u4-C6","difficulty":3,"kind":"mc","stem":"실제 길이가 6 cm인 지우개를 서아는 약 7 cm, 태민이는 약 9 cm로 어림했어요. 실제 길이에 더 가깝게 어림한 친구는 누구인가요?","options":[{"t":"서아","correct":true},{"t":"태민","mis":"M2-1-u4-X15"},{"t":"두 친구 모두 똑같이 가까워요","mis":"M2-1-u4-X14"}],"explanation":["서아는 1 cm 차이예요.","태민이는 3 cm 차이예요.","차이가 작은 쪽이 더 가깝게 어림한 거예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_review_c#22','math',2,1,'u4','','g2_1_math_u4_review_c','unit_review','M2-1-u4-C4',3,'mc','auto','끈이 자의 눈금 5부터 9까지에 놓여 있어요. 길이는 몇 cm일까요?',ARRAY['M2-1-u4-X08','M2-1-u4-X09']::text[],false,'{"seq":22,"concept":"M2-1-u4-C4","difficulty":3,"kind":"mc","stem":"끈이 자의 눈금 5부터 9까지에 놓여 있어요. 길이는 몇 cm일까요?","options":[{"t":"4 cm","correct":true},{"t":"9 cm","mis":"M2-1-u4-X08"},{"t":"5 cm","mis":"M2-1-u4-X09"}],"explanation":["5부터 9까지 1 cm 칸을 세요.","1 cm가 4번이에요.","그래서 4 cm예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_review_c#23','math',2,1,'u4','','g2_1_math_u4_review_c','unit_review','M2-1-u4-C4',4,'mc','auto','가 끈은 자의 0부터 5까지, 나 끈은 4부터 12까지에 놓여 있어요. 바르게 말한 것은 어느 것인가요?',ARRAY['M2-1-u4-X08','M2-1-u4-X15']::text[],false,'{"seq":23,"concept":"M2-1-u4-C4","difficulty":4,"kind":"mc","stem":"가 끈은 자의 0부터 5까지, 나 끈은 4부터 12까지에 놓여 있어요. 바르게 말한 것은 어느 것인가요?","options":[{"t":"나가 가보다 3 cm 더 길어요","correct":true},{"t":"나가 가보다 7 cm 더 길어요","mis":"M2-1-u4-X08"},{"t":"가가 나보다 더 길어요","mis":"M2-1-u4-X15"}],"explanation":["가는 5 cm예요.","나는 4부터 12까지 칸을 세면 8 cm예요.","8 cm와 5 cm의 차이는 3 cm예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_review_c#24','math',2,1,'u4','','g2_1_math_u4_review_c','unit_review','M2-1-u4-C5',4,'essay','teacher','그림의 붓 길이를 「약 몇 cm」로 말하고, 그렇게 읽은 방법을 설명해 보세요.','{}'::text[],false,'{"seq":24,"concept":"M2-1-u4-C5","difficulty":4,"kind":"essay","stem":"그림의 붓 길이를 「약 몇 cm」로 말하고, 그렇게 읽은 방법을 설명해 보세요.","answer_guide":{"answer":"예: 약 9 cm. 붓 끝이 눈금 9와 10 사이에 있는데 9에 더 가깝다. 그래서 9를 읽고 딱 맞지 않으니 「약」을 붙인다.","scoring_points":["약 9 cm라고 답했는가","끝이 어느 두 눈금 사이이며 어디에 더 가까운지 썼는가","딱 맞지 않아 「약」을 붙인다고 썼는가"]},"explanation":["약 9 cm예요.","9에 더 가까워요.","「약」을 붙여요."],"asset":{"type":"ruler","len":9.2,"label":"붓"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_review_c#25','math',2,1,'u4','','g2_1_math_u4_review_c','unit_review','M2-1-u4-C6',4,'essay','teacher','크레파스의 길이를 몸의 기준으로 어림하는 방법을 쓰고, 어림이 맞았는지 확인하는 방법도 써 보세요.','{}'::text[],false,'{"seq":25,"concept":"M2-1-u4-C6","difficulty":4,"kind":"essay","stem":"크레파스의 길이를 몸의 기준으로 어림하는 방법을 쓰고, 어림이 맞았는지 확인하는 방법도 써 보세요.","answer_guide":{"answer":"예: 가운뎃손가락(약 5 cm)보다 조금 더 길어서 약 7 cm로 어림한다. 자로 재어 견준다.","scoring_points":["물건을 정하고 몸의 기준을 골랐는가","기준이 몇 번쯤인지 견주어 「약 몇 cm」로 어림했는가","자로 재어 확인하는 방법까지 썼는가"]},"explanation":["기준 고르기.","약 몇 cm.","자로 확인."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_review_d#1','math',2,1,'u4','','g2_1_math_u4_review_d','unit_review','M2-1-u4-C1',1,'mc','auto','끈으로 본뜬 세 길이를 왼쪽 끝을 맞춰 놓았어요. 가장 긴 것은 어느 것인가요?',ARRAY['M2-1-u4-X15','M2-1-u4-X01']::text[],false,'{"seq":1,"concept":"M2-1-u4-C1","difficulty":1,"kind":"mc","stem":"끈으로 본뜬 세 길이를 왼쪽 끝을 맞춰 놓았어요. 가장 긴 것은 어느 것인가요?","options":[{"t":"다","correct":true},{"t":"나","mis":"M2-1-u4-X15"},{"t":"가","mis":"M2-1-u4-X01"}],"explanation":["왼쪽 끝이 맞추어져 있어요.","가장 많이 나온 다가 가장 길어요.","나는 가장 짧아요."],"asset":{"type":"len_bars","rows":[{"label":"가","len":7},{"label":"나","len":4},{"label":"다","len":11}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_review_d#2','math',2,1,'u4','','g2_1_math_u4_review_d','unit_review','M2-1-u4-C2',1,'mc','auto','같은 칠판을 걸음과 뼘으로 재었어요. 잰 횟수가 더 많은 것은 어느 것인가요?',ARRAY['M2-1-u4-X04','M2-1-u4-X05']::text[],false,'{"seq":2,"concept":"M2-1-u4-C2","difficulty":1,"kind":"mc","stem":"같은 칠판을 걸음과 뼘으로 재었어요. 잰 횟수가 더 많은 것은 어느 것인가요?","options":[{"t":"뼘","correct":true},{"t":"걸음","mis":"M2-1-u4-X04"},{"t":"똑같아요","mis":"M2-1-u4-X05"}],"explanation":["뼘이 걸음보다 짧은 단위예요.","긴 단위는 횟수가 적고, 짧은 단위는 횟수가 많아요.","같은 길이를 잴 때의 약속이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_review_d#3','math',2,1,'u4','','g2_1_math_u4_review_d','unit_review','M2-1-u4-C3',1,'mc','auto','「12 센티미터」를 바르게 쓴 것은 어느 것인가요?',ARRAY['M2-1-u4-X07']::text[],false,'{"seq":3,"concept":"M2-1-u4-C3","difficulty":1,"kind":"mc","stem":"「12 센티미터」를 바르게 쓴 것은 어느 것인가요?","options":[{"t":"12 cm","correct":true},{"t":"12 m","mis":"M2-1-u4-X07"},{"t":"12 c","mis":"M2-1-u4-X07"}],"explanation":["cm는 센티미터라고 읽어요.","12 센티미터는 12 cm라고 써요.","미터(m)는 다른 단위예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_review_d#4','math',2,1,'u4','','g2_1_math_u4_review_d','unit_review','M2-1-u4-C4',1,'mc','auto','종이띠의 길이는 몇 cm일까요?',ARRAY['M2-1-u4-X09','M2-1-u4-X10']::text[],true,'{"seq":4,"concept":"M2-1-u4-C4","difficulty":1,"kind":"mc","stem":"종이띠의 길이는 몇 cm일까요?","explanation":["종이띠의 한쪽 끝이 눈금 0에 맞춰져 있어요.","다른 쪽 끝의 눈금이 10이니 10 cm예요.","자의 숫자는 1 cm가 몇 번인지를 나타내요."],"variant_rule":{"cm":{"ask":"read"}},"options":[{"t":"10 cm","correct":true},{"t":"11 cm","mis":"M2-1-u4-X09"},{"t":"9 cm","mis":"M2-1-u4-X10"}],"asset":{"type":"ruler","len":10,"label":"종이띠"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_review_d#5','math',2,1,'u4','','g2_1_math_u4_review_d','unit_review','M2-1-u4-C3',1,'mc','auto','1 cm가 몇 번일까요? 막대의 길이는 몇 cm일까요?',ARRAY['M2-1-u4-X09','M2-1-u4-X03']::text[],true,'{"seq":5,"concept":"M2-1-u4-C3","difficulty":1,"kind":"mc","stem":"1 cm가 몇 번일까요? 막대의 길이는 몇 cm일까요?","explanation":["1 cm 칸을 하나씩 세면 10칸이에요.","1 cm가 10번이면 10 cm예요.","칸 사이의 선이 아니라 칸을 세어요."],"variant_rule":{"cm":{"ask":"cells"}},"options":[{"t":"10 cm","correct":true},{"t":"11 cm","mis":"M2-1-u4-X09"},{"t":"9 cm","mis":"M2-1-u4-X03"}],"asset":{"type":"ruler","len":10,"label":"막대","mode":"cells"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_review_d#6','math',2,1,'u4','','g2_1_math_u4_review_d','unit_review','M2-1-u4-C4',1,'mc','auto','자로 길이를 재는 바른 방법은 어느 것인가요?',ARRAY['M2-1-u4-X10','M2-1-u4-X08']::text[],false,'{"seq":6,"concept":"M2-1-u4-C4","difficulty":1,"kind":"mc","stem":"자로 길이를 재는 바른 방법은 어느 것인가요?","options":[{"t":"물건 끝을 0에 맞추고 다른 끝 눈금을 읽어요","correct":true},{"t":"물건 끝을 1에 맞추고 다른 끝 눈금을 읽어요","mis":"M2-1-u4-X10"},{"t":"물건을 비스듬히 놓고 읽어요","mis":"M2-1-u4-X08"}],"explanation":["시작점은 0이에요.","물건 한쪽 끝을 0에 맞추고 다른 끝 눈금을 읽어요.","0에 없으면 1 cm 칸을 세요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_review_d#7','math',2,1,'u4','','g2_1_math_u4_review_d','unit_review','M2-1-u4-C5',1,'mc','auto','끝이 눈금 10과 11 사이에 있고 10에 더 가까워요. 길이를 바르게 말한 것은 어느 것인가요?',ARRAY['M2-1-u4-X11','M2-1-u4-X12']::text[],false,'{"seq":7,"concept":"M2-1-u4-C5","difficulty":1,"kind":"mc","stem":"끝이 눈금 10과 11 사이에 있고 10에 더 가까워요. 길이를 바르게 말한 것은 어느 것인가요?","options":[{"t":"약 10 cm","correct":true},{"t":"약 11 cm","mis":"M2-1-u4-X11"},{"t":"10 cm","mis":"M2-1-u4-X12"}],"explanation":["끝에서 더 가까운 눈금을 찾아요.","10에 더 가까워 약 10 cm예요.","딱 맞지 않으면 「약」을 붙여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_review_d#8','math',2,1,'u4','','g2_1_math_u4_review_d','unit_review','M2-1-u4-C6',1,'mc','auto','약 1 cm를 어림할 때 기준으로 쓰기 좋은 것은 어느 것인가요?',ARRAY['M2-1-u4-X14']::text[],false,'{"seq":8,"concept":"M2-1-u4-C6","difficulty":1,"kind":"mc","stem":"약 1 cm를 어림할 때 기준으로 쓰기 좋은 것은 어느 것인가요?","options":[{"t":"엄지손톱","correct":true},{"t":"한 뼘","mis":"M2-1-u4-X14"},{"t":"한 걸음","mis":"M2-1-u4-X14"}],"explanation":["엄지손톱이 약 1 cm예요.","엄지손톱 약 1 cm, 가운뎃손가락 약 5 cm, 한 뼘 약 10 cm예요.","기준을 알면 어림할 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_review_d#9','math',2,1,'u4','','g2_1_math_u4_review_d','unit_review','M2-1-u4-C1',2,'ox','auto','두 종이띠의 왼쪽 끝을 맞추면 더 많이 나온 쪽이 더 길어요.',ARRAY['M2-1-u4-X01']::text[],false,'{"seq":9,"concept":"M2-1-u4-C1","difficulty":2,"kind":"ox","stem":"두 종이띠의 왼쪽 끝을 맞추면 더 많이 나온 쪽이 더 길어요.","answer":"O","reason_options":[{"t":"시작점이 같으니 남는 만큼 더 기니까","correct":true},{"t":"종이띠 색깔을 봐야 하니까","mis":"M2-1-u4-X01"}],"mis":"M2-1-u4-X01","explanation":["시작점이 같아요.","그래서 더 나온 쪽이 더 길어요.","본뜬 것은 한쪽 끝을 맞추어 비교해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_review_d#10','math',2,1,'u4','','g2_1_math_u4_review_d','unit_review','M2-1-u4-C2',2,'mc','auto','연필의 길이는 클립으로 몇 번일까요?',ARRAY['M2-1-u4-X03']::text[],true,'{"seq":10,"concept":"M2-1-u4-C2","difficulty":2,"kind":"mc","stem":"연필의 길이는 클립으로 몇 번일까요?","explanation":["클립을 빈틈없이 이어 놓은 것을 세어요.","클립으로 3번이에요.","겹치거나 띄우지 않고 이어서 세어요."],"variant_rule":{"cm":{"ask":"unit"}},"options":[{"t":"3번","correct":true},{"t":"4번","mis":"M2-1-u4-X03"},{"t":"2번","mis":"M2-1-u4-X03"}],"asset":{"type":"ruler","len":6,"label":"연필","mode":"unit","unit":"📎","size":2}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_review_d#11','math',2,1,'u4','','g2_1_math_u4_review_d','unit_review','M2-1-u4-C4',2,'sa','auto','지우개가 자의 눈금 0에 놓여 있지 않아요. 지우개의 길이는 몇 cm일까요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":11,"concept":"M2-1-u4-C4","difficulty":2,"kind":"sa","stem":"지우개가 자의 눈금 0에 놓여 있지 않아요. 지우개의 길이는 몇 cm일까요? 숫자로 쓰세요.","explanation":["4부터 8까지 1 cm 칸을 세어요.","1 cm가 4번이니 4 cm예요.","끝 눈금 숫자 8을 그대로 읽으면 안 돼요."],"variant_rule":{"cm":{"ask":"off"}},"answer":["4"],"asset":{"type":"ruler","len":4,"label":"지우개","s":4}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_review_d#12','math',2,1,'u4','','g2_1_math_u4_review_d','unit_review','M2-1-u4-C5',2,'mc','auto','붓의 길이는 약 몇 cm일까요?',ARRAY['M2-1-u4-X11','M2-1-u4-X12']::text[],true,'{"seq":12,"concept":"M2-1-u4-C5","difficulty":2,"kind":"mc","stem":"붓의 길이는 약 몇 cm일까요?","explanation":["끝이 눈금 9와 10 사이에 있어요.","10에 더 가까우니 약 10 cm예요.","눈금 사이에 있으면 가까운 쪽 숫자를 읽고 「약」을 붙여요."],"variant_rule":{"cm":{"ask":"approx"}},"options":[{"t":"약 10 cm","correct":true},{"t":"약 9 cm","mis":"M2-1-u4-X11"},{"t":"10 cm","mis":"M2-1-u4-X12"}],"asset":{"type":"ruler","len":9.7,"label":"붓"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_review_d#13','math',2,1,'u4','','g2_1_math_u4_review_d','unit_review','M2-1-u4-C2',2,'mc','auto','하늘이는 끈을 블록으로 10번, 도담이는 다른 끈을 클립으로 7번 재었어요. 어느 끈이 더 긴지 바르게 말한 것은 어느 것인가요?',ARRAY['M2-1-u4-X05','M2-1-u4-X04']::text[],false,'{"seq":13,"concept":"M2-1-u4-C2","difficulty":2,"kind":"mc","stem":"하늘이는 끈을 블록으로 10번, 도담이는 다른 끈을 클립으로 7번 재었어요. 어느 끈이 더 긴지 바르게 말한 것은 어느 것인가요?","options":[{"t":"단위가 달라서 횟수만으로는 알 수 없어요","correct":true},{"t":"10번인 하늘이의 끈이 더 길어요","mis":"M2-1-u4-X05"},{"t":"클립이 더 짧으니 도담이의 끈이 더 길어요","mis":"M2-1-u4-X04"}],"explanation":["두 친구가 쓴 단위가 달라요.","단위가 다르면 횟수만 보고 길이를 견줄 수 없어요.","같은 단위로 재어야 비교할 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_review_d#14','math',2,1,'u4','','g2_1_math_u4_review_d','unit_review','M2-1-u4-C3',2,'sa','auto','1 cm가 14번이면 몇 cm일까요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":14,"concept":"M2-1-u4-C3","difficulty":2,"kind":"sa","stem":"1 cm가 14번이면 몇 cm일까요? 숫자로 쓰세요.","answer":["14"],"explanation":["1 cm가 몇 번인지 세면 길이예요.","1 cm가 14번이면 14 cm예요.","14 센티미터라고 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_review_d#15','math',2,1,'u4','','g2_1_math_u4_review_d','unit_review','M2-1-u4-C6',2,'mc','auto','지우개가 엄지손톱(약 1 cm)의 네 배쯤 되어 보여요. 길이를 어떻게 어림할까요?',ARRAY['M2-1-u4-X14','M2-1-u4-X05']::text[],false,'{"seq":15,"concept":"M2-1-u4-C6","difficulty":2,"kind":"mc","stem":"지우개가 엄지손톱(약 1 cm)의 네 배쯤 되어 보여요. 길이를 어떻게 어림할까요?","options":[{"t":"약 4 cm","correct":true},{"t":"약 40 cm","mis":"M2-1-u4-X14"},{"t":"약 5 cm","mis":"M2-1-u4-X05"}],"explanation":["엄지손톱은 약 1 cm예요.","1 cm가 4번이면 약 4 cm예요.","기준이 몇 번쯤인지 견주어 어림해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_review_d#16','math',2,1,'u4','','g2_1_math_u4_review_d','unit_review','M2-1-u4-C5',2,'ox','auto','눈금 사이에 있는 길이는 더 먼 눈금의 숫자를 읽어요.',ARRAY['M2-1-u4-X11']::text[],false,'{"seq":16,"concept":"M2-1-u4-C5","difficulty":2,"kind":"ox","stem":"눈금 사이에 있는 길이는 더 먼 눈금의 숫자를 읽어요.","answer":"X","reason_options":[{"t":"더 가까운 눈금의 숫자를 읽으니까","correct":true},{"t":"먼 쪽이 더 크니까","mis":"M2-1-u4-X11"}],"mis":"M2-1-u4-X11","explanation":["가까운 쪽 숫자를 읽어요.","그리고 「약」을 붙여요.","「약」은 딱 맞지 않을 때 붙여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_review_d#17','math',2,1,'u4','','g2_1_math_u4_review_d','unit_review','M2-1-u4-C1',3,'mc','auto','세 종이띠를 놓았어요. 가장 긴 것은 어느 것인가요? (칸 하나의 길이는 같아요.)',ARRAY['M2-1-u4-X01','M2-1-u4-X15']::text[],false,'{"seq":17,"concept":"M2-1-u4-C1","difficulty":3,"kind":"mc","stem":"세 종이띠를 놓았어요. 가장 긴 것은 어느 것인가요? (칸 하나의 길이는 같아요.)","options":[{"t":"가","correct":true},{"t":"나","mis":"M2-1-u4-X01"},{"t":"다","mis":"M2-1-u4-X15"}],"explanation":["세 종이띠의 시작점이 달라요.","칸을 세면 가 9칸, 나 7칸, 다 5칸이에요.","오른쪽 끝이 가장 많이 나온 것이 가장 긴 것이 아니에요."],"asset":{"type":"len_bars","rows":[{"label":"가","len":9},{"label":"나","len":7,"off":3},{"label":"다","len":5,"off":2}],"grid":true}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_review_d#18','math',2,1,'u4','','g2_1_math_u4_review_d','unit_review','M2-1-u4-C4',3,'error','auto','친구들이 자 위에 놓인 종이띠의 길이를 말했어요. 종이띠는 1부터 7까지에 놓여 있어요. 잘못 말한 친구는 누구인가요?',ARRAY['M2-1-u4-X08','M2-1-u4-X15']::text[],false,'{"seq":18,"concept":"M2-1-u4-C4","difficulty":3,"kind":"error","stem":"친구들이 자 위에 놓인 종이띠의 길이를 말했어요. 종이띠는 1부터 7까지에 놓여 있어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"도윤 — 「7 cm야.」","correct":true,"mis_target":"M2-1-u4-X08"},{"t":"예린 — 「1 cm 칸이 6번이니 6 cm야.」","mis":"M2-1-u4-X15"},{"t":"지안 — 「7 − 1 = 6, 6 cm야.」","mis":"M2-1-u4-X15"}],"explanation":["1부터 7까지는 1 cm가 6번이에요.","끝 숫자 7을 그대로 읽으면 안 돼요.","나머지 두 친구는 바르게 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_review_d#19','math',2,1,'u4','','g2_1_math_u4_review_d','unit_review','M2-1-u4-C5',3,'mc','auto','크레파스의 길이는 약 몇 cm일까요?',ARRAY['M2-1-u4-X08','M2-1-u4-X11']::text[],true,'{"seq":19,"concept":"M2-1-u4-C5","difficulty":3,"kind":"mc","stem":"크레파스의 길이는 약 몇 cm일까요?","explanation":["4부터 세면 끝이 5칸과 4칸 사이에 있어요.","5에 더 가까우니 약 5 cm예요.","눈금 사이에 있으면 가까운 쪽 숫자를 읽고 「약」을 붙여요."],"variant_rule":{"cm":{"ask":"approx","off":true}},"options":[{"t":"약 5 cm","correct":true},{"t":"약 9 cm","mis":"M2-1-u4-X08"},{"t":"약 4 cm","mis":"M2-1-u4-X11"}],"asset":{"type":"ruler","len":4.7,"label":"크레파스","s":4}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_review_d#20','math',2,1,'u4','','g2_1_math_u4_review_d','unit_review','M2-1-u4-C2',3,'mc','auto','같은 뼘으로 가는 8번, 나는 5번 재었어요. 더 긴 것은 어느 것인가요?',ARRAY['M2-1-u4-X04','M2-1-u4-X05']::text[],false,'{"seq":20,"concept":"M2-1-u4-C2","difficulty":3,"kind":"mc","stem":"같은 뼘으로 가는 8번, 나는 5번 재었어요. 더 긴 것은 어느 것인가요?","options":[{"t":"가","correct":true},{"t":"나","mis":"M2-1-u4-X04"},{"t":"길이가 같아요","mis":"M2-1-u4-X05"}],"explanation":["같은 단위로 재었어요.","같은 단위라면 횟수가 많을수록 더 길어요.","가가 8번으로 더 길어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_review_d#21','math',2,1,'u4','','g2_1_math_u4_review_d','unit_review','M2-1-u4-C6',3,'mc','auto','실제 길이가 15 cm인 붓을 로아는 약 14 cm, 시우는 약 10 cm로 어림했어요. 실제 길이에 더 가깝게 어림한 친구는 누구인가요?',ARRAY['M2-1-u4-X15','M2-1-u4-X14']::text[],false,'{"seq":21,"concept":"M2-1-u4-C6","difficulty":3,"kind":"mc","stem":"실제 길이가 15 cm인 붓을 로아는 약 14 cm, 시우는 약 10 cm로 어림했어요. 실제 길이에 더 가깝게 어림한 친구는 누구인가요?","options":[{"t":"로아","correct":true},{"t":"시우","mis":"M2-1-u4-X15"},{"t":"두 친구 모두 똑같이 가까워요","mis":"M2-1-u4-X14"}],"explanation":["로아는 1 cm 차이예요.","시우는 5 cm 차이예요.","차이가 작은 쪽이 더 가깝게 어림한 거예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_review_d#22','math',2,1,'u4','','g2_1_math_u4_review_d','unit_review','M2-1-u4-C4',3,'mc','auto','종이띠가 자의 눈금 4부터 11까지에 놓여 있어요. 길이는 몇 cm일까요?',ARRAY['M2-1-u4-X08','M2-1-u4-X09']::text[],false,'{"seq":22,"concept":"M2-1-u4-C4","difficulty":3,"kind":"mc","stem":"종이띠가 자의 눈금 4부터 11까지에 놓여 있어요. 길이는 몇 cm일까요?","options":[{"t":"7 cm","correct":true},{"t":"11 cm","mis":"M2-1-u4-X08"},{"t":"8 cm","mis":"M2-1-u4-X09"}],"explanation":["4부터 11까지 1 cm 칸을 세요.","1 cm가 7번이에요.","그래서 7 cm예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_review_d#23','math',2,1,'u4','','g2_1_math_u4_review_d','unit_review','M2-1-u4-C4',4,'mc','auto','가 종이띠는 자의 0부터 10까지, 나 종이띠는 1부터 8까지에 놓여 있어요. 바르게 말한 것은 어느 것인가요?',ARRAY['M2-1-u4-X08','M2-1-u4-X15']::text[],false,'{"seq":23,"concept":"M2-1-u4-C4","difficulty":4,"kind":"mc","stem":"가 종이띠는 자의 0부터 10까지, 나 종이띠는 1부터 8까지에 놓여 있어요. 바르게 말한 것은 어느 것인가요?","options":[{"t":"가가 나보다 3 cm 더 길어요","correct":true},{"t":"가가 나보다 2 cm 더 길어요","mis":"M2-1-u4-X08"},{"t":"나가 가보다 더 길어요","mis":"M2-1-u4-X15"}],"explanation":["가는 10 cm예요.","나는 1부터 8까지 칸을 세면 7 cm예요.","10 cm와 7 cm의 차이는 3 cm예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_review_d#24','math',2,1,'u4','','g2_1_math_u4_review_d','unit_review','M2-1-u4-C5',4,'essay','teacher','그림의 리본 길이를 「약 몇 cm」로 말하고, 그렇게 읽은 방법을 설명해 보세요.','{}'::text[],false,'{"seq":24,"concept":"M2-1-u4-C5","difficulty":4,"kind":"essay","stem":"그림의 리본 길이를 「약 몇 cm」로 말하고, 그렇게 읽은 방법을 설명해 보세요.","answer_guide":{"answer":"예: 약 9 cm. 리본 끝이 눈금 8과 9 사이에 있는데 9에 더 가깝다. 그래서 9를 읽고 딱 맞지 않으니 「약」을 붙인다.","scoring_points":["약 9 cm라고 답했는가","끝이 어느 두 눈금 사이이며 어디에 더 가까운지 썼는가","딱 맞지 않아 「약」을 붙인다고 썼는가"]},"explanation":["약 9 cm예요.","9에 더 가까워요.","「약」을 붙여요."],"asset":{"type":"ruler","len":8.7,"label":"리본"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_math_u4_review_d#25','math',2,1,'u4','','g2_1_math_u4_review_d','unit_review','M2-1-u4-C6',4,'essay','teacher','지우개의 길이를 몸의 기준으로 어림하는 방법을 쓰고, 어림이 맞았는지 확인하는 방법도 써 보세요.','{}'::text[],false,'{"seq":25,"concept":"M2-1-u4-C6","difficulty":4,"kind":"essay","stem":"지우개의 길이를 몸의 기준으로 어림하는 방법을 쓰고, 어림이 맞았는지 확인하는 방법도 써 보세요.","answer_guide":{"answer":"예: 엄지손톱(약 1 cm) 4개만큼쯤이라 약 4 cm로 어림한다. 자로 재어 견준다.","scoring_points":["물건을 정하고 몸의 기준을 골랐는가","기준이 몇 번쯤인지 견주어 「약 몇 cm」로 어림했는가","자로 재어 확인하는 방법까지 썼는가"]},"explanation":["기준 고르기.","약 몇 cm.","자로 확인."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
